/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040826-14","meetingId":"h16-cm08","date":"2004年8月26日","dateIso":"2004-08-26","committee":"行財政改革特別委員会","time":"午後１時０４分～午後３時１６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"行財政改革に関することのうち、有料施設の有効活用に関すること","agenda":"行財政改革に関することのうち、有料施設の有効活用に関すること","exchanges":[{"speaker":"山村副委員長","kind":"質問","question":"資料の１０ページに品川健康センターがホールと会議室になっているんですけれども、これも委託先がコナミスポーツと考えて当然よろしいんですか。そこがよくわからないんですが。","respondent":"田中健康課長","answer":"同じように、ここも予約、それから収納も含めて委託をしています。","voiceIndex":7,"id":"exchange-001"},{"speaker":"山村副委員長","kind":"質問","question":"それからあと、会議室のほうなんですけれども、こちらの利用状況を考えて、こちらを例えばもっと健康施設関係のほうに変えるとか、そういうようなことは考えられたことがあるのか、それともこのまま会議室で使っていたほうが有効なのか、そこら辺のほうはどのように考えられていらっしゃるのか教えていただければ。","respondent":"田中健康課長","answer":"あそこの品川健康センターの会議室なんですが、ホールは先ほどもご説明申し上げましたとおり、ダンスですとか大きな集会ということなんですが、中規模のものがなかなかないという、すぐそばに区民集会所はあるので、そことの問題なんですが、この間。","voiceIndex":9,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"会議室と、それからホールのことだけですので、大きなくくりでお伺いしたいのが、コナミスポーツと委託契約を結んでいるわけですよね。ここで聞いていいと思うんですけれども、契約の仕方とか、それから税金の投入と費用対効果、そのメリットをどこへどういうふうに図っていらっしゃるかということをお伺いしたいんです。いかがでしょうか。","respondent":"田中健康課長","answer":"そういう意味では、一言で言えば、全体をうまく運用してほしいという契約自体をしてございまして、それから、平成１４年に、実はご存じかと思いますけれども、荏原健康センターを含めて事業者を一本化したプロポーザルを行いまして、ちょうど３年目に入ります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"その委託内容の見直しとか、それから、コナミが独自に事業をやっていく体制になっている部分と、でも最終的には品川区の施設ですから、どこかがそれをきちんと管理しなきゃいけない、その部分はどういうふうに持っていらっしゃるのかということをお伺いしたいのですが、いかがでしょうか。そのことについてどういうふうにされていくのでしょうかということをお聞かせください。","respondent":"田中健康課長","answer":"よくあそこで前衛生課長も実はとめに入ったらネクタイを、胸ぐらをつかまれたとか、そういう事件が多発しておりまして、それで、基本的には品川健康センターの利用者用のはございませんというのを軸にしてございまして、ただ。","voiceIndex":13,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それはそれでわかるんですね。おそらく、駐車場の規格としては当然クリアしているんでしょうけれども、今の大型の車が増えてくるとか、それからハイルーフと言いましたっけ、そういう車が入ると当然２台入らないとか、素人でもわかる話でありますので、そのことは今すぐとは言いませんけれども、将来に向けてもう少しハード的な整備をしていただければと思っているんですが、いかがでしょうか。","respondent":"田中健康課長","answer":"駐車場ですが、ほんとうにどこまでをどのようにという、有料化というお話が出たそうですので、私どももそれも一つ視野に入れまして、一応検討はしておるんですが、使い勝手というか、そのためにいろんな形の人的な操作をできる人ですとか、そういう問題をある程度。","voiceIndex":15,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問・要望","question":"品川第一区民集会所に比べると、あそこは９０名ですけれども、高いです。自転車で運ぶか、車をあそこへ持っていっておろして、１回家に帰って、もう１回自転車で行き直すというようなことを、搬入が必要なイベントの場合、そんなふうな利用をしているので、先ほどのご説明はるるわかりましたけれども、今後、この一般利用者２０台、１１台の分の仕分けをどうしていくのか、それも伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"要は、これが９０％になってしまいますと、多分もう身動きできない状態というか、かなり７５％でもとりづらいという状況ですので、これぐらいのがぎりぎりなのかなと。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、ほんとうはホールと会議室という問題になると思うので、今ちょっと質疑でおかしいなと。ですから、このホールと会議室に関して自由度というのはあるんでしょうか。例えば料金設定を変えたとか、そういう意味の自由度があるのかどうか。それから、コナミになる前の段階と、利用が変わって利用率が大きな変化があったのかどうか、そこら辺のところをちょっとお聞きしたいんですが。","respondent":"田中健康課長","answer":"ただ、施設予約システムがこの間入りましたので、そういう意味で、やわらかい対応といいますか、役所の職員がほとんどの施設は施設予約システムをやっているわけですけれども、あそこは唯一受付のコナミのスタッフがそういうふうにやってくれていますので、そういう点では。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それでちょっとただ、あの中で前にお聞きしたのは、一つ団体が借りていて、そこが名義を変えたいと言ったときに、もう１回借り直しになって料金を２度払わなきゃいけないというような状況を聞いたことがあるんですけれども、これは契約上の問題になっているのかどうか、その辺がちょっとわからないのと、それから、今お話があった施設予約システムになって、お金の管理は民間に任せている。","respondent":"田中健康課長","answer":"３階の会議室なんですが、確かにちょっとわかりにくい部分で、特に多分私どもの区の関係者も２階に実はさっき筋トレで使っている部屋をご覧いただきましたけれども、あそこは実は健康課が管理をしている。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に、今ご説明がありましたように、せっかくあれだけきれいなところの会議室なので、ぜひもっとアピールすれば利用度も上がるんじゃないかなと思いますので、その辺の知られるようにやっていただきたいと思います。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"川西委員","kind":"質問・要望","question":"施設予約と関係があるのかもしれないけれども、品川第一区民集会所を土曜日に予約を入れましたら入りまして、今日でも料金を支払いいいですよというふうに言われまして、えと思ったんですけれども、すぐ支払いを済ませたということで、これは便利になったなというふうに感じたんですけれども、品川第一区民集会所もコナミの人がお金を受け取ってくれるんですか。","respondent":"榎本行財政改革担当課長","answer":"予約してから７日以内に支払わないとキャンセル扱いになってしまうんですけれども、そのときにも、例えば品川健康センターで品川第一区民集会所を予約して、その場で品川第一区民集会所のお金を払えるという形になっております。全部支払いもできるような形になっております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"川西委員","kind":"意見","question":"普通のところは土曜日は支払いできないでしょう。品川健康センターの場合には、品川第一区民集会所が９０名の部屋ですけれども、あいていたので借りました。こっちの１５０名がだめなので。そして、できるだけ早く料金を払いたい、今日でもいいですよと言われて、こんな便利なことはないと、ここ数年の間で初めて思ったんです。","respondent":"榎本行財政改革担当課長","answer":"土・日あいているところについては共通でできるという形です。","voiceIndex":28,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5760#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":10754,"voices":31}},{"id":"h16-20040830-9","meetingId":"h16-cm08","date":"2004年8月30日","dateIso":"2004-08-30","committee":"文教委員会","time":"午後１時０４分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１７年度入学予定者の学校選択","agenda":"平成１７年度入学予定者の学校選択","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"先ほどの説明で、第二日野小学校の一貫校は仮設校舎の関係で１クラスというふうになっていたんですけれども、実際に一貫校が開設された場合には、１クラスずつで来ていると全体で３学級ですから、途中で全学年を募集するという格好になるのかということ。それから、１学級でした場合に、大体何名ぐらいが通学区域外の人が入れる余裕があるのかというのがわかったら教えてほしいんですけれども。","respondent":"谷田部学務課長","answer":"１点目の途中で全学年をということは、転校ということをするのかですけれども、あくまでも新１年生だけの希望申請ですから、例えば開校時点で小学校の場合には３学級ずつあります。第二日野小学校は１学級ずつしかありませんから、基本的には２学級余っている。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"１学年３学級を予定して、５年間は１学級というと、５×２で１０教室ぐらいが使われない格好になるんですけれども、なぜ当初で募集しないのか、何か混乱みたいなものが予想されるのか、ちょっと私は検討もつかないんですけれども、その考え方を教えてほしいんですが。","respondent":"谷田部学務課長、中島指導課長","answer":"転学の関係ですけれども、指導課長から教育上の問題等々ありますので、その辺はご説明申し上げますけれども、学級数についてはそのような考え方で決めさせていただいたです。一貫校におきましては、平成１８年度から移行に入っていきたいと考えておりますので、学年進行での内容を無理なく進めていきたいというふうに考えております。したがって、学年途中での募集という形は考えていないです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"今年でしょうか、小中の連携という形で組み合わせを小中学校の中で決められてということなんですが、多分そこをある程度考えながら今後小学校の入学の選択をされる保護者の方もいらっしゃると思うんですが、その辺の情報等については、今年の選択へ向かうにはされないのか、何もないということなのか、一貫教育が非常に危惧されているところがあります。","respondent":"谷田部学務課長、中島指導課長","answer":"３点のご質問のうち、１点目と３点目について、私のほうからお答えいたします。以前、こちらの文教委員会でも小中一貫教育の全校実施にあたりましては、小中学校の組み合わせの基本案を考えて。３点目の質問で、補足します。具体的に、ニコン跡地のマンションです。これは大井第一小学校の通学区域の中に含まれているです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"それを見越して、中学校のほうが数が少ないですから、そこを見て小学校を選択するとか、いろんな方法が出てきますので、関係ないというわけではなくて、むしろ関心が出てくる動きはあると思いますので、その辺の公表できる時期だけでも、どことどこの小学校と中学校が連携していくのかということがいつ頃公表されるのか、そのスケジュールがわかっている範囲でよろしいので教えていただきたいと思います。","respondent":"谷田部学務課長、中島指導課長","answer":"プレハブ校舎で児童には、もう１年新しい校舎ができるまで、現在のところで学んでいただきたいということで考えてありますので、増えたからといって、プレハブにまたプレハブをつくってというふうにはできませんので。こちらのほうの研究グループですけれども、その研究をやっていく中でさまざまな内容を見て、場合によっては入れ替えですとか見直し等を図りながら。","voiceIndex":14,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"最初に、裏面の希望申請開始の９月２４日からずっと時系がならんでいるんだけれども、対象になる方々への説明とか案内とか、そういうのは現段階ではどういう状況なんですか。","respondent":"谷田部学務課長","answer":"通常学級の全児童・生徒に対しては、９月２１日に「広報しながわ」を通じてお知らせし、またそれに合わせるような形で各家庭に希望申請の用紙、学校案内のパンフレット、必要な書類を郵送でお送りするという手続で、その段階が初めて広く周知することになるです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"小中一貫は品川区全体から入れるわけですよね。トラブルが起きるでしょう。なぜかといったら、既存の学校は１学年の入学だけというのは、もう既に徹底はされているだろうけれども、新しい学校ができるのに、なぜ２学年、３学年、４学年の子どもが入れないのかという理由がないでしょう。新しい学校ができるんだよ。それとも、あくまでも第二日野小学校と日野中学校なんですか、この小中一貫校というのは。","respondent":"谷田部学務課長","answer":"あくまでも、第二小学校と日野中学校が一つの建物で、９年間の一貫した教育を行うということですから、大井地区も原小学校と伊藤中学校の組み合わせで、同じような形態で行うという意味では、既存の小学校、中学校が形を変えて９年間の一貫教育をです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"そうしたら、ここに「便宜的に、１～６年生を一貫小学校、７～９年生を一貫中学校と標記する」と書く必要ないじゃないですか。便宜的に何よりも、「これは第二日野小学校と日野中学校です」と書けばいいじゃないですか、違いますか。","respondent":"谷田部学務課長","answer":"ただ、説明する上では、よりわかりやすく、私どもはこのような形でさせていただいたという便宜的なものですので、よろしくご理解のほどをお願いします。","voiceIndex":21,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"あくまでも第二日野小学校と日野中学校なら、そう書けばいいじゃないですか。名称がまだ決まっていないというわけじゃないですか。そうすると、平成１８年度から５カ年は、各学年に１クラスが出てきて、３クラスの学年とどういう共通課題で、総合的学習というのは全く違う学習方法にならざるを得ないじゃないですか。そこの子どもたちの５年間、６年間というのは、どう担保していくんですか。","respondent":"中島指導課長","answer":"平成１８年度からの小中一貫校も、その内容を以降に入っていくわけですけれども、例えば市民科ですとかステップアップ学習、こういったような内容は、その子どもたちの学級数に係わらず方法として実施されていくことになりますので。","voiceIndex":23,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"シミュレーションしてくださいよ。新しい学年が入ってきて３クラス、計算しやすく言うと１００人ぐらい規模の子どもたちがいる。片や２０人ぐらいの学年がある。小中一貫をどうやってスムーズに指導していくんですか。平成１７年４月、６歳じゃないと小中一貫校には入れない。第二日野小学校を除いて、第一・第三・第四日野小学校の現在の１年生から５年生は小中一貫校に入れないということね。","respondent":"谷田部学務課長","answer":"例えば、日野中学校に兄弟がいて、第三・第四日野小学校に弟さんや妹さんがいて、兄弟そろって新しい校舎に通いたいというようなケースがあった場合には、これも教育的な配慮の範囲に入りますので、どういう事情が各家庭にあるかどうかは。","voiceIndex":25,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"何でそういう言い訳をするわけ。新しい小中一貫校をつくるなら、そこに目指していくことを何で拒むわけ。現在の第四日野小学校は工事中で、仮設校舎だから難しいというのはわかる。今さらそこに３クラスの仮設校舎をつくれというのは、それは大変なこと。品川区が目指す教育環境、教育改革について理解をしている子どもたちが行きたいと言ったら、なぜ拒むの。","respondent":"古川教育次長","answer":"全体の対応の中で、募集の仕方とかさまざまあろうかと思いますが、私どもといたしましては平成１８年４月１日、基本は先ほど申しました内容ですけれども、少なくとも転校という中での受入れ枠はあるわけですので、これにつきましてもぜひこの小中一貫校の趣旨にてらして。","voiceIndex":27,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"だけど、いざできたときに、小学校というのは６年間だというのは知らなかったわけじゃないと思う。そうすると、新しく１年に入った子どもは、その学校６年間にいるけれども、現在通っている１年生にしても、平成１８年は３年生。そうすると、３年生、４年生、５年生、６年生と４年間、この学校にいるわけです。それが品川区の教育委員会が目指す小中一貫校のスタートになるかどうか聞かせてください。","respondent":"古川教育次長","answer":"今、加えて林（宏）委員からご意見をいただきましたので、その辺を含めまして十分に周知を図り、誤解のないような対応をしてまいりたいと、このように考えてあります。","voiceIndex":29,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"それはないように、教育委員会で細心の注意を払ってほしい。それはお願いしておきます。それから、大井第一小学校の表なんだけれども、右の表の新入学児童入学予測と書かれているわけなんだけれども、どこから１６６人というのは出してきているんですか。","respondent":"谷田部学務課長","answer":"今年の４月１日現在で、５歳以下のそれぞれの通学区域内の子どもの数、それと過去の大井第一小学校への入学数の実績をもとにしてはじき出したものが、こういう数字が見込まれるという数字です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"その実績による数字と言うんだけれども、例えば平成１７年度は１０１人に対して６４人プラスだね。平成１８年度は実績に対して５１人、これはどういう根拠なんですか。","respondent":"谷田部学務課長","answer":"過去３年の入学実績を見ておりまして、過去平均した入学率というのが住民基本台帳に対して １.６４３という係数が出てあります。これをもとにして、それぞれの住民基本台帳に掛けた数字がこのようになったというのが、私ども予想した数です。","voiceIndex":33,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、大井地区の小中一貫校ができるというのは、全く予測していないんですか。","respondent":"谷田部学務課長","answer":"考慮に入れてございません。","voiceIndex":35,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"だって、いつ開校なんですか、小中一貫校は。この数字の枠内に入っているでしょう。","respondent":"谷田部学務課長","answer":"当然、小中一貫校が大井地区では平成１９年度に開校するというのは、当然考えてあります。どのぐらいの子どもが動くのかというのが、過去の実績がないものですから、予測上は出せないですので、その辺はこの数字には考慮されていないです。","voiceIndex":37,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃ、逆上って大崎地区の小中一貫校の小学校３クラスというのは、どういう根拠なんですか。これは第四日野小学校だよ。","respondent":"谷田部学務課長","answer":"先ほど申し上げましたけれども、各学年３クラスずつという標準規模、それから小中一貫校を教育する上での規模からいって適正であるということで、こういう計画を立てたです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、大井地区の小中一貫校だって、そういう考え方で進めていくわけでしょう。やっぱり、この大井第一小学校の数字の出し方は、ちょっと乱暴すぎると思う。いろいろなベースをもって計算しているというけれども、乱暴すぎると思う。それは指摘しておきます。この右側の全学級数というのは、入学予想数が全部入れると、この学級数になりますよという理解でいいんですか。","respondent":"谷田部学務課長","answer":"この全学級数の見方です。現在、１年から６年まで２２学級あります。６年生が卒業しますと、３学級が生まれてまいります。その３がなくなって、新たに５学級編制になりますと、２学級増えるですので、現在の２２に２クラス足して２４学級になるです。","voiceIndex":41,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"意見","question":"２２－３＋５でしょう。そういうことだね。こうなるという、机上のというか、さっき話に出た予測の上でこういうクラスになるので、２４学級に抑えていきますよという理解をしなきゃいけないんですね。この表のようになるということはないですね。","respondent":"谷田部学務課長","answer":"全２４学級、各学年４学級ずつで何とか抑えていただきたいというようなことも現場から聞いてありますので、５学級にならないように４学級の中でおさめていきたいです。","voiceIndex":43,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"わかりました。施設の関係で、大井第一小学校みたいにどうしても入りきれない、子どもたちは受け入れるスペースがないというような場合は難しいとしても、３クラスつくるという意図を持っていて、それを排除する、１クラスに絞っていくというようなことは避けてほしい。そういうことからも、ぜひ品川区の子どもたちにとって、親が希望するならば入れてあげてほしい。ぜひ、それはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"沢田委員","kind":"意見","question":"一貫教育だ。これはバランス的にいっても、非常におかしな問題になって、私は教育上の配慮のために募集できないというより、もっと大きな問題が生じちゃうんじゃないのかなという気がするんですけれども、なぜ仮校舎から本校舎に移った段階で、臨時的ですよ、開校時に各学年で希望する人を募集しないのか、教育的な配慮の問題でなぜできないのかということを、もう一度説明してほしいんですけれども。","respondent":"中島指導課長","answer":"小中一貫教育の内容につきましては、平成１８年度から一貫校で取り組んでいくわけですが、すべての学年で一斉にその内容を実施しているわけではなくて、段階的に導入をしていくと、先ほど申し上げた状況があります。","voiceIndex":46,"id":"exchange-020"},{"speaker":"沢田委員","kind":"意見","question":"学年進行、経過措置というんですけれども、聞いているのは、なぜそういう経過措置が必要なのかということを聞いているんです。","respondent":"中島指導課長","answer":"ある程度の内容を前倒しして実施する部分ですとか、いろんな内容のカリキュラムの検討してきている内容を実施するということで、それに完全に移るためには、これまでの学習指導要領の改訂のときもそうですけれども、何年かの移行が必要になってくると、そういうところです。","voiceIndex":48,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"よくわからないんですけれども、これ以上やってもしようがないですから。","respondent":"若月教育長","answer":"ただ、確かに若干説明不足といいますか、このままでは区民の方々に多くの誤解を与える部分というのは、今日、いろいろご指摘をいただきまして明確になったわけでありますけれども、先ほど来指導課長も説明しておりますように。","voiceIndex":50,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、学校選択制の日程が出ていますけれども、希望申請が９月２４日、締め切りが１０月３１日、これなら自分が入学した学校が将来どうなっていくのか、どの学校と組み合わせをするのか全くわからないし、知らされないし、求めても検討中、これでは学校選択の意味がならないと思うんですね。そこのところを説明していただきたいなと。その姿勢をきちんと正していただきたいと思いますので、説明をお願いします。","respondent":"中島指導課長","answer":"１点目、先ほどの希望申請の時期と、私どもがこれから考えている研究グループ、このペアリングの過程が年度末であるというところのタイムラグについてのご質問です。","voiceIndex":52,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"一つの小学校と二つの中学校、二つの小学校と四つの中学校、いろんなペアリングがある点という話の中で、きちんと来年入学する１年生にもそれにかかってくるわけですから、それがなぜ９月２４日までにきちんと説明できないのか、ここをきちんと伺いたいと思いますので、もう一度お願いしたいのと、小中一貫校推進ニュースは、もう出ないんですか。","respondent":"中島指導課長","answer":"それぞれの小学校が一貫教育の内容を実施していくにあたりまして、特に５・６・７年生の連携の部分が、具体的に中学校の先生と小学校の先生が乗り入れていけるのか、そういったところを研究していくためのグループという位置づけでありますので。","voiceIndex":54,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点だけお願いします。そうなると、小学校の校舎で４年間、中学校の校舎で５年間という区切りで一貫教育をするとなると、結局中学校は５年生の途中で、選択制ですからそのまま残るのもいるし、移動するのもいるし、こうなるという理解でいいんでしょうか。こうなると、一貫教育が断ち切れるんじゃないかと思うんですね。その辺についてよくわからないので、説明していただきたいなと思います。","respondent":"中島指導課長","answer":"今の例は、あくまでもそういった形での取り組みの可能性もあるというお話をさせていただいたわけでありまして、例えば近隣の学校で４年生まで小学校のほうで学び、５・６年はすべての時間か１週間に１回かわかりませんけれども中学校の校舎で学ぶと。","voiceIndex":56,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点、わからないので質問したいんですけれども、初めは大崎地区で小中一貫校をやって、大井地区で２校目をつくって、今度は全区展開だと。ステップアップ学習では、週２回から３回やるわけですから、１週間の間に、４５分の授業のために往復４０分の移動距離がある施設。施設に違いをつくるというのは、やっぱりおかしいと思いますので、それだけ説明してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-026"}]},{"id":"topic-02","title":"平成１７年度使用小学校教科用図書採択","agenda":"平成１７年度使用小学校教科用図書採択","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"非常にうがった見方をするんだけれども、１日目、７月１３日、社会、地図、算数。社会と算数は東京書籍、２回目の７月２０日、国語、書写、理科で、国語と書写は光村図書出版、ほかはどっちかというと一つずつなんだけれども、教科書として国語と書写は一緒じゃないといけないという、連携的な部分があるんですか。","respondent":"中島指導課長","answer":"国語と書写ですけれども、国語の教科書と書写の教科書は同じ会社のものでないと、教育上、支障が出るということはございません。","voiceIndex":65,"id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、１日目の東京書籍と光村図書出版が二つずつ入っているんだけれども、偶然なんですか。","respondent":"中島指導課長","answer":"これは先ほど申し上げましたように、発行会社も全部マスキングをして協議していますので、結果としてこういう形になったです。","voiceIndex":67,"id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"出版社を伏せていることなんだけれども、確か平成１５年度はかなりミスプリというか、いろんな主張的な問題は別として、単純にミスプリが歴史上の間違いだとか、図書が僕の知っている範囲で三つ、四つあったんだけれども、もちろん訂正をしましたとか、新聞紙上でしか情報がないんだけれども、訂正の何かをよくある本なんかで訂正部分を送る、そういことで対応されてきたんだろうけれども。","respondent":"中島指導課長","answer":"例えば、今年度の教科書の中でそういったような状況があれば、当然教科書会社のほうでもその状況についての修正をかけてくるものと考えますけれども、来年度以降の教科書につきましては、そういった内容の不具合等は。","voiceIndex":69,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"例えば、子どもたちが教室で教えられて覚えちゃう。後になって、いや、あれは実は間違っていて、こういうふうに訂正しますというのは、非常に大きい問題だと思うんですね。その辺は、ある意味では出版会社の姿勢みたいなものもあるんだから、もちろん出版社名を出して選択するというのは非常に難しいんだろうけれども、それは考慮したほうがいいような気がするので、それは１点、言っておきます。","respondent":"中島指導課長","answer":"私どもが検討する項目の中には、もちろん教科書の内容記述が正確にされているかという項目もありますので、今回検討させていただいた中で、それが話題になったということはございませんけれども、当然きちんとした事実を正確に伝えるという部分につきましては。","voiceIndex":71,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういうことで、十分留意をしていただきたいなと思います。もう１点、内容じゃなくて、紙質なんですけれども、全部リサイクルの紙をもちろん使っていると思うんですけれども、全部１００％ですか。","respondent":"中島指導課長","answer":"ご指摘のとおりです。プリントされているインク等につきましてもです。","voiceIndex":73,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"意見","question":"じゃ、もう１回。そっちも加えてくるなら、使い終わった教科書なんだけれども、どういうふうにされていますか。あるいは、調査資料として相当数品川区に来ているわけですよね。それのリサイクルというか、それはどういうふうに。","respondent":"谷田部学務課長","answer":"教科書は無償で供与されますので、本そのものの所有権というのは、実際に使う子どものほうにあるわけですので、当然各家庭のほうで処理されるということです。","voiceIndex":75,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"学校の先生用にもあるでしょうし、スペアもあるでしょうし、調査していく中に相当数の教科書が品川区に配られるというか、配付されているわけですよね。ある公共施設の裏に、雨ざらしになって置かれているのを見かけるんですけれども、先ほどインクまでリサイクルに心がけているものを使っていると言うなら、そこはどうされていますか。","respondent":"中島指導課長","answer":"各校におきましても、小学校のほうは、環境ＩＳＯを全校に実施をしていくと、学校ＩＳＯの実施という状況の中で、リサイクルという形での処理をしています。","voiceIndex":77,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいんですが、以前教科用図書採択についての報告をいただいたんですが、確認をする上で、どのような選定理由、選定方法、どういう人たちが選定をして、品川区としてこういう観点から選定をするという、最終的に採択されているわけですけれども、その経緯というものをまとめた形で結構ですので教えていただけますか。","respondent":"中島指導課長","answer":"そこで、私どもでは教科用図書の検討委員会という委員会をつくりまして、そこで教育委員会が協議できる内容の資料にまとめ上げるという作業を行います。","voiceIndex":79,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"要は、検討委員会のところでいろいろ検討されて、この教科書のこういうところが優れているというふうにまとめられたものがある。一つ一つできないと思いますので、品川区としてはこういうところを気をつけて選定をやらせているとか、それとも教育委員会のメンバーの人たちの主観になってしまうのか、そこのところの調整というのは、どういうふうな形にされているんですか。","respondent":"中島指導課長","answer":"形式的な部分ですけれども、印刷の見やすさですとか、製本の仕方ですとか、そういった部分を含めて、最後に、地域性として東京都や品川区の子どもたちが使うわけですから、そういった部分への配慮がどうなされているかというところを細かくまとめて出てきた資料として。","voiceIndex":81,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"というのは、教育委員会も、事務局もそうでしょうけれども、メンバーがいつも同じというわけではない状況があるので、いつも選定の標準というのがあって選択されているのか、例えば教育委員会等々のメンバーを変えることによって、考え方が変わることで選定方法が変わってしまうものなのか、その辺はどういうふうになっているのかをお伺いしたいんですけれども。","respondent":"中島指導課長","answer":"それを具体的に、その教科書の中でクリアしようというような取り組みで使う部分で、これは非常に扱いやすいと、そういったような内容も意見としてはいただいてありますので、こちらで差し上げている資料はあくまでも補助資料という形でございまして。","voiceIndex":83,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"もう１点お聞きしたいのは、ゆとり教育という形で教科書内容が大分変わったというふうになってきていると思うんですが、文部科学省の規定が私も詳しくはないんですけれども、もう少し発展的な評価を入れるような内容のものがあったりとか、例えば円周率というのは３.１４だったのが３であると、それを発展的なところで３.１４にしていくとか、いろいろ少し見直しがあると思うんですけれども、今回の場合は。","respondent":"中島指導課長","answer":"本区におきましては、さまざまな学習を展開する中で、例えば単元のまとめの段階で習熟度別学習を実施していくときに、また発展的な内容を取り入れたりするような形で、この発展学習については抑えている部分があります。","voiceIndex":85,"id":"exchange-037"},{"speaker":"西本委員","kind":"意見","question":"以前、ヘルストレーニングのところを使用されている方はいらっしゃって、近隣に品川健康センターがあるので、そこに入れていただくようにということで、ご紹介をしていただくことになっているんですが、その後、その方たちは、何人か団体の方がご利用された方がいらっしゃったと思うんですが、その辺の状況を聞きたいんですけれども。","respondent":"上川内生涯学習課長","answer":"ヘルストレーニングルーム廃止の際につきましては、かなりいろいろなご要望等もお受けしました。健康センターに日にちを設けまして、体験学習という形で行っていただいて、その後は特に現場のほうにも私のほうにも何も申し出はございません。","voiceIndex":94,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"これは区の都合で、今まで長くお使いになっていただいた方を、こちらのほうをどうぞということをした経緯もありますので、その辺はもう少し丁寧な声かけといいますか、確認といいますか、そこで何か行きづらいという状況があるとすれば、健康上の問題、その辺をもうちょっとしていただきたいなと思うので、その辺はいかがでしょうか。","respondent":"上川内生涯学習課長","answer":"私のほうで健康センターのほうにも、一番最初のときと最近も様子を見に行ったんですが、東品川文化センターを使っている方と同一かどうかわかりませんが、結構子どもから若い方、高齢者まで入り交じってやっている姿が見えましたので。","voiceIndex":96,"id":"exchange-039"},{"speaker":"西本委員","kind":"意見","question":"いろいろありがとうあります。今年、区の政策の中でも、いきいき健康プランという形でいろいろ施策をしておりますので、なるべく、中高年の方が多かったので、ＰＲ等をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-040"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"なぜ、報告がないのかということと、具体的にどんな報告をしたのか、カリキュラムの内容で一貫教育はこう変わるということを言ったのか、私は改めて説明を求めたいと思います。","respondent":"中島指導課長、古川教育次長","answer":"その後、学校が夏季休業日に入ったところで、校長を対象の説明会、それから本年度から小学校、中学校に各１名、担当として設置していただいた小中一貫教育担当者を対象とした同じ説明会、内容はすべて同じですが。ただ、時期につきましては、先ほど指導課長からお話し申し上げましたように、まずは教員あるいは校長、教頭、それぞれの段階でカリキュラムを検討を進めている途中でございまして、途中におけるさまざまな状況について研修ということで。","voiceIndex":102,"id":"exchange-041"},{"speaker":"沢田委員","kind":"質問・要望","question":"それで、今度は、まだ途中で変わる研修だから、当委員会には報告がないんですけれども、それはもっと当文教委員会に一貫教育はどうなるのか随時報告して、意見を求めてほしいと私は思います。私どもで２７日の研修に傍聴させてほしいと言ったら、教員専用の研修だから、それはだめだと断られた。ところが、新聞の何紙かが内容を報じているんですね。これはいかがなんですか、新聞記者は入れたんですか。","respondent":"中島指導課長","answer":"これの開催につきましては、パブリシティをかけさせていただきましたので、新聞報道等のほうで入っている状況はございました。","voiceIndex":105,"id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"今後の姿勢の問題ですから言っているんです。ともに指導要領より１割以上増えることになる」。今日は、最後のその他ですから、これ以上やりませんけれども、ぜひ時間を取って、現段階でのカリキュラムの中身が、現在と今目指している方向はどこがどう違うのかというのを、事細かに報告してもらう時間をつくってほしいということを要望して、あとはその他ですから申し訳ないので終わります。","respondent":"中島委員長","answer":"今の問題に対しては、皆さんの統一した意見も必要だと思いますので、正副委員長に検討させていただいて、今後、報告をいただくかどうかは決めさせていただきたいと思うんですが、よろしいでしょうか。","voiceIndex":107,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":29677,"voices":110}},{"id":"h16-20040924-4","meetingId":"h16-c-settlement","date":"2004年9月24日","dateIso":"2004-09-24","committee":"決算特別委員会","time":"午後４時５３分～午後５時０１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":2370,"voices":18}},{"id":"h16-20040927-6","meetingId":"h16-cm09","date":"2004年9月27日","dateIso":"2004-09-27","committee":"区民委員会","time":"午前１０時０４分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１番目、第７０号議案、臨海部広域斎場組合規約の変更","agenda":"の１番目、第７０号議案、臨海部広域斎場組合規約の変更","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"平成１６年１２月１日からということでありますが、一つは、これを何で今の時期に変えなければいけないのか。臨海斎場ができたときにすぐすればよかったのではないかという素朴な疑問だと思うんです。そこのところの説明をいただきたい。","respondent":"長田区民課長","answer":"このときには、他の規約の変更事項が出そうだというようなことで、そちらのほうと一緒に合わせて行うことで調整をしていたわけですけれども、そちらのほうが当面変更しなくて済むというような見込みになったために、位置の問題は規約上の重要な問題だということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"原委員","kind":"意見","question":"平成１６年１月１５日に開設されて、あそこは事務所というのがありますよね。更地にしたところ、そこで事務の遂行はやっているわけです。兼業事務所も、本来の事務所に置かなければいけないということなんだろうと思うんですが、これを変えないでも別に業務には差し支えないということで、何でそこを変えなければいけないのかなということがわからないんです。","respondent":"長田区民課長","answer":"先ほど申し上げました、ほかの規約と合わせてやる予定だったわけですけれども、そちらのほうが必要なくなったというのを説明申し上げたわけです。もう一つは、現行の規約では管理者が大田区長になってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"もし１区でも承認をしないよという話が出た場合は、どうするんですか。","respondent":"長田区民課長","answer":"ですから、この中で１区でも議決をいただけないというようなことがあれば、実際上都知事への届け出ができないというような形になります。ただ、今のところは５区とも議決をいただくような形で調整をしておりまして、各区とも第３回定例会で議案として提出をしています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"ご事情はよく分かるんですけれども、利害関係、便宜上、あるいは規約上、書かれていない部分があるので、そういうような形で提出をしたと思います。こういったものというのは、確かにほかの規約と合わせて変えたいという気持ちは分かるんですが、そういうところをしっかりやっておかないと、何かのときには問題があるかなと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"今回、移転ということで、費用のほうはどういうふうになるんでしょうか。","respondent":"長田区民課長","answer":"費用ということにつきましては、これは事務所の位置の変更だけですから、特に使用料が安くなるとか、そういうこととは関係なく、規定の整備ということで提案を申し上げているものです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"今回の一般質問でもこの件は取り上げられましたよね。いろいろ聞いておりまして、何点かお伺いしたいんですが、稼働率によって分担金が変わるという話がありましたね。今年１年間の稼働率によって来年の分担金が変わるという話がありますので、そこのところを細かく説明をお願いいたします。","respondent":"長田区民課長","answer":"３年後は、それぞれ各区が利用した実績に基づいて必要経費の按分率を決めましょうという形になってあります。現在のところでは、想定をした数字ですけれども、品川区の場合は経費の１７.２％を3年間負担をするという形になってあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"山路委員","kind":"質問","question":"５区が平等にということですけれども、分担金を出している品川区の稼働率は全体の何％ぐらいなんでしょうか。","respondent":"長田区民課長","answer":"式場のほうが全体で４５１件で、そのうち品川区が９７件、２１.５％という数字になってあります。ですから、そういった意味では、当初想定をした１７.２％より品川区民の方にご利用をいただいているというようなことだろうと思います。","voiceIndex":16,"id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"もっとバスを大井町から出してほしいという意見があるんですけれども、これをそのままバス会社に投げると、営業上、私もたびたび臨海斎場には行っているんですけれども、ほとんど乗っている人がいないんですね。マイクロバスとか、組合と何とか区民の便宜を図るような方法がとれないのかどうか、そこまでサービスをすべきだと思いますけれども、どのようにお考えでしょうか。","respondent":"長田区民課長","answer":"ですから、そういうようなことも５区の中で、確かに不便だから、そういうこともするべきだというようなことで協議が整えば、できない話ではありませんけれども、まだ軌道に乗っていない時期に新たな支出は控えたいというようなことで、今のところは話には出ておりますけれども。","voiceIndex":18,"id":"exchange-008"},{"speaker":"山路委員","kind":"質問・要望","question":"私も現場で交通アクセスを便利にしてほしいというのは相当聞いておりますので、品川区から組合のほうに働きかけて、営業と別に、分担金を出しているという区民の思いを汲んでいただいて、もう少し身近に気楽に行けるように、ましてや、超高齢化時代ですから、これから稼働率はどんどん増えてくると思うんです。そういうのを品川区が最初に手を挙げて伝えていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"}]},{"id":"topic-02","title":"第６４号議案、平成１６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６４号議案、平成１６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"井上委員","kind":"確認","question":"一番最初の、区の拠出がゼロとおっしゃっていたところの確認ですけれども、ＪＴのほうから再開発の部分でというけれども、それは今の繰入金のところと合わせて１,３００万円が８００万円になるということではなくて、初年度経費として１億円出ているんですけれども、何がどういうふうに、最後までいったらわからなくなってしまったんですけれども、その辺をもう一度お願いします。","respondent":"日下部産業振興課長","answer":"結論から申し上げますと、当初予算に計上した１億円、それから、今回計上しております１,８００万円、合計１億１,８００万円は、すべてＪＴからの拠出金です。","voiceIndex":27,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"その１,８００万円の繰越金のところの、一般財源からここへ持ってきたというところが、これが先ほどの１,８００万円と同じものですか。","respondent":"日下部産業振興課長","answer":"先ほども申し上げましたが、一たん基金のほうから一般会計のほうに繰り入れをいたしまして、その１,８００万円を今度は歳出として用地取得の費用に充当していくという流れになってあります。","voiceIndex":29,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"この図ですけれども、線のところの４２m2というのが商店街なんですが、こちらにある台形のようなところは、斜線が区の土地なんですか。図がよくわからないんです。","respondent":"日下部産業振興課長","answer":"図の説明をもう少し丁寧にご説明すればよかったんですが、太い線で仕切ってありますが、これの左手の部分、斜線の部分も含めてすべて合わせまして１７６m2、これが土地を意味しております。それから、そのうち、先ほど歳入のほうでもちょっと触れました、既存の建物があります。","voiceIndex":31,"id":"exchange-012"},{"speaker":"井上委員","kind":"意見","question":"どういう経過でこの場所がそういう取得に至ったのかという経過を含めて、どのぐらいから予定があって、構想があってというところをお願いいたします。","respondent":"日下部産業振興課長","answer":"このたびより具体的に、先ほど申し上げました予定地の取得の見通しが立ったということで、今回補正に計上をさせていただいた、このような経緯です。","voiceIndex":33,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"土地をめぐって選定をほとんど地元の方が中心に行っているのか、そこのところと区の係わりはどのようになっているんですか。","respondent":"日下部産業振興課長","answer":"この土地の選定につきましては、もともとが地元のほうから、地域のにぎわいづくり、それから、活性化ということで何とか実現をしたいというようなお話が発端でもありますので、地元のほうで中心になりまして、いろいろ選定を進めてきたという経緯があります。","voiceIndex":35,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"要するに、拠出金を基金として積み立てておく、そこの使用方法、今回の場合は土地の取得、それ以外にも前提条件としてあるのかどうか、そこだけ教えて下さい。","respondent":"日下部産業振興課長","answer":"具体的な手法の問題ですが、拠出金が出てくる段階で既に地元の要望としましては、旧東海道の活性化ということを念頭に置いて、いわゆるお休み処のような形で確保していくという形で要望が出ておりましたし、それを受けて、地権者のほうからも。","voiceIndex":37,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"今回は東品川四丁目での開発のお話でありますけれども、地元との関係で言うと、他の開発の場合でも、地権者から拠出金という形というのは通常あることなんですか。","respondent":"日下部産業振興課長","answer":"ですから、今回の東品川四丁目につきまして、道路、公園の整備はもとより、いろいろな形で公共施設の整備は進めておりますけれども、ただ、一方で、それだけ大規模な開発を進めるということで、いわば古いまちと新しいまちがあそこにいかに共存していくかということも含めて。","voiceIndex":39,"id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"１点だけお伺いしたいんですが、当初予算１億円、今回補正で１,８００万円、要は、１億１,８００万円で計上されたということだけれども、この１,８００万円になった理由は何ですか。","respondent":"日下部産業振興課長","answer":"幾つかの候補がございましたけれども、その後のいろいろな検討の経過の中で、今回、先ほどお示しをしたような土地に決まってきた。ただ、その場合、土地の評価の金額等を含めて、１億円では足りませんので、１,８００万円を追加で補正をする、このような結果になりました。","voiceIndex":41,"id":"exchange-017"},{"speaker":"原委員","kind":"意見","question":"こだわって申し訳ないんですけれども、１,８００万円という根拠、例えばそれは２,０００万円、あるいは２,５００万円とか、いろいろあるわけですね。根拠がないと１,８００万円にならないわけで、そこを知りたいんです。","respondent":"日下部産業振興課長","answer":"ですから、今申し上げた７３万２,０００円で１７６m2、それに係わる経費が大体１億３,０００万円ほどになりますが、それから１,１００万円余の撤去費用を差し引きますと１億１,８００万円になるです。","voiceIndex":43,"id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"候補地に何カ所か挙がったというんですが、挙がった中でなぜここが選ばれたのか。","respondent":"日下部産業振興課長","answer":"にぎわいづくりの拠点として申し上げれば、この角地が一番適当だということで、私も実は宿場まつりに行ってまいりましたけれども、イベントのときもそうなんですが、にぎわいづくりの拠点として絶好の位置です。","voiceIndex":47,"id":"exchange-019"},{"speaker":"塚本副委員長","kind":"質問","question":"既存の中心と、新しいまちの中心の間にあるということ、それから、立地条件もいい。聞いておきたいのは、３億円を、ほかの委員会では報告があったと思うんですが、今回１億円になった。八潮橋のエレベーターに金を使っているんですが、どのぐらい残っていて、どういう縛りのあるお金なのか、まだこのお金でもって何ができるのかを教えてください。","respondent":"日下部産業振興課長","answer":"ですから、それで大体使い切ることになってまいりますが、現在の執行状況としては、先ほど申し上げました、１億円の維持管理経費、これは単純計算で、たしか年間５００万円で、２０年ほどということで見込んでおりますので。","voiceIndex":49,"id":"exchange-020"},{"speaker":"塚本副委員長","kind":"意見","question":"メンテナンスの費用に１億円というのは、大つかみのところでしょうけれども、基本的にはほかのお金にもう使い切ったというふうに認識していいんですね。新たに取得したところの建物のメンテナンス経費は３億円の中からは出てこないということになりますか。","respondent":"日下部産業振興課長","answer":"建物の分については、これはそちらから出る余裕はございませんので、別立てで対応をするということになってあります。","voiceIndex":51,"id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"私も紹介議員として署名をしているものですから、毎年このような形で青色申告会のほうから意見書を出してほしいということで、ここ数年続けてやりまして、特に２００m2以下の小規模の宅地用地に対して都市計画税の２分の１軽減というのは、今後の中でも、要旨にありますとおり、景気状況も含めて、まだ非常に重要な部分でもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"請願の趣旨の２番目ですけれども、小規模事業者の皆さんが景気の回復が全く実感できないという、これは本当にそのとおりなんだろうなというふうに思いますけれども、小規模事業者の皆さんが支払っている税収入との関係で見たときに、１番目で言っている、個人消費は持ち直しているとか、景気が回復してきたんだというのが、品川区内の小規模事業者の皆さんの税収との関係で見たときに。","respondent":"太田税務課長","answer":"ご質問の内容ですが、この軽減措置につきましては、先ほども申し上げましたように、昭和６３年から既に住宅用地の都市計画税の部分について２分の１を控除してきているという経過がありますので、これだけ見ますと。","voiceIndex":68,"id":"exchange-023"},{"speaker":"菊地委員","kind":"意見","question":"そういうことよりも、区内の業者の皆さんのところで実際に景気が回復してきて、一定程度の利益が上がってきているということであれば、当然税収そのものも変わってくるかと思うんですけれども、そことの関係でどういうふうに分析をされているのかというのをお聞かせ願いたかったんです。","respondent":"太田税務課長","answer":"私ども個人の住民税を徴収しているわけですけれども、その部分だけで申し上げれば、昨年６月以降、対中国輸出とか、米国輸出に伴って、国内の大企業が景気を回復したと。株価も上昇をしてきて、一定の右上がりの傾向が見られてきている。","voiceIndex":70,"id":"exchange-024"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"昭和６３年以降ということで、２０年近く経っているわけですね。これだけ長期間そういうことをやるということは、本則のほうを変えるというのが本来のあり方だろうと思うんですけれども、そういう考え方はとらないのか、また、そういう動きがあったのか、内部でも、東京都の機関のほうでも結構ですけれども、そういう情報があれば教えていただきたい。","respondent":"太田税務課長","answer":"ご指摘のように、ここ数年延長措置が必要なのかどうかというのは、東京都の主税局の内部でも検討はされているというふうに聞いてありますけれども、適用になっている方のご要望等も踏まえて、平成１６年度については継続をしたというふうに聞いてあります。","voiceIndex":72,"id":"exchange-025"},{"speaker":"塚本副委員長","kind":"質問","question":"答えにくい部分だろうと思いますけれども、基本的な考え方としては、長い間特別な措置をしていたということは特別ではなくなってしまうわけですから、本来の措置に戻すべきだというふうに意見を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-026"},{"speaker":"原委員","kind":"質問・要望","question":"いろいろご意見等があると思いますが、お話しいただいた中で、結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-027"}]},{"id":"topic-03","title":"１番目の専決処分（報告２３号）","agenda":"１番目の専決処分（報告２３号）","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"損害賠償額の内訳を教えていただきたいと思います。","respondent":"太田税務課長","answer":"バンパーの脱着取り替え、板金等でございまして、修理費で、消費税、その他で5万３,１３０円です。車の代車代が、９日間ということで４万５,０００円です。","voiceIndex":99,"id":"exchange-028"},{"speaker":"山村委員","kind":"質問","question":"先ほどのご説明にあったと思うんですけれども、使った車の車種は何でしょうか。","respondent":"太田税務課長","answer":"営業用の車でございまして、通常のホンダスペクトルワゴンです。","voiceIndex":101,"id":"exchange-029"}]},{"id":"topic-04","title":"の中延シルバーセンターの平塚橋会館への移転","agenda":"の中延シルバーセンターの平塚橋会館への移転","exchanges":[{"speaker":"山村委員","kind":"意見","question":"完璧に中延シルバーセンターが平塚橋会館に移行するということですが、シルバーセンターが入っている施設内で葬儀をやるのはちょっと趣味が悪いというか、あまりいいとは私は思っていないんですが。","respondent":"田村地域活動課長","answer":"その辺はこれから具体的に検討をしていく中で、動線、あるいはあまりお金をかけるのも難しいので、水回りも共有化しようというような話になっておりますので、これから設計を所管のほうで始めるときに工夫してまいりたいと思ってあります。","voiceIndex":113,"id":"exchange-030"},{"speaker":"山村委員","kind":"質問","question":"葬儀のほうを廃止するというのは考えられないんですか。要するに、葬儀機能のほうを廃止して、平塚橋会館ですよということは考えられないんですか。今後も伸びるとは思えないんです。","respondent":"田村地域活動課長","answer":"それの、特に借家の方が５０％いまして、要は、自宅だと自分のところでできるわけですね。借家の方はなかなかそういう設備がなくて、葬儀をしない方もいるので、１,０００人前後の７掛けぐらいで、７００人から８００人ぐらいを見込んでいたみたいです。","voiceIndex":115,"id":"exchange-031"},{"speaker":"山村委員","kind":"意見","question":"中延シルバーセンターが平塚橋会館に移設された場合、平塚橋会館自身の収支がよくなるというふうな考えでいらっしゃるのかということと、中延シルバーセンターの利用率は高かったんでしょうけれども、平塚橋会館へまた全員通ってくるかというと、それは違うという気がするんですが、そこら辺はどういうふうに考えておりますか。","respondent":"田村地域活動課長","answer":"もう一つ、私のほうの所管ではないんですが、高齢者のほうの場所が変わったことによって、そちらに通えるかということで、高齢事業課の所管のほうでは、利用者団体が３２団体から３４団体ほどあるので、こういうような考えでいますというような話を。","voiceIndex":119,"id":"exchange-032"},{"speaker":"山路委員","kind":"質問・要望","question":"今ごもっともらしい説明をいただいたわけですけれども、当時、平塚橋会館に荏原地域の葬祭場ができたということで、荏原地域の方は喜んでいたんですね。利用率を悪くした原因が区のほうにあるんじゃないかということを言っている方がいらっしゃるんですが、要望がきたと思うんですけれども、それについて連絡は入っていませんでしょうか。","respondent":"田村地域活動課長","answer":"平塚橋会館の葬儀に関しての要望等というのは、私は４月から着任しましたけれども、特に地域センターなり、特別私の耳には入っておりません。","voiceIndex":122,"id":"exchange-033"},{"speaker":"山路委員","kind":"質問・要望","question":"地元からも再三明るくしてほしいということを要望しているということです。明るくして見えるようにしてくれたら地元の私たちは使いたいというのに、そのままほったらかして、何も応えないで、いきなり移転するというのは、あまりにも努力しないで安易ではないかと言っている住民の方がいらっしゃるんですけれども、この辺についてはどういうふうにお考えでしょうか。","respondent":"田村地域活動課長","answer":"ただ、実際に利用について明るくしてほしいという具体的な話というのは、今初めてお聞きしたので、それは仮にシルバーセンターが入ってくる、こないにかかわらず、改善できるものは対応をしていきたいと思います。","voiceIndex":124,"id":"exchange-034"},{"speaker":"山路委員","kind":"質問・要望","question":"まだ明るくしたら使えるのに、それをやらなかったために私たちは使えないんだという人が何名かいらっしゃいますので、その辺の努力をしていた経緯とか、また、いきなり移転したんじゃないという説明とか、それなりの検討と、住民の方の注目のところでもありましたので、細かい配慮をしていただいて、納得の上で計画を立てていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"私も前に近隣の方に伺ったときに、利用勝手というよりも、あそこのところはほとんど使われていなくて、無駄な施設ではないか、ここを維持するにもお金が相当かかっているんじゃないかという声を伺ったことがあって、そのときにはどうしてそういう状況なのかわからなかったんですが、平成１５年度の実績で平塚橋会館は、荏原西区民集会所と同じぐらいで、１４.９％というところで少なくて。","respondent":"田村地域活動課長","answer":"区民との意見ということですが、これは当初の設立からいろいろ区民の方からのご要望が出ておりますので、本委員会に報告をした後に、既に所管の高齢事業課とは話をしているようですが、自治会長にどういうような形の説明会方式にしたほうがいいか。","voiceIndex":127,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"今回の場合で言うと、葬儀を利用したいという方が、近くの方なのか、ちょっと状況がわかりませんけれども、そこのところの順番がまずは違うんじゃないですかということを一つ指摘をします。質問としては、中延シルバーセンターのほうが動かなければならなくなった状況というのは、ちょっと所管が違うと思いますけれども、ここの係わりになると思うので、それはなぜなのかお分かりでしょうか。","respondent":"田村地域活動課長、山田区民生活事業部長","answer":"ですから、区長決定した結果を報告事項で所管の委員会にお配りして、過去の１０年からの利用状況を見ても、明らかに施設がなかなか有効活用し切れていないというのが区の認識ですから、少なくとも一部機能を残せば。その辺を勘案して、平塚橋会館をどうしていこうかというところで、三位が一体となって、この案という形で、一番妥当ではないかということで、区として決定をさせていただいて。","voiceIndex":129,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"利用者の声を一言聞いていれば、ああいう設計にはならなかったんだろうなということを、私は非常に疑問に思っておりますので、今回の場合にもシルバーセンターと葬儀、実績で言えば３件ですから、どのような状況かわかりませんけれども、利用者の立場で切り替えていかないと、せっかく税金をかけてつくったものでも、使い勝手が悪いと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-038"}]},{"id":"topic-05","title":"の報告事項に移ります。年末対策特別事業資金の実施","agenda":"の報告事項に移ります。年末対策特別事業資金の実施","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"何点かお伺いします。初めに、３番の対象者のところで、今課長のご説明で、「毎回同様ですが」というふうな言葉が出たんですけれども、１年または直近３カ月とか、そういうのを見直すとか、その条件を変えるということは考えたのかということ。この施策が本委員会に出てくるときに、区民の方に、中小企業の方に配る本物のパンフレットがいつもついているかと思うんですが、今回はなぜついていないのか。","respondent":"日下部産業振興課長","answer":"対象者について、毎回同様ということで、見直すとか、その辺はどうなのかというお話ですけれども、対象者については、本年度の実施にあたりましても、対象者をどういう形で設定しようかということで、いろいろ中では検討をいたしました。","voiceIndex":139,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"融資あっ旋の件数というのは、前回のものがここに出ておりますけれども、前々回、前々々回に比べて、あっ旋なり、融資実行件数というのは増えているのか、減っているのか。それと、平成１５年度ですけれども、融資のあっ旋をして、実行した割合が前々回と比べて伸びているような気がするんですけれども、もし伸びているのであれば、その理由、背景があれば、教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"あっ旋の実行率について今委員のほうからご指摘がありました。平成１５年度の実行率を計算しますと、件数にして９０％、金額ベースでまいりますと７５％ということで、そういった意味では、平成１４年度に比べて確かに上がっているという状況です。","voiceIndex":141,"id":"exchange-040"},{"speaker":"菊地委員","kind":"意見","question":"今のと関連しますけれども、本年度は相談員の方が入っておられて、相談件数とあっ旋件数が同じ規模だというお話でしたけれども、確かに融資実行率というのはすごく高いんだと思いますけれども、いずれにしても、３４件の方が実際には融資を受けられなかったという数字になっていますけれども、この辺は相談員の方がその後をフォローしていく体制とか、それから、実際に受けられなかった内容が分かりますか。","respondent":"日下部産業振興課長","answer":"私どもとしましては、実行されなかった方について、個々にこちらから一種の追跡でフォローするという形は現在はとっておりませんけれども、ただ、実行されなければ、かなりの方が改めて私どものほうに相談に来るケースが結構ありますので。","voiceIndex":143,"id":"exchange-041"},{"speaker":"菊地委員","kind":"意見","question":"相談員の方が相談を受けたときに、返済能力というところで、そこまでは相談に乗った段階では突っ込んであっ旋をするわけではないという形式なのかどうか。","respondent":"日下部産業振興課長","answer":"ですから、当然財務状況であるとか、経営状況についても、専門家ですから、ある程度それを把握した上で、区のほうとして紹介状を発行する、つまりあっ旋をするかどうかということで判断をするわけですが、ただ、実際にはそこである程度よしということで金融機関に紹介をしても。","voiceIndex":145,"id":"exchange-042"},{"speaker":"菊地委員","kind":"意見","question":"実際に区に相談した、前年度で言えば、わずか３４件ですが、改めて実行されなかった皆さんが区に相談に来ないまでも、そのうちのフォローというのは、このぐらいの件数でしたらある程度可能なんじゃないのかなというふうに思いますので、その辺は相談員の方も含めて、かなり丁寧にしてあげる体制をぜひ考えていただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-043"},{"speaker":"山路委員","kind":"質問","question":"この年末対策特別事業資金は、中小企業の方にとりまして、「大変助かりました」とか、私たちのほうには感謝の話がよくあるんです。私も非常に高く評価しているんですけれども、回収率というのはどういうふうになっているのか。今年の４月からですから、まだ１年経っていないんですけれども、着実に進んでいるのかどうか。その辺、実態としてどうか。","respondent":"日下部産業振興課長","answer":"返済の状況ですけれども、藤原委員のご質問にもお答えしましたが、最終的にどうしても返済できない状況になりますと、保証協会が本人に成り代わって弁済をするという仕組みになってありますが、この年末の資金につきましては、まず実行率が高いということは。","voiceIndex":148,"id":"exchange-044"},{"speaker":"山路委員","kind":"質問・要望","question":"この問い合わせがいまだあるんですね。具体的にこれはどこかに移動したか、品川区では廃止になったことは承知しているんですが、問い合わせとか、まちで聞かれた場合に、どこでどうやって相談すればいいのかということで、区のほうに行っても相談の窓口もないところなんですが、どういう場所で、どういうところで、電話番号とか、もしお分かりだったら教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"ですから、品川区であれば大井町にあります労働金庫の支店で申し込みの手続きができるということで、私も勤労者の生活資金で問い合わせを受けたのは１件ぐらいしかございませんけれども、照会があった場合は、今申し上げたような中身についてご説明をし。","voiceIndex":150,"id":"exchange-045"},{"speaker":"山路委員","kind":"質問","question":"これを、数は少ないと思うんですが、あまりにもわからない人が多過ぎるので、東京都の広報か何で知らせるということは難しいでしょうか。もし勤労者でこういうことがあったら、東京都のこういう機関にお問い合わせくださいとか。","respondent":"日下部産業振興課長","answer":"このパンフレットについては私どもの中小企業センターにも常備して、ご希望の方にお配りしておりますし、東京都の広報も含めての周知につきましては、また私どものほうから東京都にも申し入れるということも含めまして、その辺の対応をさせていただきたいと思います。","voiceIndex":152,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"質問なんですけれども、融資を実行された方たちというのは、何年かはないとか、今年そうで、また来年もちょっと大変だったのでということで可能なのか、その辺はどうなっているんでしょうか。１回受けたらその人たちは対象でないとか、そういうのはどういうようになっているんでしょうか。","respondent":"日下部産業振興課長","answer":"ただ、この大きな特徴は、ほかの設備資金、運転資金、あるいは小規模の特別資金というのがありますが、それらとの併用がダブルでの借り入れが可能だと。その辺が大きな特徴でもありますので、うまく組み合わせていただければかなり使いでがあるのではなかろうかです。","voiceIndex":154,"id":"exchange-047"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認をさせてください。この年末融資が始まって８年ですね。私は記憶がなくて申し訳ないんですけれども、当初のところと、現状のところと違うところはありますか。","respondent":"日下部産業振興課長","answer":"そういう点では、厳しさという面では状況は同じようなところで考えてあります。","voiceIndex":156,"id":"exchange-048"},{"speaker":"原委員","kind":"確認","question":"全体的な状況もさることながら、内容的なものの中で、例えば融資限度を変えてきているとか、その間にいろいろ経済状況がはさまってきているわけですね。そうすると、多分最初の８年前のそのままをずっと引きずっていればいいわけでもないということがあるわけですから、どこかいじっているのかなということも含めて確認したかったんです。","respondent":"日下部産業振興課長","answer":"貸し付けの条件等につきましては、基本的には融資限度額は変わっておりません。ただ、違うのは、本人の金利負担、これは毎年金融機関との協定の中身が変動してまいりますので、それによって若干本人負担が変わる。大きな違いはそれだけです。","voiceIndex":158,"id":"exchange-049"}]},{"id":"topic-06","title":"(4)プレミアム商品券の発行","agenda":"(4)プレミアム商品券の発行","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"昨年が２億円分で、今年が１億円分というふうになっておりますが、１億円分を減らした理由を教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"その結果、商店街のほうとしては、短期間といったこともありまして、１億円の１０％で実施をしてほしいということで要望がございましたので、その線に沿って、金額は半減されますが、１０％のプレミアムはそのままということで実施をすることになりました。","voiceIndex":165,"id":"exchange-050"},{"speaker":"山村委員","kind":"質問","question":"そうすると、やはりこれの効果でにぎわいも伸びると考えてよろしいでしょうか。","respondent":"日下部産業振興課長","answer":"実は共通商品券、取り扱いするお店がどうも少ないというような話も結構あるんですが、これをきっかけにして、そんなに多くはないんですが、前よりは５０店舗ほど増えたということで、いろいろそういった意味では、プレミアム商品券の発行ではずみがついた。","voiceIndex":169,"id":"exchange-051"},{"speaker":"山村委員","kind":"質問","question":"基本的なことをお聞きしたいんですが、その商品券は、品川区以外の人間でも買えるんでしょうか。","respondent":"日下部産業振興課長","answer":"購入については、区民の方であるかどうかというのは、これは別に身分証明書を見せていただくわけでもありませんから、それは関係ありません。ただ、区内の取り扱いをする商店街でないと買えませんから、それが一番大きな目的です。","voiceIndex":171,"id":"exchange-052"},{"speaker":"山村委員","kind":"意見","question":"そうすると、区広報でチラシとか、そういうのがありますけれども、区内以外の方で購入できるんでしたら、ホームページか何かに載せたほうが、区内からでも、品川区と目黒区の境ですとか、大田区と品川区の境の人も、ホームページに載っているほうが知りやすいのではないか。新聞とか、折り込みとかですと、品川区内の人間のみの知らせになっちゃうと思いますので。","respondent":"日下部産業振興課長","answer":"実は品川区の商店街は立派なホームページを持っておりまして、その中でＰＲをするということを既に予定をしています。","voiceIndex":173,"id":"exchange-053"},{"speaker":"藤原委員","kind":"質問","question":"今、課長のご答弁の中で、目的というのが出たと思うんですが、改めてお伺いしますが、この目的は、商店街のためなのか、それとも区民を含めた消費者のためなのか。目的をまずお伺いします。","respondent":"日下部産業振興課長","answer":"これは私どもが所管して、商店街振興事業の一環として実施をしているものでありまして、そういった意味からすると、商店街の活性化のために実施するというものです。","voiceIndex":175,"id":"exchange-054"},{"speaker":"藤原委員","kind":"質問","question":"今回で２回目ですが、前回は商品券は完売ということですが、期限がありますが、期限内に完売された商品券は２億円ですよね。実際使われた金額というのは幾らでしょうか。","respondent":"日下部産業振興課長","answer":"期限内で使われた商品券ですけれども、実はちょっと細かい話になりますが、回収率が９９.７４％、要するに、ほとんど１００％に近い形で回収がされたです。","voiceIndex":177,"id":"exchange-055"},{"speaker":"藤原委員","kind":"質問・要望","question":"大型店も使えるのであるならば、一番使われたところが分かれば教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"大型店につきましては、これはいろいろ議論があるところですけれども、現段階においては大型店での利用というのはできないということになっております。","voiceIndex":179,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"先ほど商店が努力して、抽選で昨年の３倍のふるさとのそういう特典がついたりとかというのは全部商店街が出しているものなのか、基本的に品川区としてはプレミアムの補助だけなのか、その関係はどうでしょうか。","respondent":"日下部産業振興課長","answer":"ただ、先ほど申し上げた、商店街としてのダブルチャンスとか、いろいろ独自のキャンペーンにおいては、これは商店街独自に実施するものです。","voiceIndex":181,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"ここでお聞きしていいのかよくわからないんですけれども、昨年度の実績で言えば、そういった２億円分のもので、倍の発行をしているにもかかわらず、１９６万１,０００円とか、２,０００万円プラスありますけれども、ここで上がっているわけですよね。","respondent":"日下部産業振興課長","answer":"去年は２億円、今年は１億円、ところが、プラスアルファの経費の分は金額は２７０万円で変わらないということでのお尋ねですか。","voiceIndex":183,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"去年の場合には１９６万１,０００円というふうになっていますから、事業として縮小しているのかなと思うんです。２億円から１億円になっているのであれば、そういう部分でのＰＲとかが増えているのでしょうか。","respondent":"日下部産業振興課長、山田区民生活事業部長","answer":"平成１５年度は２,０００万円プラス１９６万１,０００円は諸経費です。今年は１,０００万円プラス２７０万円が諸経費です。ですから、プレミアムは半減しておりますけれども、諸経費の分については逆に少し多くなっています。基本的に商店街振興を大きな目的として、このプレミアム商品券を出すにあたっては、年末年始にあたっての商店街での消費の拡大、それから、共通商品券そのものをもう少し定着、ＰＲをさせていきたいという思いがありますので。","voiceIndex":185,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問","question":"券は買ったけれども、近くで使えるところがないという状況もあるかと思うんですけれども、今ある商店街の中でどのぐらいの商店でこの券を利用できるのでしょうか。","respondent":"日下部産業振興課長","answer":"実は今商店街の連合会に加盟をしております商店の数は４,１００ほどありますが、この共通商品券の取り扱いをしている店舗が２,２００ということで、５割強という状況です。","voiceIndex":188,"id":"exchange-060"},{"speaker":"井上委員","kind":"意見","question":"ということは、基本的には共通商品券の需要を拡大したいということであれば、２,２００店が増えるような、利用できるところを増やしていくような何らかの支援をしていかなければ、お金のかけることも違ってくるんじゃないかと思いますので、理由は、変動があるかと思いますけれども、そういうところもしていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-061"},{"speaker":"塚本副委員長","kind":"質問","question":"１割のプレミアムというのは、使うほうにしてみれば、大変なことだろうと思うんです。増えたというのが余計かかっているわけですね。商店街のほうでそれをお金を決済すると大変な手間になっちゃって経費がかかるでしょうから、例えば郵便局と契約して、その可能性があるのかないのか、そういう工夫はしたのかどうかということをまずお聞きいたします。","respondent":"日下部産業振興課長","answer":"結論から申し上げますと、副委員長が今おっしゃったような点については、実は商店街連合会自身としてもこの辺の問題意識を持っておりまして、今年、実は実施にあたって、今郵政公社ということで組織が変わりましたけれども、そちらの本部のほうと折衝をいたしまして。","voiceIndex":191,"id":"exchange-062"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"そうすると、高額商品を購入予定の人は、そういうことが先にあって、こんなにいい話があるからしようじゃないかということ、おそらくそういうことなんだろうと思いますけれども、購入の動機といいますか、昨年やってみて、普段の野菜を買うのにこれを使うということはあまりないと思うんですけれども、その辺のことは少しは情報が整理されているのかどうか教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"5万円が限度ということでありますけれども、実際にはどこで歯止めをかけるのかということを、正直言いまして、いろいろ商店街としてもなかなか歯止めをかける方法というのが難しいということで、その辺も今後の課題であると思います。","voiceIndex":193,"id":"exchange-063"}]},{"id":"topic-07","title":"豊能郡美化センターの廃棄物処理にかかわる件","agenda":"豊能郡美化センターの廃棄物処理にかかわる件","exchanges":[{"speaker":"菊地委員","kind":"提案","question":"要は、クボタとの契約の内容というのはどういうふうに変化をしていくのか、通常行政が係わった場合にはどういうふうになるのか、その辺を教えてもらいたいのが一つ。それから、もう一つは、現地で無害化処理ですか、一次処理の関係と、シンシアで運んできます、向こうで無害化処理をするのであれば、無害化のゼロリスクというか、その辺の処理形態というのが分かれば教えていただければと思います。","respondent":"金井環境課長","answer":"もし仮にシンシアが断った場合ですけれども、現時点ではクボタと施設組合は契約をしておりますので、施設組合とクボタの間で何らかの対応を図るということだと思いますけれども、これはすべて議会を通っておりますので、その辺いろいろ内容によっては。","voiceIndex":199,"id":"exchange-064"},{"speaker":"菊地委員","kind":"意見","question":"その辺が私はよくわからないんですが、一部を運んでくるみたいなことがあったりとか、あるいは向こうで一次処理というのをした後のものを全部こちらへ運んでくるという方法もあったように思うんですけれども、向こうで行われる一次処理というのは、本当に無害という形になるのであれば、こちらへ運んできて、わざわざ処理をする必要もないかなとも思うし、それこそ水洗いをして。","respondent":"金井環境課長","answer":"それについては私どもはよく聞いておりませんので、向こうで無害化の処理して、水処理等をやって、それから一定のものを除去したものもこちらに運ぶ予定になっておりますので、その辺の濃度というのは私どもは承知しておりません。","voiceIndex":201,"id":"exchange-065"},{"speaker":"菊地委員","kind":"意見","question":"いずれにしても、もし受けるとした場合に運ばれてくるものは、無害になったものが運ばれてくるというわけではなくて、実際には汚染されたものを運んできて処理をするんだというのが、まず前提にあるんですよね。","respondent":"岩崎環境清掃事業部長","answer":"８月の末に向こうが来たんです。来て、何と言ったかというと、特別管理の３ナノはクリアできないと。クリアできない理由としては、向こうの一次処理とか、前処理とか言っている工程の中に取り込めないものがある。","voiceIndex":203,"id":"exchange-066"},{"speaker":"菊地委員","kind":"質問","question":"それが前提になるのかあれですけれども、この間一般質問の中でもいろいろ議員から出されておりましたけれども、大阪地裁での６月の和解協議の中で、品川区はシンシアに運んでくることを前提にして和解が成立してきたという経過がありますけれども、大阪地裁での、原告のほうと美化センターとの和解の条件としてこういうものが出されたというのは、シンシアには何の問題も出てこないんでしょうけれども。","respondent":"金井環境課長","answer":"それで協議がきておりますので、それによって、裁判の和解によって変更するようなものであれば、非常にありがたいんですが、当初からそういうふうにきていますので、裁判のどうのこうのという問題については。","voiceIndex":205,"id":"exchange-067"},{"speaker":"山村委員","kind":"質問","question":"疑問に思っているんですけれども、ダイオキシンが運ばれてくるということで騒がれているとは思うんですが、ダイオキシンというのは大体１００種類あって、その中の７種類のみが人体に有害であって、その人体に有害なダイオキシンだけを、要するに、人体に有害なダイオキシンが運ばれてくるのか、それとも体内に蓄積されて有害でないダイオキシンと、人体に有害なダイオキシンが一緒になっているとか。","respondent":"金井環境課長","answer":"大変難しい質問で、それについては正直言って承知しておりませんし、それがどういう物質で、ダイオキシンの中の、今おっしゃったような物質なのかどうか、該当するのかどうなのかというのは、承知しておりません。","voiceIndex":207,"id":"exchange-068"},{"speaker":"山村委員","kind":"意見","question":"要するに、いわゆるダイオキシンが含まれているものが運ばれてくるということですね。そうすると、結局、そこの中の汚染物質が何％あるかというのは、つまりダイオキシン中というのがどのぐらい汚染されているかというのは調べてないわけですね。","respondent":"金井環境課長","answer":"それは私どもはもちろん権限も話も何もないんですが、一般廃棄物だけしか事前協議としてきておりませんので、ただし、持ち込まれるのは産業廃棄物という指定のものが多いんですけれども、そういった部分も含めて。","voiceIndex":209,"id":"exchange-069"},{"speaker":"山村委員","kind":"質問・要望","question":"ダイオキシン、ダイオキシンと言うけれども、ダイオキシンが全部が有害なわけでないわけです。基本的に体の脂肪のところにたまるんですけれども、ダイオキシンの中で約１割程度のものが有害なわけで、すべてダイオキシンが有害なわけではない。その有害濃度がわからないと、どのくらい危険かというのはわからない。そこら辺のことは、向こうが知っていれば聞かれたほうがよろしいかと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-070"},{"speaker":"井上委員","kind":"質問","question":"やっぱりこの委員会に説明をしてほしいというところでは、ただ危ないからダイオキシンを持ってくるのはやめてくれという話ではなくて、区民の健康に直接係わるものがくるということで、区民が不安に思っていて、そのことを聞きたいと思ったときに、どこにも問い合わせるところがないという意味では、区民委員会としてこのことを、経過を説明するんじゃなくて。","respondent":"岩崎環境清掃事業部長","answer":"先ほど申し上げましたように、３ナノは超えるというご説明をいただいたので、それではそちらでやってもらいたいというお返事をしたということです。","voiceIndex":212,"id":"exchange-071"},{"speaker":"井上委員","kind":"提案","question":"その辺は強く主張していただきたいんですが、豊能町の町長選挙がきのうありまして、日下町長が再選をされたということで、施設組合長でもある日下町長ですから、なお強硬にこちらにそういう働きかけが多分あるのではないかと思うんですけれども、私の一般質問のときに、議員には説明はしましたという答弁をいただいたんですけれども、聞きに行ったときにはいただいたりしているけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-072"},{"speaker":"塚本副委員長","kind":"質問","question":"正副委員長のほうで、一般質問があるなしにかかわらず、井上委員の要請に基づいて、この委員会で報告できるようにという調整はしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-073"},{"speaker":"井上委員","kind":"質問","question":"今回はいいんですけれども、前回、切り替わりの前に区民委員会で、３月ぐらいから問題としては出ていたわけですから、委員会に出してほしいということで委員から発言があったと思われるんですが、そこで理事者の方からお話しいただけなかったのはなぜなのかなというのをお聞きしたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-074"},{"speaker":"井上委員","kind":"確認","question":"豊能郡のほうで無害化処理技術検討会というのが１１月から４回行われていますけれども、無害化処理の技術検討委員会の議事録を見ますと、資料の経過にありますように、１０月に品川区にどうだろうかという打診がきたときに、向こうのほうでは、大阪で反対しているものを品川区に持って行くということは、品川区でいいと言うはずがないではないかという議論の中で。","respondent":"金井環境課長","answer":"勘違いをちょっとされているのかと思いますけれども、私どもは区民のほうに情報を提供しましたよという答弁で、うちの課はしておりますけれども、自治会連合会に情報提供をしていますよということを答弁ではお話ししていると思いますが。","voiceIndex":218,"id":"exchange-075"},{"speaker":"井上委員","kind":"質問","question":"環境問題で言えば、シンシアは産業廃棄物の処理施設ですから、これを教訓に出し方についてどういうふうに考えて、当事者ではないから答えられませんということではない出し方をしてほしいと思うんですけれども、そういうことについてはいかがですか。","respondent":"金井環境課長","answer":"それは私どもよく言っていますように、事業者責任というのは法律的にも明確になっているわけですから、事業者が責任を持って説明をしないと、そこの住民が得た情報が本当に正しいのかどうか、そういったことも行政がやる場合には、明らかに変更があるとか、出所が正しい。","voiceIndex":220,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問・要望","question":"今シンシアでは受けないということですから、品川区としては施設組合に対して、こういう計画であるということを決定をしてからではなくて、今回の場合には、シンシアは受け付けていませんけれども、状況が変わったときには、施設組合に対して、品川区の中から説明責任、品川区にお願いしたいところですけれども、施設組合がすべきだというところでいらっしゃるようですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-077"},{"speaker":"塚本副委員長","kind":"意見","question":"施設組合のほうがシンシアに持ってこようとして、当初計画をしていたものの中身は、ダイオキシンがどの程度なのか、ここではわからないという話ですけれども、一般廃棄物と産業廃棄物というふうに分けていくと、どういうふうな内容になっているか。","respondent":"金井環境課長","answer":"一般廃棄物が約二十五、六ｔ、これが協議の対象ですので、通知があるとすれば、その分が追加になる。そのほかに約２２０ｔが品川区内で処理という予定だそうですので、そのうちの残りが産業廃棄物という形になります。","voiceIndex":223,"id":"exchange-078"},{"speaker":"塚本副委員長","kind":"意見","question":"産業廃棄物をほかの地域で処理しようとした場合は、どういう手続きになりますか。","respondent":"金井環境課長","answer":"ご案内のとおり、東京都の産業廃棄物は他県に全部どんどんいっていますので、関東圏の人たちの産業廃棄物関係は他県にいっているという、そういうことも我々はよく承知をしておかなければいけないかなということです。","voiceIndex":225,"id":"exchange-079"},{"speaker":"塚本副委員長","kind":"質問","question":"そうすると、大阪府の広域自治体は東京都に対して何の通知をしなくてもいいという、産業廃棄物の部分に関してはそういうことなんですか。","respondent":"金井環境課長","answer":"許可とか、そういうことはございません。","voiceIndex":227,"id":"exchange-080"},{"speaker":"塚本副委員長","kind":"質問","question":"私が思うに、一般廃棄物より産業廃棄物のほうが有害物質を含んでいる可能性が大いにあると思うんですけれども、そのことに関しては自己責任で処理して、自治体はそれを監視する役目だということで、お互いにどういうふうにしようが、自治体は特別関知しないというスタンスなんですね。ダブルスタンダードになっているんじゃないかという心配があるんですけれども、それはどうですか。","respondent":"金井環境課長","answer":"法律的な流れから言いますと、施設組合のほうで無害化処理技術検討委員会という、今の事業の流れから言いますと、大阪府のほうでこの処理に対して、無害化処理技術検討委員会というものもできておりますし、その中で全国から公募をしまして、その中から安全で。","voiceIndex":231,"id":"exchange-081"},{"speaker":"塚本副委員長","kind":"提案","question":"もう一つ、最終的に無害化、あるいは何らかの処理をしなければいけないことになると、そういう能力のあるところがどれほどあって、能勢町のほうの立場にしてみたら、ほかに選択肢はどういうものがあるのかということも、どこかほかにそういう施設がありますよ、値段の交渉でシンシアに行ったほうが安いからクボタは安く提案したんですよということなのか、ほかに選択肢がなくて。","respondent":"金井環境課長","answer":"焼却溶融する施設が全国に限られていると言いますか、その中の一つであって、クボタのプラントが入っている。そういう流れの中で選定をされたというようなことは聞いておりますが、１００％正解かどうかわかりませんけれども、そういう話は聞いております。","voiceIndex":233,"id":"exchange-082"},{"speaker":"塚本副委員長","kind":"質問","question":"能勢町の立場で、ほかにどういう選択があるのかということは、一般的な情報として分かるわけですから、それを我々に伝えられるだけの力はあなた方は持たないんですか。部長はどう思いますか。","respondent":"岩崎環境清掃事業部長","answer":"今の時点ではまだ詳しい状況、クボタ関連会社というのはほかにないのかとかというようなことというのが、向こうが言わないものですから、まだ課長も、私も答弁できないという状況だです。","voiceIndex":235,"id":"exchange-083"},{"speaker":"塚本副委員長","kind":"質問","question":"それはクボタ関連のほうが出たんでしょうけれども、そういうことは場面が厳しくなって、ほかの選択肢があるでしょうという話、要は値段の問題だけですかという話になるわけで、どれだけ状況が厳しいかということを、ここしかありませんということになったら、それは大変なことになる。そんなことも、ほかにないというようなことでは困っちゃうということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-084"},{"speaker":"山路委員","kind":"質問","question":"シンシアと豊能町のクボタとの関係が特別にあるので、さっきの説明では、シンシアの中にクボタのプラントが入っているので、そういう施設があるので、品川区のほうにも目が向いているということは、あくまでも想像ですけれども、考えられないでしょうか。これは疑問ですけれども、選択肢がほかにないから、こっちを向いたということでしょうか。","respondent":"金井環境課長","answer":"施設組合のほうで、住民の検討委員会を、説明を別個に設けて、その中で、こちらが一番安くて、効率的というような話があるようですけれども、そういうことで選定をされたという経過ですので、その辺がどのようになっているのかというのは、これからはちょっと見えませんけれども。","voiceIndex":238,"id":"exchange-085"},{"speaker":"山路委員","kind":"質問・要望","question":"クボタが向いているわけですから、品川区のシンシアのほうにも向いているんじゃないですか。プラントだけでなく、特別な何か出資しているとか、クボタとシンシアというのはいろいろな関係があるんじゃないですかということなんです。の３社の２社というのがもし分かっていたら教えていただきたいと思います。","respondent":"金井環境課長","answer":"２社については承知しておりません。","voiceIndex":240,"id":"exchange-086"},{"speaker":"菊地委員","kind":"質問","question":"向こうの施設組合にすれば、シンシアに１回断られたから、それで終わるわけではないんだと思うんですけれども、今後実際にこの施設組合が、シンシアやクボタとやっている協議内容というのは、情報として品川区に一つ一つについて入ってくるものなんだろうか。そこだけ教えてもらいたいと思います。","respondent":"金井環境課長","answer":"施設組合から連絡があります。クボタからシンシアとの協議を開始しました、いつ頃から予定ですというのは、私どもに入ってきます。その協議の結果も先般メールをいただきました。大変厳しい状況になっておりますけれども、引き続き協議をいたしますという話はきてあります。","voiceIndex":242,"id":"exchange-087"}]},{"id":"topic-08","title":"リサイクルショップ リボン","agenda":"リサイクルショップ リボン","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"この委員会の中でも経緯について出てきていない部分が非常にあったものですから、私のほうとしては、現状がどうなっているのかも含め、ご説明いただきたいと。バリアフリー等々もあってね。それが本当に営業の中に、見た目は開放しているようによく見えているんですが、実際はそうではない部分のほうがあるのかなという、販売実態のところもどう捉えていらっしゃるのか、ちょっとお聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"それに対して、スタッフのことで言いますと、約半分ぐらいですね、最低の人員確保という面もありますから、確保しなければいけないという意味で言えば，それぞれ課題がある大井町店の状況というのは、企業経営感覚からすると、より課題が大きいという認識は持っております。","voiceIndex":250,"id":"exchange-088"},{"speaker":"原委員","kind":"質問・要望","question":"今お話を聞かせていただいて、確かにスペース、そして販売品目等々からすると非常に難しい部分を抱えているのかなというふうに思いました。ある意味ではリサイクルの部分だからそれがいいのかというところもあるわけでしょうけれども、その辺も今後の中の改善方法を考えていく必要があるのではないかという、一つの課題として考えていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-089"},{"speaker":"塚本副委員長","kind":"質問","question":"入れ替えのときはかなり大仕事ですから、大きな模様替えに関するいろいろなことを考えると、新しい物を買うのを決めて、もう要らなくなったものをどうしようかというという思いもあるし、スペースの問題や何かわからないということで、手順がどうなっているか、ここにありますよと、すぐ指定してくれて、運ぶのはだれで、４週間経ったときに引き取れというのか、その辺の流れをちょっと教えてもらうと。","respondent":"中山清掃リサイクル課長","answer":"４週間以内の展示の中で、これは先着順でお客に売るわけですけれども、特に家具についてはお持ち帰りは原則まずないですから、速やかに引き取ってくださいというふうにお願いを店舗のほうでするわけですが、できるだけ早くということで、これは逆に、４週間という形ではなくて。","voiceIndex":253,"id":"exchange-090"},{"speaker":"塚本副委員長","kind":"質問","question":"そういうことをやって、四、五千円の対価を得るということがどういうことか。だれかに使ってほしいという思いが強くないと、つまり自分のところは要らないわけですから、そういうことから言うと、もう一つ何か余裕といいますか、供給者サイドのことを考えた流れの中に余裕がないから、いい物が集まってこないし、売れないという点を指摘したいんです。","respondent":"中山清掃リサイクル課長","answer":"その辺でリサイクルショップの買い取り方式に比べると、スピード感もあるし、値段的にも２割を手数料で取るというのは、普通に考えますと、利用者の方の、当時はリユースという形はなかったんですけれども、リサイクルを促進をしようということで。","voiceIndex":255,"id":"exchange-091"},{"speaker":"井上委員","kind":"質問","question":"管理運営のところで、ちょっと経過がわからないんですが、エコ企画という運営団体がどういうものなのかということ。平成１３年から都市整備公社に委託された、どういう形でこうなったのか、公募でこうなったのかとか、管理者のことでお伺いいたします。","respondent":"中山清掃リサイクル課長","answer":"７,０００万円近い売上等を考えますと、公社の公営企業会計とか、管理運営、それから、旗の台店については住宅併設だったんですが、住宅の管理も都市整備公社がやっておりましたので、１階部分の店舗についても具体的に管理をお願いしようということから。","voiceIndex":257,"id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2404#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":64784,"voices":265}},{"id":"h16-20040927-7","meetingId":"h16-cm09","date":"2004年9月27日","dateIso":"2004-09-27","committee":"厚生委員会","time":"午前１０時０４分～午後２時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"築舘委員","kind":"質問","question":"それに関して、補正を今回組んで１月１日からやるようになるということが補正を組む理由だというふうに思いますけれども、その点、補正を組んでまでやることになった理由というのがもう一つわからないということが一つです。","respondent":"辻田児童課長","answer":"ところが、今回子育て支援ということですべてになりますので、いわゆる目的の変更、子育て支援へ一歩大きく踏み込んだということでご理解いただきたいというぐあいに考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"築舘委員","kind":"質問","question":"今回こういうことで所得制限をなくすということは、ほかの例えば福祉に関して所得制限が設けられているところもあると思うんですが、そういうことに関しての影響も多少出てくるというふうに思うんですが、全く所得制限をなくすということに関して、これは一貫してほかの福祉施策に関してもその方向をとっていくということでよろしいですか。","respondent":"辻田児童課長","answer":"これは国のほうでも今回児童手当を小学校の３年生まで拡大いたしましたけど、基本的にその部分ではいわゆる所得制限の少しずつ上限を上げている部分はありますけど。","voiceIndex":7,"id":"exchange-002"},{"speaker":"築舘委員","kind":"質問・要望","question":"ですから、その点、予算、もちろん品川区は黒字だということで健全財政をとっているので、そこに関しての施策を打てたというのが今回ある意味では現状としてはいい状態にはあったと思うんですけど、今後あらゆる面で今後ずっと子ども支援をしていくということになると、それだけの予算もしっかりとかかるということですので、そこの部分をもちろん計算されて踏み切ったんだというふうに思いますけど。","respondent":"辻田児童課長","answer":"一つ一つの事業を検討する中で、これがやはり乳幼児医療費のサービスアップにつながっていくんだというような認識のもとで、そういうような議論をいつもしているです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"拡大については、これは当初から９０％という定義ができる以前から全対象にということは議会側からも発信をしていたと思いますので、拡大ということについては、ほんとうによしとするところなんですが、それでちょっと確認なんですが、今年度３カ月ということなんですが、１月１日から、３カ月につきまして、当然対象枠が広がったということで、事務的な部分についてお聞かせいただきたいんですが。","respondent":"辻田児童課長","answer":"まだ現在、今その辺で詰めているわけですけど、私どものほうとしては、その辺について期待を持っているわけで、多分来年の４月からは今の乳幼児医療費助成制度と同じような２３区でどこでも使える。","voiceIndex":11,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"引き続き協議をよろしくお願いいたします。それから第８条なんですが、届出、今までの義務から届出ということで、年齢的には子どもが全部対象になるからということだと思うんですが、あえて義務というのを外したということをちょっともう少し詳しく教えていただきたいんですが。","respondent":"辻田児童課長","answer":"どちらかというと、これは制度改正や何かをやって文言を見直しする中で整理されてきたですけど、届けなければならないというような形で確かに義務的な部分はありますけど、これはあまり届出義務というような形できつい文言を使うより。","voiceIndex":13,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"例えば国民健康保険なんか、ちょっと話は変わりますけども、国民健康保険の保険料とかの値下げで、千代田区や渋谷区が独自な考えを出したときに、それはそれで基礎的自治体になったわけですから私はいいと思ったんですが、どうしてもそういった何か目立つ特色があることをやると、２３区の中からちょっと横の一線をもうちょっと配慮してくれというような声が出る場合があると思うんですが。","respondent":"辻田児童課長","answer":"そういう中では、マスコミ関係につきましてはやるということで大々的に報道されまして、それでどういうわけか一たん２月以降ずっとやってきたわけですけど、またちょっと前ですね、８月ぐらいにまたもう一度この部分でマスコミ関係の取材等もございまして。","voiceIndex":15,"id":"exchange-006"},{"speaker":"嶋委員","kind":"質問","question":"先ほども課長のほうから医師会のほうも大変協力的というか、ございましたけど、医師会の反応とか医療の内容とかがこれからちょっと変わる、変わるということはあってはならないんでしょうけども、そういう心配と、またあと対象者、第５条のいろんなところに出ていますけれども、対象者、乳幼児を養育している者が対象者になったですが、対象者はどのぐらい。","respondent":"辻田児童課長","answer":"２項以降は除外規定ということで、この方たちは生活保護による保護を受けている方とか、こういう方は別の形での助成が出ますので、そちらのほうで処置をするという形になってまいります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひまたこの２３区どこでも使えるというのができたらほんとうにうれしく、私どものほうにも各区からどのように品川区はこれを進めてきたのかと聞いてくる方もたくさんありますので、ぜひこの２３区どこでも使えるようにご努力をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今ご説明の中で、児童福祉の増進から、子育ての支援への政策の転換ということでご説明がありましたけれども、すべての子育てを応援していくという意味で、ほんとうに大きな前進だと思って歓迎をいたします。よかったなと思っています。地方の財政が圧迫してはいけないのでこの辺の今都と国のところの動向がわかっている範囲がありましたらお知らせをいただきたいと思います。","respondent":"辻田児童課長","answer":"国および都の動向ですけど、都はこれについて何とか２３区で使えるような形でできないかということで打診しましたところ、大変協力的に国保連合会との間、それから医師会との間をいろいろ取り持っていただきまして、大変スムーズに今打ち合せは進んでいるという状況です。","voiceIndex":20,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"１点ちょっと具体的なところで聞きたいのは、第７条の２のところの文言のところで、ちょっと具体的にこれはどういうことなのか教えていただけたらと思います。","respondent":"辻田児童課長","answer":"ですから、個別に応じ、必要に応じて実施するという形、今までは毎年大体７月から８月にかけてこれを実施してきたです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保険の加入要件ということなんですけど、たとえ、ちょっとよくわからないので、例えば国民健康保険などで保険料が払えない、困難な家庭の状況とかが生まれたときに、この子どものところはどうなるのか、具体的にちょっと教えていただきたい。","respondent":"辻田児童課長","answer":"この場合は、その保険料は支払うのが困難かどうかというようなことを調べるのではなく、どの保険に加入をなさっていて、どこに請求をすればいいのかというようなことのための調査です。","voiceIndex":24,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"２点お聞きしたいんですが、直接これに関係ないかもしれないんですけど、医療証の交付のところで、今現在の乳幼児医療のほうの乳)の医療証の交付なんですけども、ちょうど今時期的にやっていらっしゃるかと思うんですが、１０月１日から切り替えかなというふうにちょっと思っているんですけど、何人かの方から、まだ医療証が新たなのが来ていないというようなお話を聞いたりしているんですけど。","respondent":"辻田児童課長","answer":"今回まだ届かないという、事務作業は当然やっておりますので、個別に届かないというケースがあれば、確かにまだ届かない、１日にまたお医者さんに行かなければというご心配がありますでしょうから、区のほうに個別に確認していただければ、私どもは対応していくです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"１点目のほうですけど、去年も実はちょっとそういう、苦情までいかないんですけど、実際にはぎりぎりに届いているということなんで、やっぱり中にはやきもきされる方がいて、今課長がおっしゃったように１０月１日に届いていないと、そこで大きなけが、病気をしたときにどうなるんだとか、そういう心配の声を結構聞いていまして、今年もそういう声もちょっとあるものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"南副委員長","kind":"質問・要望","question":"財政的な部分はかなり４億円というのがプラスされるところで、かなり大変だとは思いますけども、ほんとうに区民に喜ばれるそういう施策をこれからもどんどん広げていただきたいということをちょっと１点要望しておきたいというふうに思うんです。それともほかに何か通知、周知というのはほかに考えていらっしゃるんでしょうか。その点、１点だけ伺います。","respondent":"辻田児童課長","answer":"できる限りの形ですべての子どもたちに情報が受けとめられるような形での情報発信をしていきたいと、ＰＲをしていきたいというふうに考えております。","voiceIndex":29,"id":"exchange-014"},{"speaker":"本間委員","kind":"質問","question":"日本のお金の使い方をもうちょっときちんとしないと、必ず将来赤字になるよというような、いわゆるある種の警告といいますか、そういう部分が出たというふうなことで、そのことは一つ頭に置きながら、もちろん国が必死になって先ほども出ましたように１.２９以降新たな決意を持っていろんな施策を展開してきているわけですし、地方自治体も各地域の企業等関係するところと力を合わせながら。","respondent":"辻田児童課長","answer":"ただ、品川区としての区域でのエリアはありますけど、やはりこういうことを実施していくということで自治体として子育て支援に真剣に取り組んでいるんだというようなことは後からもちょっとご説明ありますけど。","voiceIndex":31,"id":"exchange-015"},{"speaker":"本間委員","kind":"意見","question":"これからいろいろ新たな課題といいますか、部分の中で、常に品川区は２３区の自治体のみならず、全国の地方自治体の中から注目される、いわゆる先頭を走っているだけに注目される地方自治体となっているだけに、その辺も大変ご苦労が多いと思いますが、ぜひその辺も頑張っていただいて、今後の皆様方のご努力に期待をしておきたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"この福祉基金といいますと、寄付をしていただいた方のお名前が載るということなんですが、この基準といいますか、金額のラインとか、その辺について教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"この基金の基準ですが、概ね５００万円以上のご寄付があって、なおかつ寄付者の方からこれこれにしてくださいというような特定の目的があればそれに使わせていただきますが、一般的に福祉にお役立てくださいというような趣旨でのお申し出があったときに。","voiceIndex":39,"id":"exchange-017"},{"speaker":"本多委員","kind":"質問","question":"大体５００万円以上のご寄付をいただくと、この条例改正でお名前を載せていくということなんですけれども、例えば親から子へ譲渡なんかをして、この子どもの名前での寄付金とか、そういったケースは今までないと思いますけども、そういう場合とか、あくまでこれはご本人ということで条例改正はしていくということでいいんでしょうか。","respondent":"早津高齢福祉課長","answer":"そのときはご本人は亡くなっておりますので、実際に寄付される方は子どもさんということになるわけですが、寄付のご遺志はそもそも亡くなったご本人にありますので、ご本人のお名前にしてこの基金が設置されてあります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"築舘委員","kind":"意見","question":"この品川区の社会福祉基金の条例の新旧対照表のところに、単に社会福祉基金という方もいるし、今回は障害者用社会福祉基金ということになっているんですよ。そうすると、障害者用というふうになると、使われる範囲というか、決められちゃうのかということと、それから、それが本人の意思でそういうふうな使い分けになっているのかということですね、その点、お願いします。","respondent":"西島障害者福祉課長","answer":"特に障害者用にというご希望がございましたときには、障害者用社会福祉基金として設置をするということになってあります。","voiceIndex":43,"id":"exchange-019"},{"speaker":"築舘委員","kind":"意見","question":"そうしますと、障害者用に使われるということで限定されてくるわけですね。それであと、基金をずっとあれしているんですけど、使われるときに、またこの終わったというか、基金は使われたときにはそのままどういうふうになっていくのか。名前だけ残って、それでそのまま、でも基金からは外されちゃうわけですよね、なくなってくる。","respondent":"早津高齢福祉課長","answer":"条例の規定では、この本体自体を取り崩すことは可能ではありますけれども、現時点では果実運用型の運用をしているです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"使途について具体的にちょっとどういうところに使われているのか教えていただきたいのと、あと先ほど５００万円以上がこの基金にお名前が載るということなんですが、５００万円以内のときは、そういうご寄付があったときはどこに入るのか、ちょっと教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"それから５００万円以内である場合は、そのご寄付の方のご意思ですね、どういうふうなのにお使いいたしましょうかというようなことをいろいろご協議した上で、例えば車いすですとか、そういったものに使わせていただくということになります。","voiceIndex":47,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特定財源で、あと不足分を一般財源、ちょっと具体的に使途、幾つか、あっこういうことに役立てられているんだなという、ちょっとわかるご説明をしていただきたいんですけど。","respondent":"早津高齢福祉課長","answer":"特定の例えば障害者用の何かの施策とかというまでは明確にはなってございません。一たん、お金には色がありませんので、利息としてこれこれ３００万円ぐらいがついたとすると、それが障害者の施策の中に盛り込まれていると、こういう形です。","voiceIndex":49,"id":"exchange-022"},{"speaker":"築舘委員","kind":"質問・要望","question":"それが１点。そしてあと、企画財政課で歳入を一括計上というのはどういうふうな意味か、ちょっと教えていただきたいということと、それから、区立の大井保育園のことに関しましては、保育園の児童が増えてくるわけで、そうすると、先生方というか、人材に関してはどういうふうにそれに対して付随してくるのか、その点をお聞かせください。","respondent":"早津高齢福祉課長、辻田児童課長、金子保育課長","answer":"社会福祉基金の収入がどこかということですが、前ページの１２ページ、繰越金の中の一部がこれに当たります。補助金の関係ですけど、ちょっと先ほど説明が早口でしたので大変申しわけなかったと思うんですけど、都を経由して国のほうが補助金を出すということです。大井保育園の増員後の職員のご質問ですが、単純に計算しますと、従来よりも２人職員が必要にはなりますが、従来から私ども保育園全体の保育士。","voiceIndex":60,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子育て支援総合推進モデル事業についてなんですが、中身を検討中ということで、具体的にはお示しがなかったわけですけれども、次世代育成の行動計画を今年度中に作成するという段階で、先ほど整合性を持ってやっていくということなんですけれども、その辺、なぜ今この時期にこの中身を国のモデル事業というのはあるんですけれども、今一本区のほうで考えているところに、これは補助金はついていますけれども。","respondent":"辻田児童課長、金子保育課長","answer":"時期ですけど、２番目はなるべく早くということで、何とか年度内に実施してくれないかというような形での要望等があります。取組事例集につきましては、年度末までというような形での期限かというぐあいに考えております。私ども保育園に関しては、委員もご案内のとおり、待機児が数多くいるということから、これの解消も早急に進めなければならないということから、今回ご提案を申し上げているところです。","voiceIndex":64,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"特に企画の部分のところだとは思うので、ここでご答弁はなかなか難しいと思うんですが、何かあまりよく事業の内容とか、今のこの時期、取り急ぎやるところがどうなのかなとちょっと疑問が解けないので、その辺もう一点と、あと大井保育園の改修については、耐震診断の結果がもうじき出るということなので、あわせて工事が進めばいいのではないかなと思うんですが、一つ３階建てというところで。","respondent":"辻田児童課長、金子保育課長、小沼児童保健事業部長","answer":"少なくても全国の中でモデル市町村として指定を受けるというのは。ソフトに関しましては、これから細かいところも詰めてまいりますが。これは国のほうが言っているとおりなんですが、それと同時に、従来この間、おかげさまで長期の総合実施計画等を含めて。","voiceIndex":67,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大井保育園の改修についてなんですが、先ほども人員配置のことでさまざまな工夫ということなんで、ぜひいい方向で工夫をしていただきたいのは、特にここの保育園に伺ったら、３歳、４歳、５歳、１人担任であるということで、保育の形態はさまざまだと思うんですけれども、特に３歳児が１階のフロアに１クラスでいるというあたりでは、人員配置がとても大事だと思うので。","respondent":"金子保育課長","answer":"定員増につきましては、こちらのほう、予定によりますと１０月には工事が終わるということで、工事が終わり次第定員増については実施していきたいと考えています。","voiceIndex":71,"id":"exchange-026"},{"speaker":"嶋委員","kind":"質問・要望","question":"子育て支援総合推進モデル事業ということで、全国で４９カ所の中に品川区が手を挙げていただいたということで、大変うれしく思っております。それから、大井保育園改修工事ですけど、工事期間中に保育園も開設されているということで、安全面とか、ちょっとそれをお聞かせいただきたいことと、それから２９名の待機の解消を図るということで大変うれしく思います。","respondent":"金子保育課長","answer":"ですので、直接声を確認したわけではありませんが、その意味では、大井倉田保育園に集中している部分をある程度解消できるのと、やはり大井町近辺、従来から五反田、大崎のあたりは人気が高くて、これについてもさまざま定員増等の施策展開をしていますが。","voiceIndex":73,"id":"exchange-027"},{"speaker":"嶋委員","kind":"質問","question":"ぜひ安全面、また調理室も大きく拡充されるということですので、これも大変かなと思いますが、ぜひ安全、無事故でお願いをしたいと思います。それから、３番目の近隣ですが、そういう意味では大井倉田保育園に集中していた分が分散されて、喜ばれる、保護者にとっては大変うれしいことですが、住宅街ということもありまして、そういう意味の近隣ということでお聞きをしたんですが。","respondent":"金子保育課長","answer":"この施設は３階は先ほどから申し上げているとおり学童保育クラブとして使っていましたので、子どもの声あるいは日常活動そのものを、言葉は悪いですが、騒音ととらえれば、これは従来から同じかなとは思うんですが。","voiceIndex":75,"id":"exchange-028"},{"speaker":"南副委員長","kind":"質問・要望","question":"それで、多目的室が南のほうに、園庭にすぐ出ていますので、３歳児という年齢の発達状況から見ると、やっぱりもう少し南側であってほしかったし、園庭にすぐ出れるような、そういうところに設定してあるべきじゃないかなというふうに思ったんですけど、構造上のいろんな検討した段階で、こういう選択をせざるを得なくなったんだろうというふうには承知しますけれども。","respondent":"辻田児童課長、金子保育課長","answer":"ただ、次世代支援育成、地域行動計画の中では、当然その企業との連携ということにつきましては、十分検討していきたいというぐあいに考えております。食事については、この３歳、４歳、５歳については右のランチルームを使うというのを基本にしておりますので、そのようにご理解いただければというふうに考えてあります。","voiceIndex":77,"id":"exchange-029"},{"speaker":"南副委員長","kind":"質問・要望","question":"保育園のほうですけども、特に乳児のほうについては、二つのグループ分けをして保育をするものではないというふうな趣旨で聞きましたけども、年齢と発達状況によって、この集団数というのはやっぱりかなり厳しいところがあるというふうに思いますので、ベテランぞろいですから、その辺はあえて私が言う必要もないことですけども、やっぱり安定した環境を整えた中で保育活動ができるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-030"},{"speaker":"本間委員","kind":"意見","question":"１点だけちょっと気になることがありますので。私どものほうの数字でいろいろあそこは、北側、いわゆる正面からの裏側の北側と、それから表面から向かって右側、東側の部分からちょうど入る道路が１メートル弱ぐらいのところでずっとかぎ型になっていますよね。これを見ますと、どうなんでしょう、改修と書いてあると、中だけの工作で、道路の部分は頭に入れないでできるのかどうか、ちょっとその辺だけ。","respondent":"金子保育課長","answer":"今回建物に関しては内部の改修だけで、増築というのは一切考えておりませんので、その周辺というのは特にいじる予定にはしておりません。","voiceIndex":81,"id":"exchange-031"},{"speaker":"本間委員","kind":"質問・要望","question":"ちょっと現実の認識が違うかなという感じですね。立会道路はもともとあそこはオートバイは通れませんよ。だからゆえにあそこを通ると、こういう感じのものがあります。オートバイはだめですというふうな、これはどうでしょうかね、地元の人たちの使い勝手でお互いに大きな事故も聞いておりませんけれども、やはりあそこは非常に音を耳をすませながら走らせる道路なんですよね。","respondent":"金子保育課長","answer":"ですので、あそこは、私道で、私どもの敷地という関係になるかと思うので、道路として整備するのは非常に難しい問題があるかと思いますが、ただ、現実に通っていらっしゃる方というのは結構いらっしゃるのは私も承知しておりますので、安全面に関しては。","voiceIndex":83,"id":"exchange-032"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"月額の平均にしてのご説明なんですが、入園したときから何年間か入っている間の、その月額平均については公私格差が縮んできたということでよくわかったんですが、入園時とか卒園するまでの期間では、どのくらいのまだ格差が残っているのか教えていただきたいんですが。","respondent":"金子保育課長","answer":"それ以外に教材費あるいはさまざまな園の制服等々の費用がかかってくると思いますが、それについては細かい計算をしておりませんので、申しわけありませんが、全体としては今の入園料の感じがメインになるということと、それから保育料の補助については。","voiceIndex":92,"id":"exchange-033"},{"speaker":"本多委員","kind":"質問・要望","question":"乳幼児を預かる幼稚園側ですね、こちらのほうの、３番目のほうの説明で、幼稚園協会には３５０万円の補助金というふうにあるんですが、請願の文章の中でもわかるように、幼稚園側の負担もまだまだ解消されていない部分というのがまだ数多くあろうかと思いますので、できる範囲で引き続き請願の趣旨に沿って取り組んでいただきたいと思いますが、そこで一つだけ確認なんですが、国の三位一体のほうの改革で。","respondent":"金子保育課長","answer":"東京都については、ご案内のとおり財政改革ということで、補助金全体の見直しが今進められているというふうに聞いておりますが、私ども所管課のほうに個別にお伺いしたところでは、東京都の保護者補助金については見直しは予定していないというふうにお伺いしているんです。","voiceIndex":94,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のところと少しダブるんですが、概要のところを見させていただきましたら、私立幼稚園と補助のところで、今の都の制度と国の制度と二つありますよね。これはどちらを受けられるのかというか、その辺、先ほどの平均の補助の金額からすると、どちらかということなんです。その辺、ちょっと基本的なところを教えていただきたい。","respondent":"金子保育課長","answer":"先ほどちょっと保護者の視点に立ってどのようなふうに補助が出るかということで申し上げました。と言いますのは、非常にちょっと国と東京都の基準が一致しているところもありますし、ちょっとずれているところもありますので、非常に説明が煩雑になるので簡単に申し上げました。","voiceIndex":96,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"というと、この概要のところだと、区の負担をしているのもどこかに入っているということなんでしょうか。その辺がこれを見た限りではすごくどこからお金が出ているのかよくわからないんで、すみません、もう一回そこのところを。入園料の補助金というのは、これは都ですか。これも分担があるんですか。","respondent":"金子保育課長","answer":"全体の４割の方が補助の対象になっているということでご理解いただきたいと思います。","voiceIndex":98,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目、預かり保育についてなんですけれども、幼稚園でも多用なニーズに応えてということで、きんだぁくらぶですか、実施していて、働くお母さんたちも幼稚園のところで子育てができるという面で活用されていると思うんですけれども、この辺で今品川区内でこの預かり保育をしているところが何カ所あって、１園にどのくらいのお子さんたちが活用されているのかと、どの程度の補助が、支援がされているのか。","respondent":"金子保育課長","answer":"きんだぁくらぶ、これはきちっと統計をとっておりますので、このきんだぁくらぶに関しては、昨年度まで８園やっておりまして、現在５月の終わりで聖美幼稚園が廃園になりましたので、７園が実施しております。","voiceIndex":100,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"１園減って７園というところで、区の補助が１園１００万円ということで、預かり保育をすると、時間が延長されて結局職員の確保もなかなか大変なのではないかなと思うんですが、その辺で７園というのは、全体の中で利用が増えているのかどうなのかというところで、私はかなり経営が厳しいのではないかなと思うんですが、その辺についてのご見解はいかがでしょうか。","respondent":"金子保育課長","answer":"先ほど申し上げたとおり、きんだぁくらぶ以外にも若干の預かり保育をやっているというところはありますが、こういった預かり保育あるいはきんだぁくらぶというのは、園選択の非常に大きな要素になっているというふうには認識しています。","voiceIndex":102,"id":"exchange-038"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味で、協会へ３５０万円助成をされている。この中の、請願書の中により活発な活動が展開できますよということがありますが、具体的に何か今のままでは足りなくて、もっとこれをやりたいために助成をしてもらいたいということを言っているんだと思うんですが、何か具体的にお聞きになったことがあったらお聞かせください。","respondent":"金子保育課長","answer":"やっぱり子育て支援に向けて私立の幼稚園の関係の方々も何かしていきたいという意向はお聞きしております。ですので、具体的にどうこうということはまだお聞きしておりませんが、そういった方向性で物を考えていらっしゃるのかなというふうには想像しております。","voiceIndex":104,"id":"exchange-039"},{"speaker":"嶋委員","kind":"質問・要望","question":"私たちの時代は入園料がなくて、ほんとうにこれは署名運動した思い出がありますが、まだまだこういう不況が長引いているというのが一番の状況ですので、ぜひ区としてもできる限りの応援を、ぜひ支援をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-040"},{"speaker":"築舘委員","kind":"意見","question":"入園料の補助金のほうですね、増額の場合には所得制限はないということで、２３区中２番目だということだったんですけど、次の保護者補助金の所得制限の場合、これが現在４割ぐらいが補助に該当していない方がいるということなんですが、これは年額幾らぐらい以上の方がそうなっているのかというのが一つと、それから２３区では。","respondent":"金子保育課長","answer":"１点訂正しますが、先ほどから所得税と申し上げていましたが、住民税の所得割額のことでしたので、申しわけありませんが、訂正します。その意味で、現在私どもが補助していないのは、住民税の所得割額で１４万円を超える世帯の方です。","voiceIndex":107,"id":"exchange-041"},{"speaker":"築舘委員","kind":"質問","question":"そうすると、保護者補助金というのがないところも４区あって、一番最大限のところは３０万円が一番優遇されているということでいいんですかね。そうすると、２３区中、品川区の場合はどの程度のぐあいになっているのか。何番目とか、そういうのは出ているんですか。","respondent":"金子保育課長","answer":"補助のトータルの額の比較というのはしておりませんが、２３区全体で区負担の補助の平均が大体７,２１７円になりますので、先ほど申し上げたとおり、区の負担は７,０００円しておりますので、その意味ではほぼ平均の額だというふうには。","voiceIndex":109,"id":"exchange-042"},{"speaker":"築舘委員","kind":"質問","question":"そういう意味では、平均以上にはなっているということだとは思うんですけど、例えば管轄とは違うのかもしれませんけど、最近大田区なんかは区立幼稚園を将来的に廃止していくというようなこともちょっと出ていました。だから、その辺の意図を今後どの程度の計算で、計画でやっているのかがもし今の段階で、わからないということでしたら一般質問でもしたんだけども、それで結構なんですけど、教えてください。","respondent":"金子保育課長","answer":"今後どのように進めていくか、たしか委員ご指摘のとおり大田区はダイナミックな展開を公表しておりますが、私どもとしても、こういうような趣旨から何らかの全体的な改革といいますか、見直しというのが必要ではないかというふうに考えているところです。","voiceIndex":111,"id":"exchange-043"},{"speaker":"南副委員長","kind":"質問・要望","question":"私立幼稚園が今何園ぐらいあって、そこに何人ぐらいの子どもさんたちが就園されているのか、ちょっとその実数を、この請願書の中には書かれていないのでちょっとわからないから教えていただきたいと思います。","respondent":"金子保育課長","answer":"幼稚園の在園者は毎年統計が５月１日現在でとりますので、区内の幼稚園に通っている区民の方という数字ですと２,５５１人ですが、そのほかに区外のほうに通っている方もいらっしゃるので、あわせますと３,１１８人という数字になります。","voiceIndex":113,"id":"exchange-044"},{"speaker":"築舘委員","kind":"質問","question":"それで、ただ、具体的な請願事項になりますと、入園料の補助金に関しましても増額をということですが、今２３区中の２番目ということでもありますし、すぐにこれを全部それじゃあできるかということになると、予算上のいろいろな問題もあるでしょうから、そういう点を考えて趣旨として賛成ということに私ども自民党としてはそういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-045"},{"speaker":"本間委員","kind":"質問・要望","question":"今日結論を出していただいても結構だと思います。それに付随しての意見はいいですか。言いますか。これは３項目あります。したがいまして、今すぐに急いで増額ということはいかがなものかなという感じもしますが、もちろん請願者の皆さんのご要望にどこまで応えられるのかどうか、ほんとうはそういうふうな形であってよろしいのですが、そういうふうな部分で少し懸念する部分があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"意見","question":"そういったところで所得制限のところ、公私格差の是正、大分緩和はされていると思うんですが、いまだ４割の方のところが所得制限を設けられているというところでは、このところの不況の中で、かなり影響を、教育費の負担を感じていらっしゃる方もいらっしゃると思うんですね。結論としては趣旨採択ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-047"},{"speaker":"築舘委員","kind":"質問","question":"このじん肺の状況というのは、全国ではわかるんですけども、品川区はどういった状況があるのか、その企業とか、それから人数というのが出ているのかどうかというのが１点と、それから加害企業というふうに言っていますけども、この企業が要するに企業が悪いというふうになると、具体的にはどういうふうに、要するに粉じん、土、ほこり、金属片などを出さないように企業ができるものなのかどうか。","respondent":"田中健康課長","answer":"政府の援助等についてもありますが、どちらかといえば、これは対応策でございまして、じん肺を出さないように予防的な意味でのいろんな規定がありますけども、企業について命令的な意味でのところまではなかなか難しいような中身で入っているかと思います。","voiceIndex":126,"id":"exchange-048"},{"speaker":"築舘委員","kind":"質問・要望","question":"そうしますと、品川区の現状はよくわからないということですかね。それで、今３５年にじん肺法があって、それを今健康管理とか、そういう意味の予防の点での法としてはいいんだけれども、そこの法改正をするということは、じん肺を根絶するために法改正をするというんですけども、具体的にはどういったところの法改正をねらっているのかというのがもしわかれば教えていただきたい。","respondent":"田中健康課長","answer":"法律というのは、すべてじん肺法だけではなくて、労働安全衛生法ですとか、そういう形のいろいろなものが組み合わさっていろんな制度ができてありますので、私どもが推測しますに。","voiceIndex":128,"id":"exchange-049"},{"speaker":"築舘委員","kind":"質問","question":"そうするとまた、これはほかの２２区にも同じような請願が出ているというようなこともちょっと聞いたんですけど、その辺の現状、ほかの請願が出ているのかどうかというのがわかれば教えてください。","respondent":"田中健康課長","answer":"それで、私どものほうで把握している限りでは、ほぼほとんどの区が既に意見書を趣旨に沿って出しているようです。一番近い例で言いますと、昨年葛飾区のほうで出している例がございまして、品川区が出せばほぼ２３の区が区としては出揃うような形に一応把握をしています。","voiceIndex":130,"id":"exchange-050"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうから、先ほど四つの検診、就業時、または定期的、１年、３年とか、定期外、後から発症、離職時というご説明がございましたけど、これはどのような症状なのか、もしわかれば教えていただいて、離職時、後から出てくる発症というのがあった場合は、品川区の場合は窓口が「なし」ですが、こんな症状が出たらどこかに行きなさいとかという。","respondent":"田中健康課長","answer":"各都道府県の労働基準局に手続あるいは問い合わせをくださいという意味でのいろいろなホームページ等は私どものほうも参考にさせていただいてあります。","voiceIndex":132,"id":"exchange-051"},{"speaker":"嶋委員","kind":"質問","question":"個人レベルですので、この発症というか、出た場合に生活面に困ったとか困るとか、不安とか、将来に対する肺がんへの問題ということが一番この方たちの不安ではないかと思いますが、そういう意味で、それを労働基準局のほうに全部問い合わせをするということなのでしょうか。","respondent":"田中健康課長","answer":"もし、ございましたら、私どももいろいろホームページですとか、労働基準局のほうに問い合わせをし、そちらのほうにおつなぎするというのが現状というふうにお考えいただければと思います。","voiceIndex":134,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺、なかなかよくならないと私は聞いているんで、なってしまわないで、やっぱり予防を、ならないようにしていくのはどうしたらいいのかというのがすごく重要だと思うんですが、その辺がこの数字からすると予防の対策が不十分である、そういうふうに受けとめていいんでしょうか。","respondent":"寺西品川区保健所保健サービス課長","answer":"やっぱり、２０年、３０年の積み重ねによる病気であるということ。それから治療法はありません、基本的には。体に沈着してしまったものですから、対症療法として酸素を吸わせるとか、そういうことはもちろんありますけれど、最も確実なのはやはり予防になります。","voiceIndex":136,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"例えば区の施設やなんかで、例えばアスベストとかの除去やなんかで体験したり、対策したりとか、そういうのは今までの例ではないのでしょうか。","respondent":"田中健康課長","answer":"アスベスト対策等々、経理課の施設担当のほうのいわゆる工事の改修等でいろんな話は聞いたことがありますが、基本的に区の関係職場でそこまでの対策、それから被害ということは耳にしておりません。","voiceIndex":138,"id":"exchange-054"},{"speaker":"南副委員長","kind":"確認","question":"そういうときに、その工事のために、例えば解体だとか、そういうものをしなきゃいけない工事の場合に、健康課あるいはこの健康問題を担当するセクションとして、こういう例えばじん肺だとか、そういうものを出さないために、きちんとこういうところに気をつけなさいみたいな契約上の仕様にそういう内容も盛り込むような指導というのはしてられるんだろうと思うんですけど。","respondent":"田中健康課長","answer":"すべての工事とか、すべてそういうものを発生するかどうかというのは難しい問題ですし、個別に何か相談をいただければ、内部的にあれば、私どももいろんな調査物でこういう影響とかというのはもちろん話し合いますけども。","voiceIndex":145,"id":"exchange-055"},{"speaker":"南副委員長","kind":"質問","question":"そうすると、民間の業者の側の仕事をするに当たって下請けなり、そういう業者にお願い、あるいは職人さんにお願いするときにきちんとしたそういう手当をしないで、あるいはしても安く請け負うために不十分になりがちなところってあり得るんじゃないかなとちょっと気になったので、ちょっと質問したんですけど、やっぱりこれからそういうことも予防するという意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-056"},{"speaker":"築舘委員","kind":"意見","question":"結論を出すということで、ほかの２２区ならびに都のほうも同じような形での意見書を出しているということもありますし、国連の機関ではＩＬＯならびにＷＨＯが２０１５年に向けてじん肺根絶目標年を定めているというようなこともありますので、そういった形で品川区も具体的に被害に遭っている方もいるかと思いますけども、採択をして意見書を出すということでいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":149,"id":"exchange-057"},{"speaker":"本間委員","kind":"質問","question":"難しいというか、非常に自分たちの身の回りでどうだというようなうわさとか、そういう想像では多少わかることはあるんですが、現実になかなかという部分はなくもないんですけども、いろいろお話をお聞きしまして、やはり国際的な課題である目標年が２０１５年というような形も出ていましたし、こういうふうな問題意識を持って、国際動向を見ながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この意見書案の中にも、「じん肺は最大の職業病である」と書いてありますけれども、今ご説明いただいたところ、ほんとうに一度かかったら治らないという、予防を講ずれば、今ほんとうにいろいろ技術も進歩しているというところでは、安全対策、予防対策をほんとうに十分していけば、ほんとうにこの数を減らしてなくしていけると思うので、ぜひ品川の議会からも意見書を採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":54288,"voices":157}},{"id":"h16-20040927-8","meetingId":"h16-cm09","date":"2004年9月27日","dateIso":"2004-09-27","committee":"建設委員会","time":"午前１０時０３分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６７号議案、品川区手数料条例の一部を改正する条例","agenda":"第６７号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"高星委員","kind":"意見","question":"１番、２番、３番、それぞれで専門用語で書かれていて、主として自己の居住の用に供する目的とありますね。じっくり考えればわかるような気がするんだけれども、それぞれ１番、２番、３番というのは、具体的にもっと私たちのわかりやすい日常用語で説明してもらいたいんですけれども。","respondent":"浜脇住環境整備課長","answer":"この開発許可というのは、５００m2以上で建物を建築する際に、土地の区画、形質、がけおよび道路とかそういったものが変更した場合、申請する場合の手数料がかかってございまして、規模については、大体がこれは小さいといいますか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"高星委員","kind":"質問","question":"だから、１番の説明をいただいたときに、用途の若干の変更というのはミニ開発だよという言い方なんですかね。例えば僕らがわからないのは、個人の家なんかつくるときに２階建ては入らないのか、そういった細かい日常的な私たちの活動の中で生きている中で、わかりやすい言葉でやって、ミニ開発とはどれがミニ開発なのとなっちゃう。その辺のところをもっとわかりやすく教えてもらいたいんですが。","respondent":"浜脇住環境整備課長","answer":"私ども、５００m2以上の土地に、５区画以上、そういった場合には、開発許可というのをとって、道路づけ等の審査を行って、前にもありましたけれども、開発指導要綱に基づきまして、５０m2とか６０m2区画を守っていただくと、そういったようなご指導といいますか。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高星委員","kind":"確認","question":"それはわかります。ちなみにそういうことになってきますと、今の建築確認申請が東京都で十幾つですか、民間業者にやられているケースもかなり多いというふうに思いますけれども、ごく将来的には、こういった開発行為についても、そうしたところに委ねられていくという、その辺がどうなのか。その辺はちょっとどうなるかわからないけれども、その辺の民間の確認申請団体との、これから先どう関連していくのか。","respondent":"片田建築課長","answer":"いずれにしても、法律が改定されたときに、役割分担ということで、通常の確認とかこれについては実施者になりますので、民間機関でもできるというふうな役割分担を、平成１１年度の改正の時になってきたと。","voiceIndex":11,"id":"exchange-003"},{"speaker":"高星委員","kind":"質問","question":"いろいろな法の中では、例えば昔から言われている人民は弱し官吏は強しという、役所というのはそういう意味で許認可については強いと昔から言われているわけです。そのことに一切言うつもりはないんですが、最後に一点質問して、なぜこの時期に、五割もの上げ幅のものをつくらなければならなかったのか、このことだけ聞いて私の質問を終わります。","respondent":"浜脇住環境整備課長","answer":"中にはまだやられてない、改定を予定していた人たちで、区も当然あわせてやるべきということで、１６年度中まで検討していった結果、きょう提案するといいますか、ご審議をお願いしたものです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"三上委員","kind":"質問","question":"そうすると、２３区以外の市町村のこういう金額的な部分というのはどうなっているのか。1)と2)の金額に比べると、ドーンと大きな金額になっているんだけれども、あまりにも幅があり過ぎている感じがすると同時に、逆に広さによってはもっと２段階、３段階的な部分の、広さによってのそういう金額の設定というのはあってもいいんじゃないかという感じがするんだけれども、どうなんでしょうか。","respondent":"浜脇住環境整備課長、中谷まちづくり事業部長","answer":"大体改定の見直し自身の発信というのが、東京都のほうで財源問題なんかも絡めて、改めて受益者負担に対して検討したということで、その検討してある意味では都がやって、２３区や都下がやらないというのは。本手数料条例につきましては、人件費等に基づきます事務手数料により算出されたもので、職員１人当たりの人件費に、それに要した時間それを掛けまして、そのほかの事務手数料、印刷製本費とかその他の旅費ですとか、消耗品費。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一番初めのところの、先ほども質問があったんですけれども、1)、2)、3)の1)の住居用に供するというふうなところでは、ミニ開発で５戸とか６戸とかできるというふうな、何とかマンションだとかというところでわかるんですけど、業務用に供するというのとその他の目的というのは、具体的にどういう中身なのかを教えていただけませんか。","respondent":"浜脇住環境整備課長","answer":"3)につきましては、土地だけやった場合とか、売れない場合、売れないというのはどうかと思うんですが、とりあえず開発をすぐというような場合にはこれに入ると思うんですけれども、要するに目的がなくてやるような場合も3)に入ってくると思うんですけれども。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"2)の業務用というのがマンションになるんですか。マンションというふうに考えていいんですか。","respondent":"浜脇住環境整備課長","answer":"会社等の事務所です。","voiceIndex":22,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"3)は、ちょっと例もないというふうなところで、具体的にはよくわからないんですけれども。もう一つ、区の収入が１.４倍になるということですけれども、具体的に幾らぐらいになるのかということを教えていただきたいと思います。","respondent":"浜脇住環境整備課長","answer":"これ、平成１４年、１５年しかちょっと調べてきていないんですけれども、１４年で、合計６２件ございまして、開発許可が６件ですか、変更が３件、開発登録簿の写しの交付が５２件、地区の承継が１件あったんですが、これで６２件で６４万余が９５万余になります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"ちょっと戻っちゃうんですけど、都のほうで今回値上げをしたということで、４月１日からという値上げをやって、今度、２３区のほうも協力して値上げをしてくれと。その辺、今、人件費等々取り込む話なんですけど、その辺、今後対応を何か考えていただければありがたいなと思います。","respondent":"浜脇住環境整備課長","answer":"私も、先ほどの委員にもお話ししましたけれども、そういう情報が入って、できるだけ速やかにやったつもりですけれども、今回１１月にということでなって、９月の議会にはというのはありますけれども、そういった意味では、整備に一生懸命やっておりますけれども。","voiceIndex":26,"id":"exchange-009"}]},{"id":"topic-02","title":"の専決処分の報告について。報告第２４号","agenda":"の専決処分の報告について。報告第２４号","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"毎年このような事故、損害賠償、また慰謝料等々の報告が来るんですけど、やはり行政、区のほうは、自賠責保険のみなんですよね。いろいろ役所関係の庁有車、事故を起こすと自賠責しかおりない。逆に事故を起こされたほうは、本当に少ない金額でのまなきゃいけない。和解しなきゃいけない。何かその辺ちょっとお聞きしたいと思います。","respondent":"松代道路公園課長","answer":"私も、特別区自治体総合賠償責任保険、これは特別区協議会のほうで入っている保険ですが、これも１３年の４月から任意保険の手続を行ってあります。","voiceIndex":34,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"今度新しい団体保険も入らなきゃということで、事故が起きた場合に、被害者の方にできるだけのことをできるようになればさらにいいと思いますので、今後とも、今回また再三、いろいろ向こうが条件を撤回したということは、ちょっと向こうにも問題はあるのかなと思いますけれども、被害者の方にできるだけご配慮していただけるように、行政のほうとしてもよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-011"},{"speaker":"高星委員","kind":"質問","question":"こういうケースもまれにしかないということだというふうに思うんですが、こういうふうに車両も含めてだけど、事故とか何か起きたときに、事業部の対応する制度と窓口みたいなのがあって、そういうのはどういう仕組みになっているのか、あるいは庁有車の運転手が出て行ってやるのか、あるいは先ほど言った保険の関係のほうの方にも全部任せちゃうのか、その辺のつくり方、特にうちの事業部というのは。","respondent":"松代道路公園課長","answer":"その際、当然いろいろとこういったことも想定されますので、法律の専門の文書係、そことも十分相談をしながら、この保険会社等にこの状況等を協議し、示談等に当たっているものです。","voiceIndex":37,"id":"exchange-012"},{"speaker":"高星委員","kind":"意見","question":"職員に対するいろいろな締めつけがきつくなってきているという、言葉は悪いけど、そういう中で、ややもすれば運転されていた方が萎縮されちゃって、こういう事故の関係なんか特にそうなんだけれども、ごめんなさいから入ってしまうとなっちゃうと、向こうが今度出てきちゃうというような、事故というのは、事故という言い方はあれだけど、これはもめちゃうというのは、往々にして相手に対する配慮が。","respondent":"松代道路公園課長","answer":"速やかに報告をする。その後、先ほど申しましたように、文書係、もしくは保険会社とその事故の今後の対応について、被害者等にきちんと示すべく、こちら側の誠意のある対応を進めております。そういったことで今やってあります。","voiceIndex":39,"id":"exchange-013"}]},{"id":"topic-03","title":"次、報告事項でございますが、(2)の大崎駅西口地区の道路拡幅整備工事に伴う区営自転車等駐車場の仮移転","agenda":"次、報告事項でございますが、(2)の大崎駅西口地区の道路拡幅整備工事に伴う区営自転車等駐車場の仮移転","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これは、駅から距離的には両方とも、どれぐらい離れているのかということと、敷地をお借りするということは、やっぱり賃貸料を払うようなそういう状況なんでしょうか。","respondent":"山口交通安全担当課長","answer":"敷地の関係については、この明電舎との協議のほうで、責任を持って整地等する予定ですので、区のほうは費用は全くかからない予定です。賃貸料のほうは今のところはございません。","voiceIndex":46,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"これは、今まで道路上を使っていたところですよね。そうすると、これは移動するという条件は、この道路そのものが使えなくなるとか、工事車両が頻繁に出入りするとかという、そういう条件が新たに出てきているから移転するということなんでしょうか。全くそういうことはなくて、今の状況は変わらないけれども、ただ、空間ができたのでそちらのほうに移動するという、そこはどうなんでしょうか。","respondent":"上野都市開発課長","answer":"明電舎Ｅの東地区につきましては、来年１月から着工する予定ですけれども、最終的には平成１９年の７月に竣工する予定ですけれども、その竣工にあわせてＥ東地区周辺の道路を１２ｍで整備する予定ですので、そうしますと、これから工事期間に入りまして、その中に、今。","voiceIndex":49,"id":"exchange-015"},{"speaker":"高星委員","kind":"質問","question":"この場所、どこから入っていっていいのか、いわゆる明電舎の土地、昔からの経緯というのがあって、でも、どこからどう入っていいのかわからない。その辺のところ、あの辺はブロック塀はなくなっちゃったんですね。ただ、がけ下の間のその辺のところの状況だと、ちょっと斜めの状況をどういうふうに整備していったらいいかということを、ちょっとお聞きしたいなと考えています。","respondent":"上野都市開発課長","answer":"委員ご指摘のとおり、ここは坂で降りてくるところですけれども、特にＥの東地区の西側が若干がけ地になってございまして、既存のマンションとの取り合い等ございまして、その辺の工事の調整が一番今後、工事面ではかなり難航が予想されているところですので、その辺の工事の中で。","voiceIndex":51,"id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"こっちのがけをね、なぜあそこのがけに手をつけられなかったかというと、工事そのものが大規模になっちゃうんです、あの明電舎の。あそこを反対にどうすればいいんですかと言われたらどうしようもなくなっちゃう。少し丁寧に自転車の出し入れに際しても、できるだけ迷惑をかけずに、利用者に便利がいいようにやってもらいたいと思います。","respondent":"山口交通安全担当課長","answer":"仮移転後の交通安全対策につきましては、利用者について看板等を設置して、交通安全に万全を尽くしたいと思います。交通管理者、警察署等とも協議しまして、交通規制等必要ならばまたその都度万全を図っていきたいと思いますので、よろしくお願いいたします。","voiceIndex":53,"id":"exchange-017"}]},{"id":"topic-04","title":"のＪＲ大崎短絡線の計画","agenda":"のＪＲ大崎短絡線の計画","exchanges":[{"speaker":"三上委員","kind":"意見","question":"私、これだけ見ただけでも、これは難しいなと。３年間でこの計画で進めようなんて、バブルの時代みたいに、札束をドーンと積んで目の前に出してやるとかというようなことだったら、それで話に乗る人がいるかもわかりませんけれども、今までみたいにそうじゃないと思いますので、これだけのことで説明会をやろうと思ったら、ちょっと難しいような気がするんですけど。","respondent":"藤田都市計画課長","answer":"先ほどの私の説明の中で、３年半で一応工事しようですけれども、一応地元との調整、あるいは詳細の設計を終えた後、工事の期間として３年半ぐらいかかるですので、まず、地元説明、あるいは詳細の設計を進めるといったのを進めた後のことですので。","voiceIndex":61,"id":"exchange-018"},{"speaker":"三上委員","kind":"質問","question":"特にこじれるのは、町会長は話を聞いているけれども、その町会長がほかの自分の町会の役員だけに話をした、それだけでとまってしまって、その計画が起きたときに、なぜ我々に教えてくれなかったんだというのが、あとからの説明会で紛糾するもとになるのはそういう部分があるわけですね。できるところもできなくなってしまう原因というのはそこのところにあるわけですね。","respondent":"藤田都市計画課長","answer":"現在、地域センターの町会長会議、全体の町会長が集まる会議ですけれども、ここでの説明と、あと直接関係が出てくる３つの町会、大崎一二三町会、西品川二丁目町会、大崎三五町会、この３町会につきましては、町会長を集めてということではなく別に。","voiceIndex":63,"id":"exchange-019"},{"speaker":"三上委員","kind":"意見","question":"その間をあけないでやってもらいたい。それをあけちゃったりするから、またこじれるもとになるのであって、スケジュールについてもしっかりと、どのぐらい短い間隔でやるかということも考えた上で、しっかりお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一番初めのときに、標記について、地元説明に使用した資料ですということを言われているんですけれども、この地元説明というのはどういう説明だったのかということをひとつ教えていただきたいのと、それから、本体工事はおおむね３年半程度を予定していますということなんですけれども、本体工事までの期間をどれぐらいから始めるという、そういうふうな計画というのが、もう既に計画されているのかどうか。","respondent":"藤田都市計画課長","answer":"本体工事に入る前の期間ですけれども、当然、地元の皆様方の合意が前提ですので、そういった中できちんと調査、地元との調整、設計等を行うものですので、逆にその期間がどれだけということではなくて。","voiceIndex":66,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地権者に対して説明したという今のご説明でしたけれども、いつぐらいにどれぐらいの方が対象でされて、その中ではどんな意見が出されていたのかということも含めてちょっと教えていただきたいと思います。","respondent":"上野都市開発課長","answer":"今まで理事会等でもって、ＪＲの説明に対して幾つかご意見が出てありますけれども、基本的に大きく直接土地の区域に入ってきますから、大きな影響として、再開発事業そのものに対しての支障になるですので、それをどういった形でクリアできるのかといったようなことを。","voiceIndex":68,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"土地買収が必要になってくるということで、そういうところにも説明をされてきているということなんですけれども、その土地買収をする対象というのは何件ぐらい、どれぐらいになっているのか、そこら辺をちょっとお聞かせいただきたい。","respondent":"上野都市開発課長","answer":"百反通りの南側の区域につきましては、これは大きな地権者の方がおられまして、あるいはご兄弟で共有されているものとかが幾つかありますけれども、大体大きな地権者の方で買収予定地域にかかってくるですので、そこにつきましては、ＪＲのほうからも個別にご説明をして。","voiceIndex":70,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何となくよく内容がわかってこないんですけど、まだわかっていないという部分もあるのかもしれないんですけれども、ちょっとそこら辺のところは改めて、わかり次第またご報告をぜひいただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-024"},{"speaker":"高星委員","kind":"質問","question":"この３ページの地図で、新しい大崎短絡線というこの地図から見ると、国際自動車の後ろのほう、高い位置から２階があって、大崎の２階部分で入ってくるという発想ですね、これね。この線が新しくできますよ。そういうふうにしっかりとした考え方、ＪＲのそういった見方も含めて将来的にどうなんですかと。どう考えたって、あの２階建てのところが、大崎駅で工事をやって２階建てを持ってくるわけでしょう。","respondent":"藤田都市計画課長","answer":"１点、これも私の説明がうまくできてなかったんですけれども、現在の横須賀線がちょっと盛土の高架になってありますけれども、そこから高架の線が延びて、今、ＪＲのほうから聞いている話といたしましては、大崎の駅では、今の駅のホーム、あれを使っていくということで。","voiceIndex":73,"id":"exchange-025"},{"speaker":"高星委員","kind":"質問","question":"今回この提示しかありませんからという話じゃなくて、全部ＪＲのことだからＪＲに任せようという発想に立っているからそういうふうになっちゃうんであって、将来的に品川区のあのビルが、ＪＲのあの辺をカットしちゃって、将来的に品川区で共生できるような形で開発行為ができれば、これはすばらしいことになるんじゃないかというふうに思うんだけど、そういう発想に立たないんですかね。","respondent":"中谷まちづくり事業部長","answer":"あるいは考えていただかなくちゃいけない問題がＪＲに対してあると思いますから、こういう問題について誠意を持って区として対応すべきだと、こういうことで今、ＪＲには申し入れて、そして説明会などについても、先ほど三上委員からもご指摘がございましたが、怠らないように。","voiceIndex":75,"id":"exchange-026"},{"speaker":"高星委員","kind":"意見","question":"例えばこれが５０年、６０年たってきて、何でこんなことやったのよと、何であのときこうしなかったのよというようなことが出てくるような気がしてならないんです。そういうことを残さない考え方というのが必要なんじゃないかなと思ったものだから、ついつい言いました。どうもすみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3796#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":24504,"voices":82}},{"id":"h16-20040927-9","meetingId":"h16-cm09","date":"2004年9月27日","dateIso":"2004-09-27","committee":"文教委員会","time":"午前１０時０４分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第６８号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"の第６８号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"先ほどの説明で、東京都から区へというお話がありました。今まで、東京都がやっていて、区になったその理由というのがあるんですか。単なる命令で、ここしろ、ああしろという感じでしてきたのか、その辺のいきさつを、少し説明してください。","respondent":"谷田部学務課長","answer":"そのところで、従前は、先ほど申し上げました都道府県で、公立学校医等の公務災害補償を定めるということになってございましたけれども、その法律改正に伴いまして、条例が当該の設置者である区市町村の事務ということで、各区が、それぞれの公務災害補償を定めるということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、例えば、これを区のほうで所管するというか、そうなってきたら、補償だから、のべつまくなしということじゃないんでしょうけれども、実際にこれが適用された場合に、区として持ち出しになる部分があるのか、その辺のお金の流れといったら変な言い方だけれども、その辺、ちょっと聞かせてくれますか。","respondent":"谷田部学務課長","answer":"各区市町村のほうにこの事務が移管されるということになった段階では、特別交付税の措置の予定だということで、特別交付税の中で措置するということになってあります。議員については、特別交付税の対象外ですので、都区財調の中で見てもらえるものという部分で。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"おおよその流れがわかったところで、教育長にお聞きしますけれども、こうやって、都から区へ教育関係の人に関するいろいろなものが移管されてきた。これは、いわゆる我々が言っている東京都から人事権を区へというような流れの一環として考えていいんですかね。","respondent":"若月教育長","answer":"学校医というのは、そういった意味では、常勤の教職員とは、身分上若干違うわけでありますけれども、大きな流れの中では、それぞれの基礎的な自治体と言われる自治体が、それこそ適切な財源保証といったようなものを前提にして。","voiceIndex":11,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"期待をしながら、一つのステップまで行くのかどうかわかりませんけれども、そういうふうに、我々は期待したいと思います。その後、きちっと開業されているお医者さんにお願いしなさい、あるいは開業している薬剤師にお願いしなさいという話をしてきたんですけれども、現在はどういう状況になっているのか。ちょっとこの補償からは外れるんだけれども、品川区の学校医関係の話を聞かせてほしいんです。","respondent":"谷田部学務課長","answer":"私どもはやっぱり、学校の児童生徒たちの教育関係をあわせてやっているということと、それから、健康診断で、治療しなきゃならないようなものが生じた場合には、やはり最初に見ていただいた学校医の先生方のところで治療を受けるというのが基本だと思ってありますので。","voiceIndex":13,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"最後ですけれども、思っていますじゃ困るんで、実態の把握は教育委員会の責任なんですよ、医師会の責任じゃないわけで。思っているだけじゃ困るんで、教育委員会として、こういうふうにしていますというきちっとした答えをください。","respondent":"谷田部学務課長","answer":"失礼いたしました。適切に行われているところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"聞き逃したり、間違えて聞いていたら申しわけないので、ちょっと確認で教えていただきたいんですが、人事院というか、国家公務員の給与が下がったことが政令で定められて、それが補償基礎額に影響して、都も区も横並びしていったというふうにとらえていいかどうかということ。","respondent":"谷田部学務課長","answer":"先ほど、法律の主旨を、ちょっと説明させていただきましたけれども、法律では、国のほうにおいては、常勤の国家公務員である医師だとか、歯科医師ですとか、薬剤師と同等の公務災害補償になるようにということが法律の主旨になってありますので、各自治体も、それを条例のほうで。","voiceIndex":17,"id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"今のは、わかりました。実際の運用で、ほとんど事故がないから必要ないのかなと思うんですけれども、例えば、裏担保するということで、保険に加入をするというのは。先ほどの地方交付税、あるいは都区財調で担保されるというのは全額ですよね、だからそういうのには必要ないのかどうなのか、ちょっとそこのところだけ。","respondent":"谷田部学務課長","answer":"先ほど、申し上げましたが、東京都全体で、平成２年を最後に、こういう事故が発生していない。各区市町村ごとに考えれば、さらに発生率等が非常に低いかと思ってあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"学校医だとか、薬剤師は限られているから、そんなに事故もないと思うんですけれども、一般の公務員は、保険は入っているんですよね。そこだけちょっと教えてもらえますか。","respondent":"谷田部学務課長","answer":"各区市町村は、分担金という形で払っております。その年に発生した分は、集めた分担金で賄いますが、余った場合については、基金に積み立てをして、将来の事件に対する備えとしてやっているということは、私ども聞いてあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけなんですけれども、それぞれの医師会や歯科医師会から、公務災害補償に対してご意見とか、要望で何か寄せられているものがあれば、二、三紹介していただければと思います。","respondent":"谷田部学務課長","answer":"この件に関しては、何も話は来ておりません。","voiceIndex":24,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"基礎的なことだと思うんですが、教えていただきたいんですが、公務災害というと、具体的にどういう範囲のことなのか。それから、それに関連して、そもそもの枠なんですが、交通事故とか、そういうことも入っているのか。どこまでのことをあらわしているのか。","respondent":"谷田部学務課長","answer":"公務上ということで言うなら、公務災害補償を適用するか、しないかという判断をするです。ですから、先ほど、私が二つ例を申し上げましたけれども、大体それが公務災害として適用されるという状況です。","voiceIndex":26,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"先ほど、平成２年から例がないというお話だったんですけれども、品川区においても、こういう公務災害という形で起きたというのは、最近ないということなんでしょうか。","respondent":"谷田部学務課長","answer":"私が申し上げたのは、東京都が行った事務が平成１３年度までですから、東京都がつかんでいるのは、平成２年を最後にないということ。それから、平成１４年度に区の事務として移管されて以降、１件も発生していないです。","voiceIndex":28,"id":"exchange-011"}]},{"id":"topic-02","title":"の第６４号議案、平成１６年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"の第６４号議案、平成１６年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"この財源なんですけれども、今、ご説明されたご寄附をというんですけれども、平成１５年度に、寄附をされている方１人、８００万円ありますよね、この補正では。これを充てるということですか。これとはまた違う方が、直接的に障害者のために使ってほしいという形で寄附をされたものなんでしょうか。その辺の財源をちょっと。","respondent":"古里品川図書館長","answer":"ただし、平成１６年度予算案の編成には、その使い方について、ご遺族の方とお話をしなければならないということもございまして、新年度予算の最初の編成の中には反映することができませんでしたので、今回、平成１６年度の歳出の補正をするという内容です。","voiceIndex":36,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば、この補正に出てきた８００万円は、ネーミングが何々と、お名前がついた基金になるわけですけれども、こういうふうに物に変わっちゃうと、例えばどこかに、何々様よりご寄贈とか、よくあるじゃないですか、そういうことは考えていらっしゃらないのか。寄附された方が望まれてはいないと思うんですけれども、売名行為としてではなくて、ほんとうにご気持ちだろうから。","respondent":"古里品川図書館長","answer":"ただ、備品を購入する部分もありますので、林（宏）委員のご発案については、遺族の方と相談をさせていただいて、もしそのようなことを望まれるのでございましたら、プレートを備品につける等は、検討させていただきたいと思います。","voiceIndex":38,"id":"exchange-013"}]},{"id":"topic-03","title":"平成１６年請願第２２号 学校事務職員・栄養職員を含む教職員の給与費半額国庫負担などの「義務教育国庫負担制度の堅持」を求める請願","agenda":"平成１６年請願第２２号 学校事務職員・栄養職員を含む教職員の給与費半額国庫負担などの「義務教育国庫負担制度の堅持」を求める請願","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"主旨のほうの７行目、文部科学省から第７次公立義務教育諸学校教職員改善計画で出されているんだけれども、ここの内容について、ここには「『学校運営の円滑化』のための事務職員、栄養職員の定数改善が盛り込まれています」と書かれているんだけれども、ちょっとそのあたり、この改善計画の中でどういうことをうたっているのか、わかりますか。","respondent":"市川庶務課長","answer":"具体的にその中では、少人数指導や習熟度別指導を行うなど、きめ細かな指導を行う抜本の取り組みに対する支援ということ。それから、円滑な学校運営のための教頭複数配置の拡充。最後の３番目といたしまして、養護教諭、学校栄養職員、事務職員の定数の改善。","voiceIndex":48,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"意見","question":"文部科学省では、そういうことを出している一方、総務省の場合は、国と地方の関係ということなんでしょうけれども、お金のことは財務省で、２００１年に出て、かれこれ２、３年、あるいは、今の計画で言うと来年まで、経緯的にはそういうことになるんですけれども、この計画がどのぐらい、財務省、あるいは総務省あたりで認められてきているのか、実態としての流れがわかりますか。","respondent":"市川庶務課長","answer":"今回の請願の説明をするので、私も随分、幾つか当たってみたんですが、今、委員のご指摘になったように、国と都とのいろいろなやり取りの結果が、実際に、私があまり無責任をことを言うわけにいかないんですが、区市町村におりてくるときに。","voiceIndex":50,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"前は、いわゆる来年度の予算要望に向けて、こういうことを訴えてきたというところがあるんだけれども、三位一体改革で、まさに交付金問題なんかが変わろうとしている中だから、こういう請願を出してくるんだという意図なのか、その辺を聞いていらっしゃったら、わかったらで結構ですから、もし請願者の意図をつかんでいらっしゃったら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-016"},{"speaker":"沢田委員","kind":"意見","question":"私、直接会ってないんでわからないが、いつも、予算要求として。今回は、密接に絡むんだけれども、教職員の半額負担を切っていこうとする、だから、ちょっとレベルが違うんじゃないかなと、私の思いですけれども。いつもやっている予算要求とはまたちょっと。予算要求は、また別に出てくるんじゃないか。〔「ああ、そうなの」と呼ぶ者あり〕それは、わからないですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"一般質問でもお聞きしたんですけれども、区として、まさに今、三位一体の改革の中で、教育関係のいろいろなものが一般財源化されてくる。ちょっと教育長は担当、それでも教育全体の財政に関しての責任を持つ部署におられると思うんですけれども、私見でも結構ですけれども、その辺の流れ、直接勉強された庶務課長の意見でもいいんだけれども。","respondent":"市川庶務課長","answer":"ですから、これから税源移譲、財源確保ということで、しかるべき協議の場で検討されていくと思いますけれども、今申し上げたように、私たちはやはり東京都の特別区、あるいはその一部という形で、品川区の立場としてどうなのかということは、いわば今。","voiceIndex":54,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"ちょっとどのぐらいの影響額かということを知りたいんですが、２分の１国庫補助の部分として、品川区では大体どのぐらいになるのかということ。財調はどんどん細っていって、だめだったらアウトになっちゃう。空中戦だということで、わからないのかもしれないけれども、例えば、東京都はどうしようとしているのかというのは、全くわからないんですか。","respondent":"市川庶務課長","answer":"ですから、具体的な数字は持ち合わせてございません。それから、２番目のご質問は、先ほど、林（宏）委員のご質問に対して答弁申し上げたような事情で、今の時点では、もうこれ以上のことは申し上げる材料を持っていないというのが、一番正しい表現かなと思います。","voiceIndex":56,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"それで、２分の１が東京都の補助ということですから、概算はわかるんじゃないかなと思うんですが、それが一つ。東京都の場合で言うと、これは間違いなく影響が出てくる。ちょっとそれとの関係で、品川区の現教職員の国庫補助関係と、それが一般財源化されると、丸々東京都は来ないわけですから、何かそのほかの手当てが提起されているのかなと思うんですが、いかがでしょうか。","respondent":"古川教育次長","answer":"ただ、そのことが将来とも変わらないかという問題については、なかなかそういうわけにはいかない部分があるのかなということで、この問題の根の深さというんでしょうか、全体をとらえるのは非常に難しいと、このように考えています。","voiceIndex":58,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"全国の市議会議長会では、この問題は大変な問題だと。だから、各市議会、区議会でしかるべき税源がきちんとバランス取れて移譲されるように意見書を上げてくれと、照会が来ているわけです。それで、ちょっと聞きたいんですが、区長会あたりでは、これで動きが何かあるんでしょうか。都道府県に影響することですけれども、何かあるんじゃないかと思うんですが、つかんでいたら教えてほしいんですけれども。","respondent":"市川庶務課長","answer":"今の時点では、特段、動きはございません。","voiceIndex":60,"id":"exchange-021"},{"speaker":"藤田委員","kind":"質問","question":"これはやっぱり義務教育ですから、安定的に、優秀な教職員を確保するにはどうすべきなのか。その辺が大きな問題になっていると思うんです。今、説明の中で、非常に情報も不足をしているということもあるようで、まさにそのとおりだと思うんです。現状で構わないんですけれども、もう一度、先ほどの文部科学省の立場、それから財務省の立場の説明をお願いできませんでしょうか。今現在で結構です。","respondent":"市川庶務課長","answer":"「教育については、義務教育に関する地方の自由度を拡大し、地方公共団体や地域住民の知恵や工夫が一層生かされるような仕組みとするため、これまでの改革に加え、現行法の見直しを含めた検討を進めるなど、義務教育国庫負担制度の改革を推進する」と。","voiceIndex":62,"id":"exchange-022"},{"speaker":"藤田委員","kind":"質問","question":"一方はお金の問題、一方は義務教育ということですね。請願内容の２項目なんですが、これはもう既に一般財源化をされている中で、復元してほしいというのは、今現在の予算の関係から見ても、これはちょっと厳しいのかなと思うんですが、この辺はいかがなんでしょうか。","respondent":"市川庶務課長","answer":"それがいわゆる行財政改革と言われていますけれども、その中で、各方面、特に国と教育現場がいろいろな協議、検討の場を経て、いわばクギにクギを重ねた上での苦渋の選択として行われたものだとは思いますが、ただ、この間の社会経済情勢を受けた財政の事情、そういったものは。","voiceIndex":64,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"区の基本的な姿勢というか、立場を少し伺いたいと思うんですけれども、全国紙以外は、かなり激論になって、テレビなんかでもインタビューしているんですけれども、公立中学校の８,５００億円を削減する、２００９年度に小学校部門という話も出ていますけれども、こういった動きに対する、現時点での区の姿勢ですが、今、どういう立場に立っているのか、お聞きしたいと思います。","respondent":"市川庶務課長","answer":"基本的な、この時点での考え方、あるいは区の姿勢としては、これまで折に触れて申し上げてきてありますけれども、やっぱり現在の義務教育に国庫負担制度の根幹を成しています教育の機会均等、それから、教育水準の確保。","voiceIndex":66,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな意味合いがあるのかなと思うんですが、学校事務職員、栄養職員と、教職員の給与の考え方、そこら辺がどういうふうな考え方をされているのか。それを踏まえて、請願内容の１があるのかなという、ちょっと曲がった考え方かもしれないんですが、そういうふうに受けとめられないこともないので、そういう考え方は誤解でしょうか。","respondent":"市川庶務課長","answer":"このことは、２番目のご質問に関係するわけですけれども、今現在、私どもが承知している限りでは、文部科学省の考え方といたしましては、学校事務職員と学校栄養職員については、いずれも学校運営にとって欠くことのできない必要な基幹職員で、事務職員については。","voiceIndex":68,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"政府、文部科学省、財務省、総務省と、国に対しての意見書ということであるんですが、従来、品川区として出すというのは、都があって、国があって、国と都の間のことで、今、進んでいるという状況ではあるんですが、品川区としてのアプローチの仕方というのは、今の状況では難しいなという判断ができるんですが、むしろ品川区としての見解が求められるんであれば。","respondent":"市川庶務課長","answer":"この請願で取り扱われてあります義務教育費国庫負担制度は、国の法律と、それから国の予算に基づいて運営されているものです。その意味では、私ども品川区、あるいは品川区議会が直接そこに何らかの役割を果たすということは、制度的にできない。","voiceIndex":70,"id":"exchange-026"},{"speaker":"沢田委員","kind":"意見","question":"それからもう一つ根本の問題で、学校教職員給与費の２分の１を、さしたる税源移譲の保証がないままにやる問題と、二つの問題があるんです。少なくとも、来年度の予算に絡む問題については、今やらないと、１０月中旬に結論を出すという方向で、先ほども報告があったけれども、動いているから、私は、きょう採択をすべきだと思います。それが一つ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"さっき、沢田委員にお聞きして、いろいろな問題を含んでいるから即決が必要だという部分と、もうちょっと財源移譲、税源移譲、税の三位一体改革のいわゆる税のどういうところが、我々にとっては必要であり、求めていくのかというのが、根本的にあるわけですよ。もうちょっと見てというか、国と都道府県のやり取りを注視したいという気もしているんですよ。２項目一遍にやるというと、どうしても無理になる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-028"},{"speaker":"藤田委員","kind":"質問・要望","question":"私ども、請願内容の２項目については、今、答弁もあって、現段階では非常に難しいと考えます。それから１番目について、まさに先ほども話しましたように、党としても、この問題については、大変議論もされていますので、私たちもその中に意見を言っておりますので、現段階では、もう少し国の動きを注目していきたいと思っていますので、きょうのところは、継続にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-029"},{"speaker":"大西委員","kind":"意見","question":"政党に属されている方と、属していない方も含めまして、１項目については、ある一定のコンセプトが得られているんですけれども、２項目について、私どもでも、これをこのまま生かせるのは、少し問題があるのではないかという考え方を持っております。今、自民党、公明党会派の皆さんがおっしゃったように、もう少し国の姿勢がより一層鮮明になるまで、少し待ちたいというのが、私どもの会派の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"１項目目と２項目目と、主旨が随分違うと思うんです。これは、議事の進行の方向について質問したいところなんですが、１と２を別々に審議というのはできないものなんでしょうか。例えば、これが継続になるというと、また１番目と２番目を議論していくと。ちょっと、２番目は、私どもとしても、難しいのではないかと。部分的なというのができるものなのでしょうかということをお聞きしたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"沢田委員","kind":"質問・要望","question":"私たちは両方、ここで出ている教育だとか、恩給費だとかというのは、今まで求めてきたことですから。ただそこで意見が違うので、両方没にするというのは勿体ない、忍びないと思いますので、１項目で一致するんだったら、ある意味じゃ、こっちが本丸と言えば本丸ですから、それでも一向に構わないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"私からは、２４日の生活者ネットワークの井上議員が行った学校給食の民間委託について。内容は、保護者への説明と、今後の計画、スケジュールというんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":26278,"voices":86}},{"id":"h16-20040927-5","meetingId":"h16-cm09","date":"2004年9月27日","dateIso":"2004-09-27","committee":"総務委員会","time":"午前１０時０5分～午後１時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年請願第２５号、郵政事業の公社堅持を求める請願","agenda":"平成１６年請願第２５号、郵政事業の公社堅持を求める請願","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"それに対するさまざまな理論を含めたものが全く聞こえてきていないものですから、もうどうなるんだかさっぱりわからない中で、方針だけが決まっているというようにも見える。役所に聞くのが適切であるかどうかというのは、実に思うんですけれども、聞く相手がいらっしゃらないので。委員長に聞くわけにもいかないものですから、とりあえず聞かせていただきたい。わかるところがありましたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"そうすると、今、郵政公社という形で一定の理念等もかざして中間の状況にあるという形の中で、もう少しきっちりとその辺のことを見てくださいというような判断のこの中身は内容は極めて当を得ていると私は思っているものですから、質問のような意見のような形で言わせてもらっているです。とりあえずそこまでで一遍切らせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"若林委員","kind":"意見","question":"公社の「アクションプランの必要性」という下の段のところで、ご自身が赤字体質から急ぐような、そういうようなことが書いてあります。そこら辺にくっつけてというか、いわゆる郵政民営化へのメリット、デメリットというのをどのぐらい考えておられるか、ちょっとお聞かせ願います。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"この日本郵政公社の第１期の決算概要が出ておりますので、その辺を含めてご説明させていただきたいと思います。それで、第１期の日本郵政公社の決算の概要ですと、公社全体としては、当期利益という形で２兆３,０１８億円の利益。メリットのほうは、先ほど行財政改革担当課長のほうがご説明した９月１０日の閣議決定の中で、３点言われております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"若林委員","kind":"質問","question":"今のメリットとデメリットを、バランスをとって比較するのが大事だというふうに思います。もう一つだけ、今の３点の政府のメリットという中で、４機能の潜在能力の発揮、そのとおりだと思います。それから、資金が民間へ流れて、また経費の問題だとかが改善されるというところは理解できる。ちょっとあれば教えてください。ちょっと報道等では私もつかみ切れないので。なければ結構です。","respondent":"榎本行財政改革担当課長","answer":"申しわけございません、そこら辺までは、まだ見えてきていない部分でちょっと出ないので。申しわけございません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"質問というか、考え方になってしまうということもありますが、基本的にはこの請願を今報告を受けて、請願の内容についてお伺いして考え方を話したいと思っているんですけれども、非常に３行目からの「郵政事業は」というところの趣旨の中は、非常に今もお話にありましたように明治４年から１３０年間の歴史を持つ郵政事業を進めてきたわけでありますけれども。","respondent":"榎本行財政改革担当課長","answer":"詳しいことはなかなか申しわけありませんが、わからないんですけれども、実際にちょっと私の手元のほうに郵政公社総裁の８月２１日に講演したものがありまして、その中からちょっとご説明をします。","voiceIndex":15,"id":"exchange-005"},{"speaker":"石田委員","kind":"質問","question":"ですから、それで我々も危惧をするのであれば、もっと違う言い方というか、違う訴え方があってしかるべきだろうなと非常に思っておりまして、それぐらいに今、また違うときに意見を言いますが、とりあえず考え方はそのように思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問・要望","question":"非常に抑えた要望、請願事項になっていると思いますけれども、その気持ちはよくわかるというふうに思います。私どもはそれに反対ですけれども、それでもこの抑えた要望の中期経営目標、自分たちで努力をやっているから、その努力を見てからにしてくれと、そういう要望というのは非常にわかるし、当然だというふうに思います。ですから、ちょっと意見ですけれども、この請願に私は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"この請願の文章ですけれども、大変中身の濃い内容でして、議会としてどういう態度をとればいいかなということを率直に言って迷いながら幾つかお尋ねを、理事者のほうに聞きますのでよろしくお願いします。閣議決定した次の日、１１、１２日に読売新聞が全国調査をやったのが２３日に報道されています。例えば、先ほど職員の数が２７万人と言われましたですね。これは全国家公務員なんですか。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"職員の部分がちょっと出ましたので、その辺のご説明なんですけれども、職員公社全体で２７万人ということで、郵便事業１２万人、郵便貯金が５万７,０００人、簡易保険が４万１,０００人、その他５万人ということで。これは私どもがそういう見解を持っているということではなくて、閣議決定のときに言われていることの理解ですけれども、現在は、郵貯とか簡保の資金のうち、ほとんど一番主要なものとして、国債の購入ですとか。","voiceIndex":19,"id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"そういうあたりはどんなふうに整理されているんですか、この閣議決定の中身、そういう中身まではさっきの説明でもわからないんですけれども、２０１７年の３月には民営化に移行となっているんですけれども。メリットの中身についても、ちょっとよく理解できないところがあるんですけれども、掌握していれば。","respondent":"榎本行財政改革担当課長","answer":"今、この基本方針の中で述べられている部分でいきますと、この推進体制ということで、この郵政民営化本部というものを設置しましてやってきているということなんですけれども。","voiceIndex":22,"id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"それで、請願の趣旨は大変重い内容があるんだけれども、そういう状況、今お話を聞いても、もっとしかるべきところから、政府筋といいますか、そちらからの資料等も説明をいただきながら、先に結論ありきじゃなくて、いい機会ですから、ご説明をいただきながら議論したほうがいいんではないかなというふうに思うんですよね。ちょっとこれは質問というよりも最後のほうは意見になりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"石田委員","kind":"質問","question":"そこら辺のことで、大変危惧というか、今の現状ではどうなるのかなと思って不安を抱いている部分もあります。それで、そういう形の中で、中期経営目標に対する実績を見てから判断するべきだろうと、これも非常にそのとおりだと私も思っております。しかしながら、今のお話を伺っていくとなると、内容がほんとうに十分よくわかりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう意味では、公社の堅持を求めるという趣旨には私はちょっと賛同しづらいかなというのが正直なところで、今の段階で言えば、この文言で言えば、堅持を求めるという、そういう意見書はちょっと出しづらいなというのが私たちの意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"そういうんじゃなくて、文章づくりの名人がいて、うまくつくっていただけると非常にいいんですけれども、必ずしもそうでもない部分もありますから、私たちが一生懸命この中からそれぞれの趣旨をくみ取るべきだろうなと、こんなように思います。そういうことですから、その部分がある意味では穏やかに表現されているのに腐心されたのかなと思いながら、この請願を見しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、やはりいろんな事情もあったり、意見もあるけれども、それでも区民のちゃんと世論を踏まえて十分に審議しろと、例えばそういう内容だったら一致できるといったようなのであれば、そういうことで出していければなというふうに私は思います。ですから、今日は私は採択できればというふうに思いますけれども、最低限のところでは趣旨採択のところで折り合いがつければなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"},{"speaker":"本田委員","kind":"質問・要望","question":"出されているのは、国会で政党の態度を表明するようなテーマですよね。品川区政でどうしようと区民の要望にどういう態度をとるかという性格のものではないわけ。しかし、ひと皮向けば、いろいろな問題を実は抱えているということも事実ですから、公社化になったり、いろいろな努力がされているわけです。国の中で。かえって説明を求められてしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-015"}]},{"id":"topic-02","title":"１６年度の総合庁舎の工事","agenda":"１６年度の総合庁舎の工事","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"特に工法が昔はだんご張りとよく言われたような、工法自体も当時と違いますし、それであるならば、１回やりかえてしまったほうがいいなんていう判断を下すというのもあるんですが、ここら辺の点は今言ったように調査をしてからということだと、ここにも書かれているこれはピンニングというのはそれだと思いますが、そういうところに踏み切ったのは、多分それのほうが安いからというんだろうけれども。","respondent":"鷹倉経理課長、宍戸施設担当課長","answer":"３点目については、施設担当課長のほうからお答えいたします。それで、これは委員からもちょっとお話があったとおり、費用対効果というふうなことで、今回このアンカーピンニング工法で、補修としては何年間かもつであろうというふうなことで判断したものです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、またそのやったって、ほかのところでひび割れが普通はしてくると考えるんだけれども、そうすると、またせっかくやりかえたのに、またほかのところがあそこは割れているよということになってきて、だから、全部やりかえちゃおうという計画的な、まさにおっしゃったように、計画的に大規模で直していくんなら、そういうことも考えるというだけでも、その部分だけとると安い方法を選んだとされて。","respondent":"鷹倉経理課長、宍戸施設担当課長","answer":"ただ、何年かということを今明確に言えないので、その割り算はなかなか難しいわけですけれども、大事に末長く使いたいということ、こういう時代ですので、そういう気持ちはあります。そうしますと、コストをできるだけ落とす。したがいまして、確かに委員がおっしゃるとおり、何年かすると、ほかのだんご張りの既存の部分が浮いてくるというふうなこともあると思いますが、基本的には、ですから、今、この方針としては。","voiceIndex":43,"id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"意見、要望だけにしますが、ぜひ、今後こういう大規模修繕でも何でもいいんですが、多分内部でやられているのかもしれませんが、基本的には民間の企業でも何でも、そういう設備投資なり改修なり、そういうところをすると、何年間でこれは改修する、そうすると、単年度で考えるとこれぐらいの費用負担はという、もちろん減価償却していって、それを決めていくわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-018"},{"speaker":"土井委員","kind":"意見","question":"石田委員の関係は、要するに今あるこの庁舎の扱いを含めたものをどう考えるかというところに大きな流れがあって、これはもう手をかけることによって１００年でも１５０年でももつんだよという発想のもとに一定程度かけていくというかけ方もあるし、もう６０年たったらやめちゃおうやという、仮にそういう話だったら、もうそろそろやめごろのときになってくると。","respondent":"宍戸施設担当課長","answer":"雨水の利用方法といたしましては、屋上の散水と、それからトイレの洗浄水です。","voiceIndex":47,"id":"exchange-019"},{"speaker":"土井委員","kind":"質問","question":"受水槽にたまった水は、まさかそこへ行ってひしゃくでくんでくるわけではないですよね。トイレに使うとすれば、トイレに注水というスタイルでの配管が必要になってくるし、屋上で使うにしてもそこまでポンプアップして持っていって、ひねったら出てくるようにしなきゃいけないわけで、そこら辺はどうなっているんですかと言っているんです。","respondent":"宍戸施設担当課長","answer":"ポンプアップするです。","voiceIndex":49,"id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"先ほどトイレに新しい便器をつけるんですよね。そうすると、雨水をトイレや何かに使おうとすれば、トイレへその水を持っていかないといかんわけですから、その配管が、とりあえずここにためるんですというなら、どんどんたまっていったらどうするのという話になっちゃうので、そこら辺をどういう算段になっているんでしょうかと。そのまま飲料水に使うようにぽんと入れるわけにいかないわけだから。","respondent":"宍戸施設担当課長","answer":"ポンプアップするとともに、配管や何かをすべて新設するものです。","voiceIndex":51,"id":"exchange-021"},{"speaker":"土井委員","kind":"質問","question":"今までも、若干のその種の水が、地下水なのか何かわかりませんけれども、活用されていて、そのためにトイレに配管をするなどという一定の水槽と配管があったと。そこに水を運ぶようにいたしますということなんですか。","respondent":"宍戸施設担当課長","answer":"説明が非常に悪くて申しわけございませんでしたが、これまでも湧水を一部活用しようという趣旨のもと、上水もかなり実は入れざるを得ない状況の中で、トイレの洗浄水は普通の手洗いの水洗などとは別に配管がなされておりました。","voiceIndex":55,"id":"exchange-022"},{"speaker":"土井委員","kind":"意見","question":"まとめると、今までも湧き水なんかを入れて、一応トイレなんかに使おうということでやっていたんだけれども、湧き水なんかだけでは足りなくて、上水も一緒に入れて、それでトイレなんかに使っていましたと、別々配管で。だって、飲み水と違っているやつなんだから、きちんと別配管にしないと危ないですよね。言っている意味はわかりますよね。","respondent":"宍戸施設担当課長","answer":"トイレの洗浄水については、全く洗浄水専用の管でつないでいるです。それから、屋上の散水栓につきましては、かぎつきの水栓にしてございまして、通常屋上にいらっしゃった区民の方々が自由にひねれないような工夫がしています。","voiceIndex":57,"id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"そういうことがあったりすると問題が起こるから、そうじゃないように、案内も含めてやらなきゃいけませんね、それは庁舎管理のところと連携をとっていただいて、その種の形に何かやっていただくこと、それともう一つ、環境課等でそういう水を使って、環境問題を我々はそういうことでやっているんですよという宣伝も使っていただくこと等もお願いをしたいという意味で申し上げていますので、よろしく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"確認","question":"議会棟とか第２庁舎、第３庁舎のところはどういうふうに考えているのか、あとは２番目の内壁タイルのところ、これは第２庁舎はまだ新しいので保留という判断なのか、そこのところはちょっと確認しておきたいと思いますけれども、あと３番目のガス管のところも、これは本庁舎と議会棟となっていますけれども、第２庁舎とか第３庁舎とか、そこら辺の考え方はどういうふうになっているんでしょうか。","respondent":"鷹倉経理課長","answer":"第２庁舎はご案内のとおりに平成６年ということで、まだ比較的新しいということで、特に配慮する必要はないというふうに考えてあります。第３庁舎も、平成１１年だったと思いますけれども、そのころに取得したときに、ガス管については既に修理しております。","voiceIndex":60,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"大体わかりました。いろいろな時点でそういう問題提起していたかと思うんですけれども、そういう一つ一つの建物あるいは全体的でもいいんですけれども、そういう全体として維持して長く大事に使いたいということなんだけれども、どういうふうにやっていくのか、そういう計画というのはつくってあるものなんでしょうか。","respondent":"鷹倉経理課長","answer":"ただ、これは具体的に予算がつくというのは、その後のことですので、私ども庁舎管理部門としては全体的に過去の履歴も含めまして持ってございまして、それをこういう形で順次やっていきたいなと。それを予算づけという形で順次お伝えする、こういうことになろうかと思います。","voiceIndex":62,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、大規模修繕というのは総合庁舎で持っているということですよね。それについて、こういう計画が来ているということですか。","respondent":"本間総務部長","answer":"先ほど来、大規模修繕のお尋ねがありますが、基本的には経理課長が答えたとおりなんですが、通常のこの種の建物、一概には言えませんけれども、約６０年だとかという説はあります。","voiceIndex":64,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。質問が変わるんですけれども、そうなると、例えば、１、２、３、４の大きく今回四つの工事なんですけれども、それぞれ大体何年ぐらいこれによってもつのか、あと費用がどのぐらいかかるのか、ちょっと大くくりで１、２、３、４でいいんですけれども、どんな感じになるんでしょうか。","respondent":"鷹倉経理課長","answer":"排水管は法定耐用年数ですけれども１５年、実際には十七、八年もつだろうというふうに言われておりますけれども、ガス管のほうが今１５年ないし２０年、ちょっと幅がありますけれども、そのようになってあります。","voiceIndex":66,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"意見","question":"この今の当面この工事をやってということなんですけれども、これからまた考えられるという、その種の工事というのは、あとどういうものが出てくるのか、今、大体頭に思い浮かべているものといいますと、どんな感じのがありますか。","respondent":"鷹倉経理課長","answer":"電気回り等は前年大体終わってあります。２年間かけて電気のものはやってありますので、その辺のところが大きいのかなと。ただ、そうは言ってもいろいろなものがおいおい出てまいりますので、その辺も踏まえながら計画的に考えていきたいというふうに考えてあります。","voiceIndex":68,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"意見","question":"最後に１点なんですけれども、一番最後のこの雨水利用で、これは当然もう水道代も安くなると思うんですけれども、費用的にはどんな感じでプラスマイナスで、どういうふうに。プラスを含めて総計が１,８００万円のバランスだったんですけれども。どういうふうになりますか。","respondent":"鷹倉経理課長","answer":"それぐらいかなというふうに考えてございまして、この平成１４年、１５年、総合庁舎全体で２万５,０００ｔ、年間利用料金が２,２８０万円ぐらいですので、これで１００ｔ減になることによって何十万円ぐらいのオーダーで減になるのかなというふうに考えてあります。","voiceIndex":70,"id":"exchange-030"},{"speaker":"石田委員","kind":"質問・要望","question":"これは行ってあれなんで、行ってから一生懸命勉強し直そうと思ったんですけれども、１点だけ全然内容と違うかもしれないので教えていただきたいんですが、私が勉強不足だったらすみません、あれなんですけれども、今たまたまちょっと気がついたんですけれども、水沢市の最後のところで、アメリカ連邦会計検査院、このＧＡＯというのが書いてあったり、あとは下記の文献をもとにして。","respondent":"中尾根企画部長","answer":"早くやられているから、おそらくいろいろな意味で、いずれにしろいろいろな自治体の参考のためにこういうふうにつけていただいているという場合もあるかと思いますが、それは向こうに行って聞いていただければと思います。","voiceIndex":80,"id":"exchange-031"},{"speaker":"若林委員","kind":"質問","question":"水沢市のＩＣカード活用なんですが、お話を聞くとあまり大してしていないんじゃないか、品川区も結構よくやっているんだという、何か見るべきものがそれでもあるんでしょうか。","respondent":"中尾根企画部長","answer":"水沢市の場合は、ＩＣカードというものを媒体にしながらサービスを行っている、こういう点だという意味で言いましたので、誤解があったら、すみません。","voiceIndex":82,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":49290,"voices":84}},{"id":"h16-20040928-6","meetingId":"h16-cm09","date":"2004年9月28日","dateIso":"2004-09-28","committee":"区民委員会","time":"午前１０時０２分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年請願第１８号および平成１６年請願第２０号、小規模非住宅用地の固定資産税・都市計画税の減免措置の継続につき意見書の提出を求める請願にかかる意見書","agenda":"平成１６年請願第１８号および平成１６年請願第２０号、小規模非住宅用地の固定資産税・都市計画税の減免措置の継続につき意見書の提出を求める請願にかかる意見書","exchanges":[{"speaker":"山村委員","kind":"意見","question":"観光資源の調査のところで、ものをつくるというのを調査されるというふうに聞いたんですが、それ以外に、例えば北品川のほうの老舗の料理屋とか、そういう飲食店関係で品川区は歴史があるようですが、そういうことに関しては、観光協会で取り上げていくのかどうか。","respondent":"日下部産業振興課長","answer":"飲食店も、今おっしゃったように、老舗と言われているような、ほかにはないようなお店も区内にいろいろありますので、飲食店の関係も区内の観光資源としては非常に重要な素材にもなりますので、こちらも含めての調査ということで検討を進めております。","voiceIndex":15,"id":"exchange-001"},{"speaker":"山村委員","kind":"意見","question":"例えば老舗でなくて、最近できた店でも凄く評判がいいとか、歴史的なことは抜きにして、区外からでも食べに来る価値のある店は品川区内にはいっぱいあると思うんですが、そういうものまでフォローするのかどうか。","respondent":"日下部産業振興課長","answer":"新しいお店の場合は、その辺をどこまで把握をし、また、どこまでアピールをしていくのか、なかなかた難しい面はあります。","voiceIndex":19,"id":"exchange-002"},{"speaker":"山村委員","kind":"質問","question":"今後そういうような形にして、東京都のようなことをやる気があるのかというか、東京都は東京都でやっているという面もあるんですけれども、さらに細かく品川区でやる場合は品川区の収入になるわけですから、そういうことは考えられているか、どう思われているか。","respondent":"日下部産業振興課長","answer":"そういう一種の登録制という形で、一つ仕組みとして受け皿をつくっていくのかどうか、この辺も含めて、基本調査の中で検討をしていきたいというふうに思います。","voiceIndex":21,"id":"exchange-003"},{"speaker":"山村委員","kind":"意見","question":"私としては、民間のほうの何気ない風景でも意外に撮影というのは効果がある。そういうふうに細かくあっ旋していただける場所があれば、ほかの区がやっていなければ、やっていない部分品川区が登場する機会が増えますので、そういう意味では観光というか、品川区のアピールにはなると思います。それに占有料的なものを払っていただく。今後そういう意味では頑張っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"主な事業内容のところですけれども、基本調査が今進められているということで、どのようなメンバーで、どういう感じ、ちょっとイメージがわからないので、いつ立ち上がって、どのようなイメージで、どこかに委託しているのか、それとも区の中でやっていらっしゃるのか、あと最終のまとめはどの辺においていらっしゃるのかというのを質問をします。","respondent":"日下部産業振興課長","answer":"基本調査の関係ですけれども、これにつきましては、しながわ観光協会に委託をして実施しております。ただ、しながわ観光協会のほうとしましては、観光関係のシンクタンクのご協力をいただいて、より専門的な立場も含めて検討を進めているという状況です。","voiceIndex":24,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"言ってみれば、丸投げみたいな感じで、まとめができた段階で何か品川区の中やしながわ観光協会の中で何かされるのか。よく普通に計画などをされる場合には、そこから出されたものが品川区なりの文書にだけ変更されてそのまま出てくるというようなこともありますけれども、その先はどうなるんですか。シンクタンクからの調査のまとめがきた段階では。","respondent":"日下部産業振興課長","answer":"そこでいろいろな検討をし、より専門的なところで、ほかの全国の事例とか、例えば経済効果について、ある程度専門的な視点からの算定の作業とか、そういうのも必要になってきますので、そういう専門性が必要な面については、シンクタンクのほうのアドバイスを受ける。","voiceIndex":26,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"今までのお話を伺っている中では、都市型観光というのが、地域活力の増大と、産業の活性化というのは、産業振興課のほうが担っているというような、中小企業センターの中に拠点もあって、そういうイメージなんですけれども、品川区の文化、歴史と言えば、教育委員会とか、生涯学習課とか連携があると思うんですが、その辺の連携はどのようにとられているんでしょうか。","respondent":"日下部産業振興課長","answer":"歴史であるとか、文化、それについては教育委員会のほうがいろいろ面での材料をいっぱい持っているということもありますので、これは今後具体的な作業の中で、ヒアリングも含めて、教育委員会ともいろいろ連携、調整をしながら進めていくということで予定をしております。","voiceIndex":28,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"要望として、連携を深めていくというよりも、これをしようとした段階で、立ち上がる段階で連携をして、縦割りではなくて進めていって、品川区全体の、今回視察に向けてはそういうことがメインになるんじゃないかと私は思っているんです。","respondent":"日下部産業振興課長","answer":"あるいは品川の近辺、あるいは大井町周辺という選択もあろうかと思います。その辺はいろいろな角度から今検討を進めているです。","voiceIndex":30,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"どこかの観光名所に行って、駅前にそういう観光のガイドが並んでいるという、今のお話を聞くと、そんなイメージができてしまったんですけれども、旅行に行くときに、どこかの温泉地に行って、そういうパンフレットがあるなというような、それも一つかもしれないですけれども、品川区の中を向いて、もっと品川区全体で名所・旧跡、歴史とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"予算が１,５６０万円出ておりますけれども、これは国とか、東京都の補助もあるんですか。品川区独自の予算ですか。","respondent":"日下部産業振興課長","answer":"この都市型観光の関係の本年度の予算につきましては、国や東京都の補助金というのは見込んでございません。","voiceIndex":34,"id":"exchange-010"},{"speaker":"山路委員","kind":"意見","question":"観光といいますか、旧東海道を中心にというすぐイメージがわくんですが、先ほど教育とのリンクの話がありましたけれども、歴史館とか、文化財との兼ね合いがどうなのかなとかすぐ浮かんでくるんですね。新しい大崎があります。旧東海道品川宿周辺まちづくり協議会といいますと、品川駅周辺との協定とかいろいろあります。それについて説明をしてください。","respondent":"日下部産業振興課長","answer":"ですから、当然のことながら、区内のいろいろな資源、素材を活用していこうということが出発点でありますけれども、ただ、今ご指摘にありましたけれども、ほかの区とのいろいろな隣り合っているようなところでの素材というのもありますので。","voiceIndex":36,"id":"exchange-011"},{"speaker":"山路委員","kind":"質問","question":"そうあるべきだと私も思っていたんですけれども、新たにこれから海のほう、ベイ地帯が開発されていきますよね。そういう面では、品川を拠点にして、２３区、それから全国から非常に発展していくことはいいことだと思うんです。ポイントと言いますか、品川区としては、ここに担当の方を置くわけですか。協力体制なのか教えて下さい。","respondent":"日下部産業振興課長","answer":"実際の体制としましては、先ほどの経過の中でもお話ししましたけれども、品川区の観光の推進の特色というのは、まちの皆さんが一生懸命やってこられたということでもありますし、その町場の皆さんを中心に組織が成り立っております。","voiceIndex":38,"id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいんですが、平成９年にしながわ観光協会が発足をして、当初から比べるといろいろな事業に対して今発展的にいろいろ携わってきております。そしてまた、今後の中で、そういった体制、要するに、行政と、そういった観光協会との係わりをどういう形で持っていこうとされているのかをお伺いしたいと思います。","respondent":"日下部産業振興課長","answer":"これまでの品川区のしながわ観光協会への事業の委託ということでありますけれども、先ほども申し上げました、平成１４年度からスタートしておりますまちの瓦版の運用であるとか、あるいは観光資源台帳の作成、それから、先ほども触れました、基本調査の実施につきましても。","voiceIndex":40,"id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"今まで行政が主導をしてやってきた事業の中で、できるだけ多くの形でしながわ観光協会に携わってもらって、そこを行政と民がタイアップをしっかり持っていくということが非常に大事な今後の中の動きではないかなと思うんですが、例えば都道府県等々もいろいろな形を持っていると思うんですが、そういったところの資料等も含めて、今後もう少しイメージをふくらませていただきたいなと思うんですが。","respondent":"日下部産業振興課長","answer":"例えば観光協会は２３区の中で１１区ほどありますけれども、半分ぐらいの区が、例えば商工部門の中に観光協会が一緒に同居しているといいますか、区が観光協会の一つの役割を兼務しているとか、結構そういうところがありますし、そういった意味では。","voiceIndex":42,"id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"今回１２月に海外調査という形で、この委員会に係わるということで、スイスにおける災害対策および危機管理ということですが、所管の区民委員会としてもいろいろな項目の中で、特に大枠の形の中では、スイスにおける災害対策のどういう計画を持ってされているか、そしてまた、その計画の中で連絡調整はどんな形でしていくのか、１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-015"},{"speaker":"山村委員","kind":"意見","question":"私のほうからは、区民委員会の範囲かどうかちょっとわからないんですが、スイスにおける災害対策および危機管理で、どのようにボランティアを活用しているか。災害対策ということになると、どうしても地域の連携が密であればあるほど、いざというときは有利だと私は思うんですが、そこら辺に関してどのような地域の連携を持っているか。それから、どのような意識にあるかといったことが聞きたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"ここにテーマが出てきたところで、お聞きする機会がなかったので、どうぞこのことをというふうに納得するためには、スイスにおける災害対策がどのようにあるのかお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-017"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"スイスの災害対策および危機管理ということですけれども、日本、とりわけ東京都、品川区とは同じ都市でも違うというところで、我々が一番心配しているのは、震災、台風等ですけれども、スイスにはそういう両方の心配が全くないようですが、どこに共通点を求めて視察をしていくか、かなり難しい話になってくる。スイスの特徴というのは、ほかの危機はたくさんあるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2406#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":14014,"voices":60}},{"id":"h16-20040928-7","meetingId":"h16-cm09","date":"2004年9月28日","dateIso":"2004-09-28","committee":"厚生委員会","time":"午前１０時０２分～午後３時０３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南副委員長","kind":"質問","question":"説明いただきましたけど、大体趣旨としては了解したところですけども、ちょっと実施のところの本格実施とこの１０月に実施、試行的運用という、そこのところの内容がちょっといま一つ理解しきれないので、本格実施にならないという、そこは予算的なものなのかなんなのかよくわからないんですけど、体制そのものがとれなくてとかというのがあるのか、ちょっとその辺を詳しく教えてください。","respondent":"田中健康課長","answer":"確かに試行的といいますと、モデル実施という形の言葉なんですが、実際上は事業委託をして進めします。","voiceIndex":8,"id":"exchange-001"},{"speaker":"南副委員長","kind":"質問","question":"それを４０歳以下に広げていくという、そういうことで１０月から実施するということだと思うんですけど、医師会の中で体制も含めて紹介をどこまで出すのか、紹介というか、どこまでするのかというお話のようなので、それはそれとして受けとめていきたいとは思っているんですけども、しかし、いま一つ要求との関係でなかなか段階を踏む必要がどこまであるのかなというのが。","respondent":"田中健康課長","answer":"今副委員長からご指摘がありました特に４０歳の要件を外すという意味合いになりますと、障害者の方の、いわゆる知的障害の方、身体障害の方、精神障害の方という範疇で考えられるわけですけれども、実は医師会等々の先生方との議論でも、障害の方の程度というんでしょうか。","voiceIndex":10,"id":"exchange-002"},{"speaker":"南副委員長","kind":"意見","question":"わかりました。つつがなくというか、障害を持っていらっしゃる方も歯科の診療がきちんと整って、健康な生活を送れるという体制を一日も早くとれるようにというところで、こういう拡大されたというところのあれは高く、高くというか、受けとめていきたいというふうに思っておりますが、そういう状況の中で進めているということを理解したところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つ質問なんですけれども、今まで区で申請の受け付けをしていたのが、医師会のほうに移ったというご説明なんですけれども、私大分以前なんですが、歯科医というのは歯科医師会に入っていない歯科医師さんも多いと聞いたんですけれども、なかなか歯科医師会に入るのにはお金もかかって、例えば若い歯医者さんだとなかなか入れないという財政的なものを聞いたんですけども。","respondent":"田中健康課長","answer":"今、品川歯科医師会では、会員数が大体１８５人、毎月のように若い先生、今お話がありましたが、入っていらっしゃる、会報もいただいておりまして、１カ月３人とか４人とかというオーダーで新会員の方も入っておりますし、特に医師会の先生方に比べると。","voiceIndex":13,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"歯科医師会に加盟していらっしゃる７割強というところでは、入っていらっしゃらない歯科医師さんもいらっしゃるということでは、熱心で意欲的な方もいらっしゃると思うので、区のいろいろな制度で区民が選択ができるようなところの配慮というのが必要ではないかなと思うんですが、いかがでしょうか。","respondent":"田中健康課長","answer":"それでこの間、医師会のほうでは、それぞれ研修ですとかいろんな形でこのシステムに対応するためのいろんなことをしていただいていますので、そういう意味でのシステムとしてのレベルの維持という、そういう部分を含めてありますので、私どものほうとしましては。","voiceIndex":15,"id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"１点だけ。障害者の方ということで、その障害の程度ですね、軽度の方から重度の方がいると思うんですけど、その程度に限らず、極端な重度の方でも受け入れは可能なんでしょうか。","respondent":"田中健康課長","answer":"そのことで、やはりしっかり対応できませんと、逆に非常に怖い場面もあるんだよという話が歯科医師会のほうから指摘がございまして、そこでこれからもできる範囲をまず見定めながらニーズに応えていこうという内容です。","voiceIndex":18,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問","question":"そうですね、私ちょっと単純にやっぱり心配しちゃうのは、特に精神とか知的の障害の方、じっとできないような方ですね、動いちゃったりして、そういう部分が治療する場合にどうやって治療するのかなというのがわからなかったので、もしその辺、何か今これに限らずですけども、一般的にそういう方が治療されるときに麻酔とかなのか、ちょっとその辺わからないんですけど、何かあれば教えていただければ。","respondent":"青山品川区保健所長","answer":"一見した状況では、その方がそれほど障害が重そうに見えなくても、人が近くに来た、あるいは口をあけさせようと思った途端に非常に暴れだしたりというようなこともありますので、そういう点では個々の方の障害の状況というものをしっかりととらえた上で。","voiceIndex":20,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面で、この検討するような状況にある学童保育クラブがどこなのか、ちょっと教えていただけますでしょうか。","respondent":"辻田児童課長","answer":"昨年も滝王子学童保育クラブにつきましては定員増ということで九十何名の子どもたちが入りましたけど、当然それは学童保育クラブのほうでも余裕があって、そしてその整備をしながら子どもたちを受け入れていた状況がありますので。","voiceIndex":27,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すごく評判なところということで、ほんとうに活用されているのはうれしいんだけども、事故がないといいなと思っておりましたら、何か先日骨折事故が起きたという話もちらっと聞いたんです。ですから、ここの学童保育クラブのことだけじゃなくて、やっぱり周辺のことも考えて十分考慮して、利用者の納得のいく方向で進めていただきたいと思いますが、いかがでしょうか。","respondent":"辻田児童課長","answer":"ちなみに先日、私は荏原の後地小学校の子どもが５名いるという保護者の方に集まっていただきまして、その中で説明等をいたしました。","voiceIndex":29,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"元気な子どもたちが集まる場所ですから、事故が全くないということはないんで、仕方のない事故も当然あると思います。それは理解します。だから、そういった面では、さまざまなほんとうに安全を配慮した上で起こった事故というのは、それは当然いたし方ないなという部分もあると思うんですが、ぜひ最大限の配慮をしていただきたい。これは要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"お聞きしたいんですが、１０月に新たに１２校ということですが、１０月からスタートするのかということと、１２校全部がスタートするのか。学童保育クラブがゼロになるので、平成１６年度末で閉鎖するのか、それとも１０月からするのかを教えていただきたいんですけど、１０月に閉鎖する場合３月の末まで学童保育クラブの空き部屋はどうするのか、そこら辺をちょっと教えてください。","respondent":"辻田児童課長","answer":"どちらにしても、すまいるスクールと併用しているお子さんはだんだんなれてくるんですけど、すまいるスクールじゃなくて、学童保育クラブに私３月までいるという子どもについては、すまいるスクールになれていただくために、いろんな形の交流をしたり。","voiceIndex":32,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"閉鎖予定の五つの学童保育クラブの中で、既にその閉鎖された跡の使途が決まっているようなところがありましたら教えてください。","respondent":"辻田児童課長","answer":"現在児童センターの改革ということで、その機能を強化していこうということ、その辺の検討しておりますので、この辺につきましては、それぞれの館がどういう役割を果たしていけるか、そこら辺を見極めながら対応を図っていくということで。","voiceIndex":34,"id":"exchange-012"},{"speaker":"南副委員長","kind":"確認","question":"大前提として、動いている子どもたち、元気のいい子どもたちを受けて事業を開始しているわけですから、どんなことがあるかわからないし、起こっちゃいけないんですけど、起こらないための最大限の努力は当然しているんですけども、しかしそれでも起こっちゃう場合はあるけども、だからといって、先ほどのちょっと説明では、私はわかりました。","respondent":"辻田児童課長","answer":"そういう中で、私どものほうが大切にするのは、まずその前提に事故が起きないということ、それから事故が起きたときにどういう対応をしていくのか、それから親への対応をどうするのかというようなことで、その辺を大事にしながらやっていくということを申しただけで。","voiceIndex":36,"id":"exchange-013"},{"speaker":"南副委員長","kind":"質問・要望","question":"したがって、ぜひ調べていただきたいというふうに先ほどもお話しさせていただきましたけども、ぜひほんとうに滝王子学童保育クラブであったのかどうか、それを私も知りたいと思いますので、後でで結構ですから教えてください。事故が起こる前ですけど。","respondent":"辻田児童課長","answer":"ですから、一人一人個別の中でいろんな状況を勘案しながら、私どものほうは進めているということで、学童保育、要するに少ないところのクラブでは、学童保育事業はできない、子どもの育ちが保障できないということで、私どものほうは今回そういうような対応をしていったわけです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"南副委員長","kind":"確認","question":"あまりこの問題で論争するつもりはないんですけども、滝王子学童保育クラブは、じゃあ学童保育クラブとして何名定数のところを何人滝王子学童保育クラブについては移行の過程の中で何人の子どもが入っていたんだったんでしょうか。したがって、ちょっと何人の定員のところに、何人の子どもを入れて、移行の過程を踏まれたのかをちょっと改めて確認したいと思いますので教えてください。","respondent":"辻田児童課長","answer":"滝王子学童保育クラブの定員は６０人です。そこで、９４人の、年度当初ですけど、９４人の子どもが入っているです。それから、性急過ぎたですけど、今年いろんな形で報告を受けていますし、私も実際にすまいるスクール等の説明会等にも参加いたしました。","voiceIndex":40,"id":"exchange-015"},{"speaker":"南副委員長","kind":"質問・要望","question":"３４人というのは一つの学童保育クラブの規模ですよ。ほかの設備の部屋も使ってもいいよと言いながらも、あそこは事業活動が盛んなところですから、さっきもご紹介したように、１日中いろいろな方たちが親子で出入りしたり、児童センターに子どもたちが来て、目いっぱい朝から、夏休みなんかは特に朝から夜まで楽しんで生活するところですよね。ですから、こういう事故があって、私は当然だ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"},{"speaker":"築舘委員","kind":"確認","question":"今お話を聞いているところによると、すまいるスクールが来年残り９校ということで、そのほとんどの学校にすまいるスクールができたということで、学童保育クラブを閉鎖しても、その選択ですが、一人一人の子どもたちにとって、すまいるスクールというところに行くという人もいれば、児童センターで一緒にやっていくという人もいるんだと思いますが、その点、その他のところで。","respondent":"辻田児童課長","answer":"それで、学童保育クラブはあと９校開校いたしますので、そういうことでいきますと、この９校が開校することによって平成１７年度末、失礼、すまいるスクールが９校です。児童センターが平成１７年度末に１３館ということでいく、今のところ予定になっているです。","voiceIndex":43,"id":"exchange-017"},{"speaker":"本多委員","kind":"質問","question":"すみません、ちょっと教えてください。年度末に閉鎖する５館は、年度末まで職員配置は従来どおりでいいんですか。","respondent":"辻田児童課長","answer":"職員配置、単独館ですと２名、センター館ですと１名ということで担当者を配置しておりますけど、基本的に３月末までは配置いたします。","voiceIndex":45,"id":"exchange-018"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、当然学童保育クラブのほうを閉鎖してから、配置がえしてすまいるスクールのほうとかに移りますよね。すまいるスクールは１０月からスタートで、学童保育クラブは年度末までで、その辺の兼ね合いというか、ちょっと教えていただきたいんですが。","respondent":"辻田児童課長","answer":"そういう中で、今学童保育クラブに通っている子どもたちが一遍に団子状態で来られますとなかなか対応できないと、そういうような現実的なこともあります。それからもう一つは、先ほど言いましたように、子どもたちのなれです。","voiceIndex":47,"id":"exchange-019"},{"speaker":"嶋委員","kind":"質問・要望","question":"この平塚橋会館ですが、この平面図を見しますと、お骨になっている葬儀がありますね。それはどこの部屋を使っていらっしゃるのか。それとあと、この第三、第四、第五の集会室ですが、地元ではどっちかというと使い勝手のいい部屋なので、今まではこの部屋はどのように利用されていらっしゃったのか、ちょっとお聞かせをいただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"第三から第五集会室のご利用ですけれども、詳しくは承知してございませんが、聞いたところでは、やはりいろいろな自主的な活動の団体ですね、趣味ですとか、それから地元の町会、自治会等の会合等に利用されているというふうに聞いております。","voiceIndex":53,"id":"exchange-020"},{"speaker":"嶋委員","kind":"質問","question":"式場がまだ二つあるということでよろしいんですが、町会、自治会で使っている部屋をシルバーセンターに使うということによって、地元では困るんではないかと思いますが、そこら辺はどのようにお話をされていらっしゃるのでしょうか。","respondent":"蓼沼高齢事業課長","answer":"具体的にどの団体がご利用されているかちょっとわかりませんが、この平塚橋会館１階の第三から第八までの集会室と、それから２階にも第一、第二と集会室がございまして、そういう意味で、利用率で申し上げますと、かなりまだまだ全体でですけれども。","voiceIndex":55,"id":"exchange-021"},{"speaker":"嶋委員","kind":"質問","question":"利用率が十数％ということは、今まで使い勝手が悪かったということでしょうか。ちょっとそこら辺、今課長は使い勝手がよくなるとおっしゃったんですが、この利用率が十数％だったということは、使い勝手が悪かったから十数％だったのか、ちょっとそこら辺よくわからない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-022"},{"speaker":"嶋委員","kind":"質問・要望","question":"すみません、ありがとうございました。これが地域でなっていくということですので、地域への周知というのはこれからだと思いますが、ぜひ地域の方の意見をたくさんお聞きしていただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"今後地元の町会の皆様ですとかにつきましては、地域活動課と、それから区営住宅がありますので、住宅課長とも相談して今後説明をしていきたいと考えています。","voiceIndex":60,"id":"exchange-023"},{"speaker":"嶋委員","kind":"質問・要望","question":"地域に開いていた集会室だと思いますので、地域の方のいろんな要望等もあると思いますので、ぜひ皆様にご理解をいただけるような新しいまた有効活用ができるようにお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"中延シルバーセンターの移転のことなんですが、聞き漏らしたのかもしれませんが、スペース的には現在よりも広くなるんでしょうか。使い勝手とか、どうなんでしょうか。","respondent":"蓼沼高齢事業課長","answer":"ほぼ現行と同じ規模です。厳密に言いますと、少し、気持ち広くなるかなという感じです。","voiceIndex":63,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"成幸ホームのほうなんですが、今３階建てを４階建てにするというお話があったのと、期間的にかなり長いので大々的な工事であるなと思うんですが、１点予算のところで、補助金の問題なんですけれども、特別養護老人ホームの建設に当たって前に補助金が減らされるというか、圧縮をされているというような話を聞いたんですが、その辺、予算的なところの補助金の問題を１点と、あと特養ホームのところ。","respondent":"早津高齢福祉課長","answer":"新型の特養ホームというのは、個室であることのほかにユニットケアというもので、９室ぐらいを単位として部屋の前にリビングスペース、食堂スペースがあって、その９人がまとまって生活できるような形になるわけですが、この建物、構造的にもそれは不可能でございまして。","voiceIndex":65,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"ホテルコストのことを聞いたんですが、利用者に対しての負担は従来型というところでは同じ扱いという受けとめでよろしいでしょうか。","respondent":"早津高齢福祉課長","answer":"失礼しました。新型ではございませんので、従来と同じ形ということになります。","voiceIndex":67,"id":"exchange-027"},{"speaker":"南副委員長","kind":"質問","question":"そうすると、ショートステイを定員増し、デイサービスも増やし、痴呆型も１０名増やすということの改善内容なんですけれども、ちょっと平面図がないからどういうふうになるのかがちょっと見えないので、それはこれから準備の中で出てくるんだろうと思うんですけども、いわゆるそういうショートステイ部分、あるいはデイサービスの部分のスペースががっと広がり、個室分も広がっていくという。","respondent":"早津高齢福祉課長","answer":"エレベーターが１基しかないですとか、食堂のスペースが一つしかないですとか、あるいは４人部屋が基本であるというようなことで、その辺全体を改善していこうということで、使う場所は、広くする場所は隣のシルバーセンター。","voiceIndex":71,"id":"exchange-028"},{"speaker":"南副委員長","kind":"意見","question":"わかりました。そうすると、予算だとか、そういうものについてはこれからはっきり出てくると、そういうことですよね。今回の報告事項の中では、内容の説明だけで、予算規模がどういうふうになっているのかというのは来年度に、８月から工事が始まるから来年度予算に入れていくということでいいわけですね。","respondent":"早津高齢福祉課長","answer":"その辺を含めまして、平成１７年度予算等の条例も含めてですが、これから検討していくです。","voiceIndex":73,"id":"exchange-029"},{"speaker":"嶋委員","kind":"質問・要望","question":"今防音ということが出たので、２階のほうですけど、第一と第二集会室なんですが、これが隣の部屋を使うと隣に全部話が聞こえてしまうんですが、そういう場合に、これまた違ってくるかもしれないんですが、そのときもぜひ一緒に全部を考えていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-030"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、子育て支援の視察を幾つかしていますけれども、今ほんとうに今まで就労支援というのに力を入れてきたところ、就労も含めてすべての子育てを応援するというところを国も地方自治体も力を入れているというところでは、ほんとうにどうしたら国の特殊出生率を１.２９を上回る、品川区もほんとうに最大の関心事だと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"意見","question":"ぜひこの辺もすごく重要で、今後重視というか、拡大をしていったほうがいい事業だと思っているんです。私だけかもしれない。特に保健所のところの子育ての分野がなかなかわからないんで、ぜひその辺のご報告も今後いただけたらと思うんですが、いかがでしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-032"},{"speaker":"嶋委員","kind":"質問・要望","question":"今の聖火のやる時間帯がもしわかっておりましたら、教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"時間は１０時半から式典が始まりますので、式典の中で聖火の点火式をやりますので、１０時半ぐらいから１１時半ぐらいにかけて周りをぐるっと回るというふうな予定になっております。","voiceIndex":111,"id":"exchange-033"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"調査事項ということじゃないんですけど、今１０月２６日の北九州市できっずこくらみなみですか、これがなくなったということなんですけど、そうすると、２６日はウェルとばたのみの視察になるのか、それともできればほかのところもという、これは要望なんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-034"},{"speaker":"南副委員長","kind":"意見","question":"この委員会の所管事務調査事項として子育て支援も一つ大きな柱にあるので、なかなか今部長がご説明いただいたこの資料では民間が主導で施設を展開して、事業も展開しているという話のようなんですけども、子育て支援のところがどういうふうになっているか、あるいは次世代育成は品川区で言えば企画になっちゃうので総務委員会のところなんですけど、直接的にもかかわり合う委員会なので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":34577,"voices":124}},{"id":"h16-20040928-8","meetingId":"h16-cm09","date":"2004年9月28日","dateIso":"2004-09-28","committee":"建設委員会","time":"午前１０時０３分～午後２時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年請願第２１号（仮称）「グローリオ戸越銀座II」新築工事に関する請願","agenda":"平成１６年請願第２１号（仮称）「グローリオ戸越銀座II」新築工事に関する請願","exchanges":[{"speaker":"林（和）委員","kind":"意見","question":"１点、請願の主旨ですけれども、主旨で１、２、３と３つ出ておりまして、それぞれ「反しております」ということなんですけれども、したがって、「品川区の要綱、条例、施行規則を遵守した建設となるよう希望いたします」ということなんですけれども、このことについてどう思われますか。","respondent":"浜脇住環境整備課長","answer":"住民説明会等で近隣の状況について説明を行い、その中で出た要望については検討を加えて、近隣との対応に努めているというふうに聞いておりますので、それについても反しているというふうな状況じゃないと思われます。","voiceIndex":9,"id":"exchange-001"},{"speaker":"林（和）委員","kind":"確認","question":"ありがとうございました。丁寧にご答弁いただきました。そうしますと、もう一度確認いたしますけれども、請願の主旨１、２、３については、いずれも請願は「反しております」ということですけれども、「反していない」ということですね。","respondent":"浜脇住環境整備課長","answer":"私どもといたしましては、今までのいろいろな届出といいますか、報告から見ますと、これらについては、「要綱、条例、規則」は一応守られているということで、それは住民とのかかわり方かちょっとわかりませんけれども、一通りの事はやっているというふうに考えておりますので。","voiceIndex":11,"id":"exchange-002"},{"speaker":"林（和）委員","kind":"質問・要望","question":"７月には、３回目を３０名、７月３１日には４回目で３０人の説明会を行い、そして８月になってからは、代表者と４回打ち合わせをされておりますということで、９月に入りまして、代表者と打ち合わせをしている最中だですので、きょう初めての審査なものですから、委員会といたしましては、きょうのところはひとつ様子を見るということで、一応継続というふうな形で取り扱っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"高星委員","kind":"質問・要望","question":"民有地の中に３４０枚のチラシで間に合ったんですか。住んでいる方だけなんですか。地権者はどうなんですか。そういう意味で言うと、品川区の、先ほど来言っていますように、都市景観ガイドプランの基本的な理念から考えたときに、今度の場合は、そういう意味で、２６号線の北側に接する建物なものですから、近隣住民に直にいろいろな影響が出てくる、これは間違いない事実だというふうに思うんですね。","respondent":"中谷まちづくり事業部長","answer":"そういうことに結びつけられればなということで、今現在考えておりまして、まだ個別具体の十何階建ての建物とガイドプランとがどうのという、まだそこのところまでの、個々のところまで詰めておりませんが、今後そういうお話も出てくる際には。","voiceIndex":14,"id":"exchange-004"},{"speaker":"高星委員","kind":"意見","question":"ありがとうございました。木造だめよとかといういろいろなものがあるわけだけれども。当該建物の基本設計を見ますと、後ろのほうが大分あいているようでありますけれども、こういったものが、例えばもう１、２階減らして、当該の後ろのあいている部分に、例えば風を直接下へ落とさないとか、それを何とか風を食いとめるような建物の変更も含めてできないものなのかどうか。その辺は何か話を聞いていませんか。","respondent":"浜脇住環境整備課長","answer":"施設の計画については、変更しないということで、何か窓ですか、植栽なんかを考えるというようなことを図面でのっておりまして、そういった意味では設計変更はしないというふうなのが、向こうの建主の考え方であると思われます。","voiceIndex":16,"id":"exchange-005"},{"speaker":"高星委員","kind":"質問","question":"だから、例えば上の１つをとって、１階ドアの下にあるいは２階ドアの下に、そこにビル風、北風をいきなり下に落とすんじゃなくて、落とさないような構造物って、設計上できないことはないわけで、確かに余分な出費がかさむかもわからないけれども、そういったところ、区の行政サイドでは、指導という形ではなかなか難しいのかもわからないけれども。","respondent":"浜脇住環境整備課長","answer":"ある意味では議会のほうで、そういう流れの中で指導せよということがあればできますが、今のところ私どものほうから、そういった大々的な設計変更に対する指導というものはできないです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、こういう解体工事に対しての今回の住民に対して、区がどういうふうに指導したのかということを１点お聞きしたいのと、それから、説明会のところでも、説明の案内をどこにだれが住んでいるかわからないから配れないというふうなことで、案内もきちんとされなかったというふうなことがここの中には書いていますけれども、２Ｈの範囲というのは。","respondent":"浜脇住環境整備課長","answer":"ここで解体が行われるについては、口頭ですけれども、解体について説明をしたほうがいいですよということは言っています。なぜかというと、解体を最初に、ある意味では建築計画のほうでも、また紛争の種といいますか、トラブルのもとになりますよということでは指導しています。","voiceIndex":20,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、ぜひ工事前にしっかりと、マンション建築についての説明会をやると同じような形で、解体についても説明会をしっかりと地域の人にして、それで地域の人が納得いくような形で進めていくという、そういう指導をぜひしていただきたいなというふうに、解体については思うんですけど、要綱ができる前であってもね、いかがでしょうか。","respondent":"浜脇住環境整備課長","answer":"今後いろいろなお話を伺って、あとで触れると思いますけれども、例えばこの委員会の何か提案といいますか、助言といいますか、そういったものがあるのかもしれませんから、そういったものを加味しながら対応すれば、受けとめて今後要綱作成に向けて努力するということは。","voiceIndex":22,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、この請願の中では、かなり風害のことが心配なんだということで書かれているんですが、２６号線を挟んだ向かい側に１４階建てのマンションが、何年前、２、３年になるんでしょうか、できましたよね。","respondent":"浜脇住環境整備課長","answer":"７月３１日の日に、風についてのシミュレーションといいますか、検討したものを持ってご説明をしているです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これに対してどういう対策を立てるというふうなことで出されているのかということをお聞かせいただきたい。","respondent":"浜脇住環境整備課長","answer":"これは、まだ風害に対してこういう地域だからこういうのというのは、ある意味の学説的なというか、学者とか研究者のほうでこういうものだろうというのであって、行政側から見て指導できるようなそういう基準というんですかね、そういったものはありませんから、当然。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ああいうところにももうちょっと高い木があれば、もうちょっと風をやわらげることはできないんだろうかというふうにも思ったりしたんですけど、そういうことも含めて、風対策についてのいろいろ今考えられて、軽減できるような対策についてのご指導もぜひお願いしたいなというふうに思っているんですけど、いかがでしょうか。","respondent":"浜脇住環境整備課長","answer":"ですから、質問なんかよく来ますけれども、そういった木の、５、６ｍの高木がそういった意味では、そういう歩く方に対して、歩行者に対しては一番風の軽減になるというのが、これは一般的ですので、そういうことについて、一般的といいますか、そういったことでお話をして。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域の方からもちょっとお伺いしたんですけど、かなりこの業者の、ここにも書いていますけど、資料についても、本当にわずかしか持ってこなくて、説明会にも足りなかったりだとか、いろいろと家屋調査をした後も、写真を持ってこなかったりだとか、日影図なんかについても、スリーシーズンを要望したのにもかかわらず、なかなか出さなかったりとか、そういうふうなのがすごくたくさんありまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、やはりひび割れ等々もありますよね。そういうこともきちんと配慮なされていたのかなと。そしてさらに、４月半ばから６月半ばまで約２カ月間、説明会等々がなされていないと。ここはどうなんでしょう。住民のほうで要望しなかったのか、業者のほうが断ってきたのか、その辺ちょっとお聞かせください。もし情報がありましたら。","respondent":"浜脇住環境整備課長","answer":"承知していませんけれども、やはり解体の工事が当分の間多かったんじゃなかろうかなとも思われますけど。どうして、開かなかったのか、どちらのせいかというのは承知してございません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"その辺もありますね。近隣の皆さんも、実際、本来なら説明会をどんどん請求してやってもらうということもどうだったのかなと。そういうところも、建築基準法はあるんですけど、都とか国に要望して、住民の皆さんが１階でも２階でも低くなれば納得するという状況がもしあるならば、建築基準法も弾力的に運用させてくれという、そういう要望が大事じゃないかなと思うんですね。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"三上委員","kind":"確認","question":"ちょっと先に伺いたいんですが、２ページの２にある、風害等の問題についても、「セコムでは３００から４００棟建てたがいまだ風害は１軒も無いと回答書で豪語しております」とかという、こういった回答書が出されたということについての確認は、課長のほうではされているんですか。それからまた、次のページのほうの計画地の風評価の「シミュレーションを行いました。","respondent":"浜脇住環境整備課長","answer":"よくここからシミュレーションをやったようですけれども、シミュレーションをやる場合には、３０ｍ前後、いわゆる超高層と言われているものについては、そのシミュレーションをやったときには風の変更といいますか、変わった部分がよく出てくる。","voiceIndex":34,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"最初のほうの、一般的に風害はないという言い方であるわけだけれども、その回答書なるものというのは、課長の手元にはちゃんと届いているんですか。","respondent":"浜脇住環境整備課長","answer":"届いてございません。","voiceIndex":36,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"ということは、なぜ、それは説明会できちんと話された話なんでしょう。となれば、その説明会でこういうものが話をされた。提供された資料がこうありますという、そういったものが課長のほうにも報告される義務というのはないんですか、この紛争予防条例的ないろいろな流れの中で。","respondent":"浜脇住環境整備課長","answer":"議事録についてはいただきましたけれども、出した資料については、先ほど出された図面がありますね。あれとシミュレーションのやったという、ちょっと色がついた資料、あれはいただきました。それ以外は私はいただいておりません。","voiceIndex":38,"id":"exchange-017"},{"speaker":"三上委員","kind":"確認","question":"そこのところで、お互いが出されたものを照合し合うことによって、どういう話し合いがされたのか当然確認できる。ですから、そういったことについては、じゃ、住民側の皆さんと話し合ったという段階だと、住民の皆さんの代表、一人でも、代表でもいいですから、皆さん方がそういったテープをとるなりとか、それをある意味ではちゃんと文字にした、そういう記録したものを提出してください。どうですか。","respondent":"浜脇住環境整備課長","answer":"その辺も、やはり良好な関係をつくるというのが目的ですから、そういった意味では、そういうふうに話し合ったこと、あるいは約束したこと、できる、できないことについて、書類にしていただいたほうが、こういう場合、私ども自身。","voiceIndex":42,"id":"exchange-018"},{"speaker":"三上委員","kind":"確認","question":"品川区は緩やかだ。住民の皆さんたちのそういった困っている様子も、きょうは見てきていますから、これはわかったつもりでいますけれども、だからといって、建物が建てちゃならないということではないでしょうから、そこのところについての、どういうふうに調整し合っていくのかということについて、そういう場も今後大事になってくるんじゃないかということなんで、申し述べておきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところをチェックしたいというふうな声も、住民の方からすればあると思いますので、そういうところでは、建てるのは業者ですから、業者の責任として区に提出したものは住民にもあげるというふうなところで、前にもそういうふうに言っていただいたこともありましたけど、ぜひご指導をお願いしたいなというふうに思うんですけれども、いかがでしょうか。","respondent":"浜脇住環境整備課長","answer":"だって、話し合いというか、説明をしたんだから、そこは人間同士やるわけですから、当然、そういう要望があったらば、品川区を経由するんじゃなくて、まずは業者のほうに、たまにはそういう人がいるんですけれども、そういったときにはそういうことじゃなくて。","voiceIndex":45,"id":"exchange-020"},{"speaker":"高星委員","kind":"質問","question":"なぜかというと、今はハイグレードのワンルームマンションだというような形が多くなってきているというふうに。品川区内でほかのところでも散見される。その状況をつかんでいるかどうかちょっと教えてもらいたい。これは新たにワンルームの規制にかかる荒手な逃げ腰じゃないかなというふうに私は見ていたんだけれども、ちょっと教えてください。","respondent":"浜脇住環境整備課長","answer":"それにあわせて何か考える時期が来るのかな、検討する時期が来るのかなとは思っております。以上です。","voiceIndex":47,"id":"exchange-021"},{"speaker":"高星委員","kind":"意見","question":"今、状況を把握されているようですけれども、ただ、ワンルームの場合、どうしてもワンルームでありまして、これは小さな学生さん相手のワンルームと、今言ったような３０、４０、５０m2もあるワンルームということになると、住む人も当然違ってくる。定住する可能性がある。住民登録してあるかというとしていない。したがって、地元の民生委員の人が困っちゃう。最後は意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私は、この請願が、請願者が１,１００名を超えるという、こんなたくさんの署名を添えての請願ですし、この内容を読んでも、地域の方々がどれほど切実な思いかということを考えれば、今回は趣旨採択をして、趣旨採択をすることがこの事業者が誠実に対応するというふうな力になっていくんじゃないかというふうに思いますので、ぜひ趣旨採択をしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-023"},{"speaker":"高星委員","kind":"意見","question":"僕はそんなに格好をつけられないので、一人趣旨採択だと言ったって、そんなこと決められるわけないわけで、継続としてお願いしたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-024"},{"speaker":"須貝委員","kind":"意見","question":"無所属の会としては、今、一生懸命代表者の方も話し合っています。そしてまた業者のほうにも、もっとこれから区のほうも指導していただけると思いますので、よりよい方向を願いまして、今回は継続ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-025"}]},{"id":"topic-02","title":"の山本橋拡幅整備工事","agenda":"の山本橋拡幅整備工事","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"１点だけお願いいたします。ここにはちょっと記載されていないんですけど、本件の整備工事は随意契約になっているんですけど、金額的にも３億円以上ということなんですけど、その辺ちょっと理由をお聞かせください。","respondent":"上野都市開発課長","answer":"それから２点目に、都市再生機構の前身です都市基盤整備公団時代から、この大崎、五反田地区におきまして、区との協力関係がございまして、都市再生総合整備事業に関します基本計画も含めまして、いろいろなノウハウを持っているというようなこと。","voiceIndex":63,"id":"exchange-026"},{"speaker":"高星委員","kind":"質問","question":"山本橋の整備費の中で、開発事業者の負担というものはどのようになっているのか、教えてください。","respondent":"上野都市開発課長","answer":"実際の入ってくる時期につきましては、１７年度末ぐらいになろうかと思いますけれども、それまでは一般財源でとりあえず区が立替払いということで実施する予定です。","voiceIndex":65,"id":"exchange-027"},{"speaker":"高星委員","kind":"意見","question":"どうしても１年半の工期があるんだけれども、かつて平成元年の五反田地域が水浸しになったときに、これはちょうどＪＲのガードのがけから、あるいは東急の橋桁工事と重なってしまって、あのときにはＪＲの橋桁かけかえ工事の上と下では、水位が１ｍも違っていたという話も聞かれるわけです。","respondent":"上野都市開発課長","answer":"山本橋の工事の実施に当たりましても、もしそういうような天候の気象状況に応じて、非常に危険な状態が想定される場合には、同様な対応をしたいと考えていますけれども、今のところ、長い期間ですので、工事の状況とか見極めてそういう状況がもし生じた場合には。","voiceIndex":67,"id":"exchange-028"},{"speaker":"高星委員","kind":"意見","question":"御成橋のときは緊急な処置を施したという話だったんですが、今ヒートアイランドでいつどうなるかわからない状況、十分に注意してほしいと思います。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-029"},{"speaker":"木下副委員長","kind":"確認","question":"さっき富士ロイヤルという話が出たんですけれども、これを見ていますと、五反田ボウリング場のほうなんですね。その確認と、橋の真ん中が楕円形になって中が膨らんでいますよね。何か理由があるのかなと、途中なんかベンチか何か置いて休憩するようなものをつくるのかどうなのか、何でこういう形なのかなとふと思ったものですから、ちょっとお聞かせ願えればと思います。","respondent":"上野都市開発課長","answer":"しかし、東五反田二丁目の第２地区と接してございまして、ちょうど東五反田二丁目第２地区と富士ロイヤルのところの河川沿いのところで、両方あわせた一体的な河川の親水護岸の整備を想定しているところでございまして、そういう意味からも。","voiceIndex":70,"id":"exchange-030"},{"speaker":"大沢委員","kind":"質問・要望","question":"開発にあわせて調和をもってというところで、大崎、五反田地区に交通の円滑化を図るということで、拡幅整備が行われるということですけれども、本当に基本的なことかもしれませんけれども、現況７ｍを１６から約２２ｍに拡幅するということなんですけれども、この１６ｍから２２．８ｍという、なぜその数字が出てきたのか、教えていただきたいんです。根拠ですね。","respondent":"上野都市開発課長","answer":"それとあと既存の構造物、橋桁との位置関係からして、最低の今１６ｍというのが決まってございまして、全体の計画から来た幅員２２ｍ、道路上の幅員２２ｍということと、現状の橋桁が大体１８から１９ｍぐらいありますけれども。","voiceIndex":72,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3798#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":39360,"voices":88}},{"id":"h16-20040928-9","meetingId":"h16-cm09","date":"2004年9月28日","dateIso":"2004-09-28","committee":"文教委員会","time":"午前１０時０３分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"小中一貫教育カリキュラム等","agenda":"小中一貫教育カリキュラム等","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"たくさんあるので、一つずつ聞いていくと１人で質問がそれぞれかかるんで、全体的なところからいくと、説明の中の一番最後の「小中一貫教育ＮＥＷＳ」の一番裏にいろいろＱ＆Ａがあるわけですけれども、一番大きいのは、やっぱり教師をどう配置するかということだろうと思うんですよ。その辺は、今、検討しているんじゃなくて、区としてはどういう状況にあるのかというのを、ちょっと説明ください。","respondent":"中島指導課長","answer":"ご指摘のように、私どもがこうやりたい、ああやりたいと考えていましても、都のほうで、それは品川区だけするわけにはいきませんという形になってしまっては、私どものやり方はできないという形になりますので、現在、都が考えているやり方の中で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょうどあれが進んできて、小中一貫校が開校するころには、今、研究している段階が、正式に実践として使えるかどうかというところに来ると思うんです。今、説明のあちこちに、先ほども出たヒマワリの絵だとか、そういうところで成り立っているのかなと思うんですけれども、このカリキュラム全体を通して、系の学習というものに対しては、どういうふうに考えているんですか。","respondent":"中島指導課長","answer":"系の学習に取り組んでいただいている冨士見台中学校、伊藤小学校、上神明小学校、特に小中連携にずっと取り組んでいただいてきておりますので、私どものカリキュラム検討委員会には、それぞれの学校からも多くのスタッフに入っていただいております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"逆に言うと、いきなり細部に決められるかどうかという問題もあるだろうし、その辺、区としては、あれに取り組んでいる姿勢が、同時進行でいかなきゃいけないのか、小中一貫教育というところに生かしていくという気持ちがはっきり出ているのか。その辺、もう１回、説明してくれますか。","respondent":"中島指導課長","answer":"先ほどご説明いたしましたが、ベースラインとしてはカリキュラム検討会の中で、さまざまなノウハウを出していただいております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"確認","question":"一人だけ長くなると、みんないろいろ確認したいことがあるので、一つだけ聞かせてください。神奈川県なんかは、英語をもう５年ぐらい前からやっているんだけれども、話す表現というか、コミュニケーションということを言われている。その数とか、４・３・２の中で、どういうとらえ方をしていくのか。ちょっと細かい話になって申しわけないけれども、よろしくお願いします。","respondent":"中島指導課長","answer":"特に１年生から４年生までの段階では、英語のシャワーを生活の中のさまざまな場面でというようなキーワードを掲げまして、ヒアリングというものを非常に重視した取り組みでカリキュラムをつくっているという状況があります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"最後にします。一例を挙げると、この間、あるお通夜で、かなりのお客さんがいて、６列ぐらいでだあっと並んだ。カリキュラムの中で、親も一緒に教室に来てもらってするというようなことを入れていってほしいなと。今、ここで、イエス、ノーが出る話じゃないんだけれども、社会性を身につけるという点では、家庭の教育力が非常に大事なことだと思うんで、お願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"これまで長く受けられてきた科目に対して、一自治体はどこまでかかわれるものなのか。だからこそ、子どもの教育にかかわることですから、たくさんの意見や議論をきちんと保証させないといけないんだなと。やっぱり問題だなと思って、初めに意見だけ述べさせていただいて、全部の科目については時間がないので、社会科と市民科について、少し質問したいんです。説明をしていただければと思います。","respondent":"中島指導課長","answer":"検討している、または作成している系列表の部分しか表示がなくて、大変申しわけないところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"５、６、７年生では、日本国民としてよくしていこうとする人間像、８年生、９年生になると、世界の中の日本人としてと。これは教科ですから、目標だって、当然評価があるわけですけれども、模範的な日本国民、また世界の中の日本人像、これはどういう。今の子どもをどういう大人にしていくことを目標に掲げているのか。ここをちょっと教えていただきたいと思います。","respondent":"中島指導課長","answer":"これは、教科のねらい、また評価の部分とは若干違ってくるところではないかなとは考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"じゃあ、どんな人を育成するのか。日本人とか何かとか、国家が固定した人間像を育てるのではなくて、個人の尊厳を重んじ、真理と平和を求める人間の育成、教育の目的も、人格の育成、人間をつくる教育なんだと、こうしているんですけれども、ここでは、固定化された日本国民や日本人。これはどういうことなのか、そこをはっきり説明していただければ。","respondent":"若月教育長","answer":"ここは全部、前に説明したので読んでいただきたい。科学的事実判断による合理的意思決定に基づく行動できるような教科なんですよ。意思決定に基づくんですよ。その人が意思決定をできるようにするんですよ。","voiceIndex":18,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"今、教育長がご説明されましたけれども、今の教育法や憲法の中に、日本人とか、日本国民とかでなくて、人間とか、人とか、子どもとか、人権とか、なぜ規定されているかというと、きちんと過去の犯罪に立った上で、今、規定されているわけですよ。ぜひ、教育長が話したがっているので、一言伺って、次に市民科の質問をしたいので、ご意見がございましたら、聞かせてください。","respondent":"中島指導課長","answer":"これは、我が国の日本の国土と歴史に対する理解を深めるわけです。そして、その中で、国際社会に生きる民主的、平和的な国家社会の形成者として必要な公民的資質を養う、これがグローバルな公民性というところで、世界の中の日本人として、私たちが考える視点になります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"市民科のところなんですけれども、４ページの５領域と１５能力で、市民科のねらいと育てたい力となっているわけですけれども、先ほどの説明では、時間の関係もありましたけれども、文化創造の最後の自己修養とある。聞き慣れない言葉なので、よくわからないけれども、自己修養というのは、２、３、４年生、どういう学習内容になるんですか。詳しく説明していただければと思います。","respondent":"中島指導課長","answer":"４ページにあります市民科のねらいと育てたい力、５領域の中の文化創造の自己修養のところです。必須項目とそれ以外の部分ですけれども、必須項目というのは、この内容については、どの学校でも必ず取り上げていただく内容である。","voiceIndex":22,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"少し具体的になるんですけれども、教員の方に伺ったんですけれども、自己修養の中で、３、４年生で仁・義をやると。これが入ってきた理由と、それぞれどんな授業をやるのか。仁・義・忠・孝・礼・智・信、３年生から９年生までやるんですけれども、それぞれどんな学習なのか、その目的は何なのか、どんなことを学ばせるのか、子どもたちに何を教えるのか、説明していただきたいと思います。","respondent":"中島指導課長","answer":"このそれぞれの内容につきましては、今、こちらの学習項目として、そういう一つのジャンルの呼び方をしています。実際には、例えば仁というのは、これは説明になるかもしれませんが、人を慈しむ心、それを育ていくわけでございまして、義というのは、ものごとの理の部分です。","voiceIndex":24,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"３年生で、仁と義という漢字を習うんですかね。それとも、今までの学活というのは、科目というのかちょっとわからないけれども、通信簿には載らないですけれども、国語、算数、理科、社会とはまた別の単元と言ったらいいのか、その辺の専門的な言葉はわからないですけれども、つまり、市民科になったことによって、ほかの算数とかと同列の教科になったのか、そこをちょっと教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"教科なのか何なのか、その辺の関係が、市民科自体が全国初ですから、よくわからないんですけれども、評価するというのは、どう評価するのかイメージがつかないんです。初めてのことですからあれですけれども、抽象論になっちゃうとよくわからないので、現段階で、もう少し詳しく教えてください。要は、通信簿には載らないわけですよね。その辺のことだけ、ちょっと詳しく教えてください。","respondent":"中島指導課長","answer":"ちょっと専門的な話になって恐縮ですが、そういったような評価の仕方で子どもたちの学びとか、活動を振り返るような方法も、この中では検討されているところです。","voiceIndex":29,"id":"exchange-013"},{"speaker":"大西委員","kind":"質問・要望","question":"国語の部分では、文化審議会答申で、小学校６年生までに、常用漢字の大体が読めるようにということなんですけれども、読めるということと、書くということの定義、この辺はどうなのか。児童課だったか、よく私も耳にするんですけれども、家庭でやるべきことを行っていなくて、それを学校に求める傾向が非常に強い。先ほど、林（宏）委員が言われた、子どもとともに、親の教育というんですか。","respondent":"中島指導課長","answer":"子どもの読みと書きというのは相まって伸びていく部分もございまして、小中一貫校のカリキュラムでは、先ほど申し上げましたように、お手元の資料にあるような形で、子どもたちの語彙を増やしていく中で、物語文の読解に当たらせる。","voiceIndex":31,"id":"exchange-014"},{"speaker":"大西委員","kind":"質問","question":"漢字と英語については、私が考えるには、子どもたちがどのぐらいのレベルにいっているかというのを検証していくためには、例えば、漢字検定であるとか、英語であれば英検であるとか、ＴＯＥＩＣであるとか、こういうものを取り入れていって、子どもたちのやる気と、子どもたちの、その当時に備わっていっている学力というものを検証する手段。","respondent":"中島指導課長","answer":"漢字と英語のレベルの確認ですけれども、漢字につきましては、例えば漢字検定の準２級ですとか、３級程度、これがおおよそ小中学校で学習する常用漢字の大体を理解するぐらいのレベルかなと思うんですけれども。","voiceIndex":33,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"例えば、今、小学校１年生から英語の勉強をやるとか、漢字の１,９４５字を、中学校３年生から中学校１年生に戻すとか、すごい前倒しで勉強をしていって、空いたところに、今度は異学年の高等学校のものを、８、９年生は持ってこようなんて言っているんですけれども、公立学校ですよね。そこら辺は、どう検討されているんですか。","respondent":"中島指導課長","answer":"８、９年生で高等学校の内容をも視野に入れてという部分ですけれども、８、９年生が、すべて高等学校の内容を取り入れたカリキュラムで実施をするというわけではございません。","voiceIndex":35,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"きのうの新聞の切り抜きによると、小学校から英語を教育したほうがいいというのは、国民の８割になっていると言いますから、是非はいろいろあったにしても、多数の意見だということは認めますけれどもね。障害児だけを言っているわけじゃないですよ。それから、品川区として、今、子どもで学校の授業についていける子、いけない子、どのぐらいいると踏んで、こういうカリキュラムをつくっているんでしょうか。","respondent":"中島指導課長","answer":"不登校の子どもたち、それからＡＤＨＤ、ＬＤではないかと考えられる子どもたちへの対応という部分になろうかと思うんですけれども、実際に、現行のカリキュラムを実践していく中で、例えば不登校の子どもたちにどういうふうに対応していこうかとか。","voiceIndex":37,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"今、数字が、授業がわからないと子どもたち、それは取っていないからわからないと言うけれども、文部科学省でこういう調査を発表しているわけですから、そういうのを踏まえて、どういうふうにやったらいいのかということを子細に検討しなきゃ、子どもを実験台にすることになりはしないかと思えてなりません。できる子じゃないですよね。果たして可能なのかどうなのかと、もう一度、お答え願いたい。","respondent":"若月教育長","answer":"ですから、先ほどもちょっと指導課長の説明がありましたけれども、さっき何の例でしたか、具体的な例を言いましたね、６年生でこういう勉強をして、やがてそれを今度、中学校に行ってもう１回やるから、そこでさらに学力を強化していくんだという説明がありました。","voiceIndex":39,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"どっちみち午後にまたがるんですけれども、もう少し進めちゃっていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問・要望","question":"現在の学習指導要領ができるときに、あまり学ぶボリュームが多すぎるというんで、文部科学省が３割削減をしたと言われていますよね。それは二、三年前ですよね。一つひとつ積み上げながら評価をし、それを取り入れるという科学的な検討と進め方こそ、教育分野で求められるんじゃないかと。現在の学習指導要領を３割削った。習熟度別学習は、現在と小中一貫教育の中では、どう変化するんでしょうか。","respondent":"若月教育長、中島指導課長","answer":"前半の部分だけ、ちょっとお答えします。これがもしうまくいかなかったら、一体だれが責任を取るんだということを、今おっしゃいました。今の学校のこの状態は、だれが責任を取るんですか。小中一貫教育というのは、その前進としてプラン２１の中でも、小中連携教育として実施をしてきているという経緯があります。小学校と中学校の連携といった部分は、もうその前からの大きな課題になってきているところです。","voiceIndex":43,"id":"exchange-020"},{"speaker":"沢田委員","kind":"意見","question":"だれが責任取るんだ、今の現状を、だれが責任取るんだと。そういう指摘をよそにどんどんつくって、具体的な検討もしていないというのは、私は、さっき言った、小中一貫校から小中一貫教育に移る過程でも、無計画性だと、失敗したら衆知を集めてなんて、子どもの学ぶ場というのは一生に１回しかないんですよ。世界の教育学の到達点を、真摯に研究すべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいところがありますので、お願いしたいと思います。そこら辺、ベースは同じであって、具体的にどこが変わっていくのかというのがどこら辺にあるのか、まず教えていただきたいと思います。","respondent":"中島指導課長","answer":"こういったような形で、従来の指導方法をベースラインで見直していくということを考えている教科もあります。","voiceIndex":52,"id":"exchange-022"},{"speaker":"西本委員","kind":"意見","question":"その辺は、今後どういうふうにされていくのか。来年度、再来年度ということで、小中一貫教育を進めていく中では、当然ながら、新しい先生方も入って来られる、新任の先生も入って来られるというところで、その指導というのは、どういうふうに考えていかれようとしているのか。","respondent":"中島指導課長","answer":"来年度意向につきましては、他区都市から転入した教員を対象とする研修会を実施していますので、その中で、まずは小中一貫教育の内容理解を図る項目を重点的に実施していきたいと考えております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、品川区としては、あの先生に来てほしいという場合もあろうかと思うんですけれども、そこら辺の、これから、人事権も含めて、品川区の教育のＰＲというのかどうかわかりませんけれども、その辺はどういうふうに図られていくのか。","respondent":"中島指導課長","answer":"ただ、委員のおっしゃるように、意欲のある教員には、ぜひ品川区の小中一貫にかかわっていただきたいという思いが強くありますので、そういったような情報収集の方法につきまして、今後、検討してまいりたいと考えています。","voiceIndex":56,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"小中一貫校は、今までの教育を反省しつつ、子どもたちのためにいろいろ試みましょうというところもあると思うんですが、それは、やっぱり今の子どもたちに成果があってほしいと思いますので、ぜひとも、いろいろ検討をされた現場の先生方が一生懸命やっておられると思いますので、それをなるべく広げていただきたい。いいお子さんが品川区に大勢いますことを希望したいと思います。","respondent":"中島指導課長","answer":"大井地区のほうは、１学期の中で、それぞれ小中一貫教育の内容についての課題をカリキュラム検討委員会に教員を派遣することで集約し、それを学校がそれぞれ全体の課題として集める中で、２学期に向けて、どういう協力での研究体制をとるかという検討をしてまいりました。","voiceIndex":58,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"要するに、評価をするときに、やはり子どもがどうであったのかということが一番大切なことであって、それよりも、今の子どもたちに、基礎学力というのは絶対につけてほしいと、私は個人的にも思っています。ですから、そこは基礎にのっとった形で、長い年月変わろうと何しようと、これは大切な部分ですので、これからまさにパソコンとかをされますと漢字を忘れてしまうんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-026"},{"speaker":"藤田委員","kind":"質問・要望","question":"私からは、２点お伺いしたいんです。この市民科というのは、どういう資格を持った人が担当するのか。担任の先生がするのか、その辺をちょっと教えていただきたい。ですから、いい、悪いはともかくとして、やっぱり子どもたちにとって、イントネーションがどんどん変わっていくということは、ある程度知らせていく必要があるんじゃないかと。","respondent":"中島指導課長","answer":"市民科のほうですけれども、基本的には、学級担任がこれの指導に当たるというスタンスを持ってあります。ただ、学年合同で実施をする場合、あるいは、５、６、７年生とか、学年の枠を超えて実施する場合も、マネジメントすることがあろうかと思います。","voiceIndex":61,"id":"exchange-027"},{"speaker":"藤田委員","kind":"質問","question":"特別活動というのはどういう活動なのか、ちょっと教えてください。","respondent":"中島指導課長","answer":"さまざまな活動があります。例えば、地域行事について学んでいく場面が、文化創造領域の中にあるんですが、その中では、品川百景に取り組んでみるとか、そういったようなテーマも、ひとつ今、カリキュラム検討委員会の中で考えております。","voiceIndex":63,"id":"exchange-028"},{"speaker":"藤田委員","kind":"質問・要望","question":"市民科については、区独自の取り組みですので、何年先か、やっぱり成果が出るような幅広い取り組みを、ぜひしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-029"}]},{"id":"topic-02","title":"品川歴史館特別展「むさしの国 荏原」","agenda":"品川歴史館特別展「むさしの国 荏原」","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"今、ＰＲに電車のつり広告をされるということでしたが、何線なのかということ。もう一つ、雅楽の演奏会はどこでやるんですか。場所。","respondent":"上川内生涯学習課長","answer":"電車の広告は、東急大井町線。それから、雅楽については書院を利用して、あそこに座っていただいて、雅楽の初歩的な説明と、どういう構造になっているかとか、そういう初心者向けの一定の講義もしていただきながら、演奏していただく。","voiceIndex":71,"id":"exchange-030"},{"speaker":"藤田委員","kind":"質問","question":"どうでもいいような質問なんですが、全国に、荏原という地名がつくところはあるんでしょうか。ですから、荏原という地名は、我々が住んでいるここだけじゃなくて、何かもっと違うのかなと。関係ない話かもわかりませんけれども、もしそういうのがあれば調査をしてもらって、せっかくですから、ちょっと感じたものですから。結構ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"せっかくいろいろやっておられるんですが、近隣の小中学校とかにこういう会がありますよというようなことをしていただくなりして、いわゆる地域に住んでいる子どもたちもわりといらっしゃると思うんですよね。自分たちの住んでいるところにはこういう歴史があるんだというのは非常にいい教材だと思うんですけれども、そこら辺はどういう形なんでしょうか。","respondent":"上川内生涯学習課長","answer":"あわせて、児童生徒のほうに、どのようにここにつなげていったらいいかというのを検討します。","voiceIndex":76,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"それから入館料なんですが、小中学生ですけれども、たしか通常５０円だったと思うんです。なぜかというと、確かに金額はかかっていると思うんですが、わざわざ小中学生が歴史館に行くというのは、そのことを大切にしていきたいなと思うんです。それはそれで意味があるんだと思うんですね。とりあえず、品川区限定でもいいですから、そういう形ができないのかなと思いますが、いかがでしょうか。","respondent":"上川内生涯学習課長","answer":"将来的に、使用料についての区の考え方というのは、またこれからいろいろ変わってくると思いますが、今回はそういう結論にさせていただきました。","voiceIndex":78,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"入館料については、いろいろな考え方がありますの、どれがいいかというのは、ちょっと私も難しい判断があります。よく来てくれたねと、よく品川区の歴史に興味を持ってくれたねというような、逆に、そういう気持ちに、私はなったことはありますので、今後、いろいろな考え方があろうかと思いますので、ぜひ検討課題ということで、継続的に様子を見ていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-034"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、来年４月に台場小学校も入りますし、今挙がっているだけでも、台場小学校、荏原五中、第二延山小学校、あと一貫校が２校、具体的に改築校として挙がっていますけれども、そこから導入するということだから、もう今、検討委員会で決定されているのか。その辺のスケジュール的なところを、詳しく説明していただきたいと思います。","respondent":"谷田部学務課長","answer":"保護者への説明ですけれども、井上議員のほうからの質問では、職員だとか、保護者とか、どのようなところで検討されていたのか、いつごろ区民に意見を聞くのかというような主旨ですので、私どものほうといたしましては、業務内容が、給食の作業行程のうち、調理だとか、食器洗浄。","voiceIndex":84,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"改築校からということは、台場小学校から導入するということでいいのかどうか。今まで、質問すると、改築校と、これはもうわかっているんですけれども、じゃあ具体的にここから始めますと。一般的に改築校からと、これまでずっとそうですけれども、具体的にどこの小学校から、どこの時点からするのか、その検討がどう進んでいるのか、そこをはっきり教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"現時点で申し上げられるところは、今現在、まさしく改築校を中心として、順次導入していきたいということで、現在、検討をしている最中だです。","voiceIndex":86,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"台場小学校から入れるということを検討しているという理解でよろしいでしょうか。いまいち、その辺がよくわからない。","respondent":"谷田部学務課長","answer":"繰り返しの答弁になりますけれども、改築校から順次、給食調理代行を導入するという方向で、現在、検討している最中だということでご理解いただければと思います。","voiceIndex":88,"id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"今は、調理内容というか、給食の内容には変化がないから、説明はしないと言うんだけれども、変化がないならないで、直接つくるのから変化はあるわけですから、給食の変化はないという説明は、改築校なり、導入するところには、早い段階から説明をして、理解を得る努力は、最低限やらないとまずいんじゃないかなと思うんですけれども、いかがでしょうか。","respondent":"谷田部学務課長","answer":"私ども、今後、どういうような形で調理代行を組み立てして、どこの学校から手始めにやってという、まさしく、これから検討をしている最中ということで、今後、予算の問題も出てまいります。","voiceIndex":90,"id":"exchange-038"},{"speaker":"藤田委員","kind":"質問","question":"今、沢田委員から、帳消しになったというのは、ちょっと事実関係だけ、私、お話ししておきたいと思うんです。ですから、区のほうは、やるとか、やらないとか全然なくて、帳消しとか何もないんですよ。ですから、一たん俎上に上げて帳消しになったのではないということだけ、ちょっと、私の記憶の中でお話しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"今月、東京都で、授業力向上に関する検討委員会の報告書が出ています。この間、僕がＯＪＴはあまり役に立たないというか、効果が出ないというようなことを言ったけれども、これでは、ＯＪＴが重要な役割を持っていると位置づけている、変えていくという点で。これについて、次回でいいですから、説明をしていただけますか。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-040"},{"speaker":"林（宏）委員","kind":"意見","question":"ちょっと整理してください。行くところが書いてある、調査事項が書いてあるもので、中央図書館というのは行かなくなったのか。その辺をもう１回、行くのか、行かないのか。行かないけれども、調査項目としては、向こうの関係者から説明を受けるのか。その辺、ちょっと整理してください。高岡市、金沢市、京都というのを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-041"},{"speaker":"林（宏）委員","kind":"質問","question":"金沢市の、小中一貫英語教育特区はどうですか。学校は行かなくて、どこで説明を受けるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問","question":"予定どおりですね。はい、わかりました。調整中のところは、これから決まったら、教えてくれますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問","question":"ここのところしばらく、僕は総務委員会だったんですけれども、事前に質問事項とかを相手方に送って、あらかじめお答えを用意してもらうというか、そうすると、時間がむだにならないというようなことをやってきたんですけれども、文教委員会はどういうふうにやっているのかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-044"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、その質問事項はいつまで出すの。何かないかというのは、そういうものを出してくださいという意味なんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"意見","question":"ただ、どうしても長くなったり、資料の問題なんかがあるから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":66226,"voices":139}},{"id":"h16-20040928-5","meetingId":"h16-cm09","date":"2004年9月28日","dateIso":"2004-09-28","committee":"総務委員会","time":"午前１０時０３分～午後１時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１番の第６９号議案 山本橋拡幅整備工事委託契約","agenda":"１番の第６９号議案 山本橋拡幅整備工事委託契約","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"何点かお話を伺いたいと思います。今お話があったように、平成２年に橋をかけかえたわけです。その辺のところの経緯というか、平成２年にかけかえたのはなぜか、こういう、その当時には大崎をやろうとか、いろいろ考えがまるっきりなかったのか、あったのか、そこら辺の経緯を教えていただきたい。それから今、随意契約のお話がありました。","respondent":"上野都市開発課長","answer":"その後、かけかえの更新計画で道路上の整備、幹線道路２号については１２ｍの整備を予定していますけれども、その両側に５ｍずつ壁面のセットバックをいたしまして、全体で２２ｍの道路空間を整備するという考え方が打ち出されまして。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"だけれども、それから動きが活発化されてきたんだと、平成５年に大崎が活発化されてきたというわけだけれども、そのときに、変な話、道路更新計画もないけれども、将来広がるという予想のもとで計画を橋台だけはつくったよという話で理解をしちゃっていいのか、目黒川の話はわかりましたので、それは多分大綱的にああいうふうにしたんだろうから、それはわかりましたけれども、そのときに。","respondent":"上野都市開発課長","answer":"これが今現況かかっているところです。その両脇に川下側と川上側にそれぞれ今回新設するということでございまして、この全体幅員が現況の７ｍぐらいの幅員からその左側に６０cmほど広げまして、川上側のほうに大体８ｍちょっとぐらい広げる予定です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"何度も質疑であれですけれども、１点だけ教えていただきたいのは、公共団体というのは、ここで言う公共団体というのはどういう意味なのか、公共団体か都市再生機構かとおっしゃったと思うんですが、私の理解が違ったらごめんなさい、ここで言う公共団体というのは、どこのことを指されているのか、具体的にちょっと。","respondent":"上野都市開発課長","answer":"この場合は、品川区を公共団体、あるいは都道府県あるいは区市町村、それを公共団体というふうな意味です。本件については品川区が施行主体です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田委員","kind":"意見","question":"これでやめます。わかりました。いいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと今の確認しておきたいんですけれども、地方公共団体とか、この補助金が支出先が決められているということで、今の答弁は、地方公共団体は、この場合は品川区だということなんですけれども、先ほど何で入札じゃないのかということなんですけれども、都市再生機構のこの補助金を入れるということは、入札でいわゆる民間のところと競争させるということができないということじゃないんですよね。","respondent":"上野都市開発課長","answer":"それからあと、この工事を実施するに当たりましては、設計、積算だけでございませんで、発注業務とか、それから監督業務もございまして、そういったものも含めてできるのは都市再生機構しかございませんので、そういう意味からも含めて。","voiceIndex":14,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"そうなると、この補助金を使えるのは、民間のところでは使えないということではなくて、相手先の都市再生機構がいろいろその仕事をやる上で便がいいということでこっちにしたということですよね。わかりました。ちなみに、ちょっと補助金は今契約金額は３億６,９００万円ですけれども、費用の負担がどういうふうなのかということを教えていただけますか。","respondent":"上野都市開発課長","answer":"このほかにつきましては、地元の東五反田二丁目第２地区、それから五反田ボーリングセンターまで開発を予定していますけれども、そちらのほうの開発事業者において負担するというような協定を今後区との間で結ぶ予定となってございまして。","voiceIndex":16,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、３億６,９００万円のうち、国のほうから１億３,０００万円で、残りは地元の事業者負担ということなんですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"確かにいつになるかわからないものに金をかけるのはけしからんという方も中にはいらっしゃるかもしれないけれども、でも逆にそういう大きな構想みたいなものが、場合によってはアンダーテーブルも含めて行われていくということがきちんとあって、初めてこういうものができてくるんじゃないかなということなんで、特に質問にはなりませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"１点だけちょっとお伺いしますけれども、これまでと同じように、地元開発業者の負担が原則ということがこの事業でも貫かれているということの今ご説明でした。今回は全く関係のない話ではありますけれども、今後の開発の中で、このような国庫補助というのはどう変化していくのか。","respondent":"上野都市開発課長、市岡企画財政課長","answer":"この大崎・東五反田地区につきましては、国土交通省の都市再生総合整備事業という、この公共基盤の整備などを主に行う補助制度がございまして、これを活用してこれまでも事業を行ってきてありますけれども。そういう意味で、今、都市開発課長が申し上げたとおり、国のほうもこれは特に大都市の都市更新という大きな政策課題がありますから、国も現在の段階で、他の公共事業一般のように国庫補助負担金を削減するという対象にはなっていない。","voiceIndex":20,"id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"税が使われるわけですから。都市再生が国家的な事業だから、今の判断としては、引き続き、将来にわたって２分の１なのか、どこまで算定基準がどういうふうになっていくのかわかりませんけれども、そういう考え方を使用されるだろうということ、そういうふうに今理解をしたんですけれども、将来にわたってそういうことですか。","respondent":"上野都市開発課長","answer":"これは、１０年間の時限立法でございまして、その間とにかく集中的、重点的に都市の再生を行うための都市更新の事業につきまして、さまざまな施策を集中的に投入して、それで都市開発などを推進して都市再生を図っていくという考え方ですけれども、この中で。","voiceIndex":23,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"１点基本的なことと、ちょっと工法的なことになるんで、答えができるかどうか、できなかったら結構ですけれども、例えば橋台部分を拡幅しますよね。長さ的には短いものですから、そこへすとんと新たな橋台をつくったときに、今まである橋台との接続部分ですよね。例えば将来橋台を拡幅するのだというときには、建物でも何でも接続できるような形にしておきますよね。","respondent":"上野都市開発課長","answer":"それに当たりましては、今の大体つけ足す部分が３ｍ程度橋台部分ではみ出すことになりますけれども、鉄筋コンクリート造ですから、コンクリートで、あるいは鉄筋で一体的な施工が可能となりますので、そういった面では、既存の構造物とは一体的につくるですので。","voiceIndex":25,"id":"exchange-011"},{"speaker":"松澤委員","kind":"意見","question":"例えば地方へ行って道路なんかを見ますと、片側１車線分が雑草が生い茂っている。そうしますと、この工事は、土井委員の意見とはちょっと違っちゃいますけれども、前回平成２年につくったときに、しっかり橋台をつくって橋をつくって、将来拡幅するんですよという余地を残しておく、そうすれば、橋台の工事はする必要はなかったんじゃないか。","respondent":"上野都市開発課長","answer":"平成２年のかけかえ当時に、将来の全体の道路計画が定まっていて、それに基づいて、幅員などの詳細も定まっていて、それに基づいたかけかえがなされて、将来その１２ｍや１６ｍに幅員が広がることを見越して、それに合った形の橋台がそのときにできていれば。","voiceIndex":27,"id":"exchange-012"},{"speaker":"堺副委員長","kind":"質問・要望","question":"ちょっと、確認の意味で、お金の流れ、仕組みというんですか、そういった部分を含めまして、忘れている点もありますので教えていただきたいんですけれども、まず一つは、先ほどのご説明の中で、今回契約が約３億７,０００万円ですが、国庫補助の対象は２億６,０００万円のうち半分で１億３,０００万円。それが一つですね。","respondent":"上野都市開発課長","answer":"その中では、まだ詳細は今後ですけれども、基本的には平成１７年度末以降に地元の東五反田二丁目第２地区の市街地再開発事業の権利変換計画というものがつくられる予定になってございまして、それに合わせて支払いが大体なされるようなことを考えてあります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"堺副委員長","kind":"質問","question":"だけれども、今、実際に協定は結ばれていない中で、もう明らかにこの段階では地元が２億４,０００万円負担しないといけないという金額がもう出ているわけですから、契約を結ばない状態にしても、やはりそれなりの地元の方々には口頭の説明になるかどうかわかりませんが、やはり今の説明だとまだしていない、これから協定を結ぶ段階でそういう具体的な話をすることに聞こえたんですが、地元でわかりましたと。","respondent":"市岡企画財政課長","answer":"そういう意味で言えば、先ほど都市開発課長が申し上げましたとおり、タイムラグがいろいろケースによって生じますので、一時区のほうで立替るようなこともあり得るかもしれませんが、最終的には区の一般財源負担がないように。","voiceIndex":32,"id":"exchange-014"},{"speaker":"堺副委員長","kind":"質問","question":"先ほども大崎の東西自由通路のときとちょっとこれと違うような、ですから、仮の合意という表現を使っておりましたけれども、今、まだきちっとなっていない段階なのに、これだけだという金額がもう既に出ちゃっていますから、その辺で申し上げているわけでございまして、心配することはないんだですから、余計なことかもしれませんが。","respondent":"上野都市開発課長","answer":"これは、何年度にどのぐらいの額、どの箇所について必要かといったものを位置づけるわけですけれども、この位置づけるに当たっては、区としてはその地元準備組合あるいは開発事業者と事前の協議段階ですけれども、その中で入念な打ち合わせを行いまして、協議を行いまして。","voiceIndex":34,"id":"exchange-015"}]},{"id":"topic-02","title":"の第６４号議案、平成１６年度品川区一般会計補正予算","agenda":"の第６４号議案、平成１６年度品川区一般会計補正予算","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"社会福祉基金積立金というところをお聞きしたいんですが、私がわからないのでちょっと教えていただきたいんですが、佐藤ユキ子障害者用福祉基金なんですけれども、基金というのは個人の名前がよくついたりする部分と、あともう一つは、例えば障害者サービス用の備品を買いましたという形があると思うんですけれども、基金とこういう寄附という、ここら辺の基準というのはあると思うんですけれども。","respondent":"市岡企画財政課長","answer":"これは平成１６年度の予算を組むときに予算編成期に、まだ決算は先のことですけれども、平成１５年度の執行状況を見ながら２０億程度はあらかじめ繰越金が平成１５年度決算から出てくるだろうと、こういうふうに考えて組んでいたものですが、実際に決算をやってみると。","voiceIndex":43,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"内容的には今わかったんですけれども、何か個人名をこのように、例えば今の話だと、いろいろ話を伺っても、ほかの部分で例えば５万円でも１０万円でもいただいたら、その人が個人名を出したいと言えば出すのかという、何かそういう基準とか、何か個人名がうたわれているので、そういう何か基準というか、目安というか、何かあるのかなとちょっと思っている部分があるので。","respondent":"市岡企画財政課長","answer":"これはいろいろ経過がありまして、実は単位で言いますと１億円を超えるような寄附をされたような方がいらしたときに、何とかその方を顕彰するというか、できないかというふうなことを考えたときに、１０月１日、迫っていますけれども、区民表彰という形もありますけれども。","voiceIndex":45,"id":"exchange-017"},{"speaker":"石田委員","kind":"意見","question":"繰越金の部分なんですけれども、これは物事の考え方なんですが、これはある程度利益というか、黒字が見込めるよということでもちろんやられている。この２０億円が黒字が出るのかどうかという話で、２５億円という今期は今もやられているけれども、それであるならば、当初にその部分の黒字部分が見込めるんならば、当初からほかの事業に例えば充てる。感覚的に思うんだけれども。","respondent":"市岡企画財政課長","answer":"ちょっと私の説明があまりよくなかったと思うんですが、２０億円については歳入歳出予算ですので、一般財源という意味で、どこかに色をつけているわけではありませんが。","voiceIndex":47,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"細かいことなんですけれども、この１５ページの、子育て総合支援総合推進モデル事業なんですけれども、これは先ほど国のほうで指定してきたというお話なんですけれども、中身では、計画の策定とかそういうふうにやっていらっしゃるけれども、事例集も作成しているわけですが、中身というか、計画を策定して、こういうことをやりますというようになったら、今度は財源はどうなるのかなと。","respondent":"榎本行財政改革担当課長","answer":"この子育て支援総合推進モデルの実施計画というのは、実は次世代育成の行動計画の計画と重ねてもよいということで国のほうから通知がございまして、次世代育成支援対策推進行動計画を来年４月から実施予定で今協議会のほうでつくろうとしているところなんですけれども。","voiceIndex":49,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかりました。もう一つはちょっと細かいんですが、１７ページのにぎわい創出事業のところなんですが、にぎわい創出事業の青物横丁商店街のところのガソリンスタンドの跡地を活用してにぎわい創出をやるということなんですけれども、差し支えなかったら、ちょっとここに至る経過というのがどのようなものかわかったら教えていただきたいと思います。","respondent":"市岡企画財政課長","answer":"それで、そのもう一方で、なかなか土地を買って活性化の拠点をつくるというのは、これは大事業ですので、財源の問題もいろいろありましたので、地元のほうからは。","voiceIndex":51,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"かなり地元のほうも積極的に動いていたということなんですけれども、なかなか商店街のところが、中には店舗がいなくなって厳しくなってきている、いろいろあるんですけれども、なかなかそういうところは自分たちで、今ここの例だとお金の不足しているところを自分たちで負担してということできたようなんですけれども、なかなかそういう力もないというところもあるんですけれども。","respondent":"市岡企画財政課長","answer":"商店街は現在いろいろな課題を抱えていて、それぞれの商店街なりにもちろん自助努力もされておりまして、このケースというのはその一つの形で、幸いにも中長期的な視点から東品川四丁目のときの開発以来。","voiceIndex":53,"id":"exchange-021"},{"speaker":"本田委員","kind":"質問・要望","question":"それで、先ほどそういうお話もちょっとありましたけれども、最終補正で今度ばっと大きなものが出てくるということではなくて、当初予算の組み方がある意味ではかなり正確に組んでいく、よほど突発的な増収なり何らかのあれがない限り、こういう形の補正になっていくのかなというふうに、これを見まして感じたんですけれども、都市部、品川区のまちにおける今日の経済情勢や何かの中でも。","respondent":"市岡企画財政課長","answer":"それで、私どもはこの時期、補正予算に消極的だったわけではございませんで、必要な緊急に対応すべき施策があれば、あるいは必要があれば、これはそれこそ基金等の財源を使ってでも、これは金額だけではありませんけれども、必要な補正はやっていくという姿勢ではおります。","voiceIndex":55,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1666#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":30636,"voices":66}},{"id":"h16-20040929-11","meetingId":"h16-cm09","date":"2004年9月29日","dateIso":"2004-09-29","committee":"自治制度特別委員会","time":"午前１０時１２分～午後０時０７分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"今議長のお話の中で、「議長の本意ではありません」という中で、当委員会が、知事だの、都議会へ行きましょうというのは、議長から示唆されてやったことじゃないんでね、そこは、議長の本意でないとかという表現をすること自体は、ちょっと委員会に対して、議長会が要望書を出すのは別のものじゃないよということぐらいわかるんだけど、我々が、議長会が動いていない。","respondent":"松澤議長","answer":"その件については、今須藤委員がおっしゃったとおりだというふうに思います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高星委員","kind":"意見","question":"どこからどう切り口を切り出していいかわからないけれども、私はこの委員会の中で何度も、本来、２３区の議長会の議長たるものはほとんど自民党の中から出ているんですよ。これは既成の事実なわけだ。そこの中で、ここにきて、委員会が調べた中で、どうも単純に議長の職務、あるいは委員長の職務だけの問題でクリアできないような課題を感じてしょうがないんだよ。そのように、委員長、何か思いませんか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"石田委員長","kind":"質問","question":"自民党の内部のという話は別としましても、この委員会の中で委員長として、非常に議長との連携等、また皆さんからご意見をいただいた中で前回の委員会があったわけでありまして、その中で、今日、今議長からご報告があった中で、これからまた区長がおいでになってお話を伺った後、皆様に、この前の委員会でのこと、それ以外に今後のこともお諮りをしていかなくてはならないと思いますが、前回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"高星委員","kind":"質問・要望","question":"それぞれ、本当にありがとうございました。なぜかというと、ちょっと混乱していたからですね。違うなんて言う人だれもいないよ、そんなこと言ったって。だから、そういうことがあるんで、委員会の委員長というものは丁寧にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう中から、品川の区議会として、過去のいろいろな運動の実績も踏まえまして、タイミングよく議会の、いわゆる区民の意思を提示して、議会として積極的にわかろうというところからいろいろな問題提起が出てくるわけで、議長会の情報を含め、できるだけ正確な情報を当委員会にそれぞれご提供をいただいて、真摯に検討して、そういう形で自治権拡充。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"},{"speaker":"藤田委員","kind":"質問","question":"そのときに、渋谷の議長が今議長会の幹事をされているというので、今度幹事会があるから、今要するに、うちの議長としては、共通の認識をもっと深めるべきだという発言があって、わかりましたというので、渋谷区の議長が、議長会で本音を話しますということで、この９月２１日、これは世田谷の三軒茶屋にありますキャロットタワーですか、ここで城南５区の正副議長が議長協議会をやりまして。","respondent":"石田委員長","answer":"ありがとうございました。藤田委員は副議長という立場もありまして、ご一緒に参加をいただいている部分もあり、そこのの部分も今ご説明をいただいたのかなと。","voiceIndex":11,"id":"exchange-006"},{"speaker":"高星委員","kind":"質問","question":"だから、話を一通り聞いていれば、どうも、これ、当委員会だけの感覚じゃないけれども、私の感覚で言うと、いろんな意見の、自民党の会派の中でもう少し意見調整を図ったほうがいいんじゃないかと、あるいは委員長の職務において、各方面に、必要な情報をもっと的確にとらえてもらったほうがいいんじゃないかなというふうに思ったものですから、ちょっと話をさせてもらったんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"ですから、その５７％という数字をある程度のベースにして考えられているのか、そういうものをまるっきりなくして全体を見直しましょうという、もっと極端に言うと、その５２％というのが５１％になっちゃう可能性もまるっきり、東京都が出てくる可能性もあるかなというふうに思うんだけども、そういうことをまるっきり白紙で、今の５課題というものを含めながらお話しされているのかどうかという点が１点と。","respondent":"高橋区長","answer":"数字の点ですけど、これはもう理解の問題ですけど、５２％プラス７４５億円が平成１２年のときに都のほうから示され、それで財調は決まったと。それについて、東京都は、７４５億円は臨時的なもんだよと。","voiceIndex":21,"id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"いろいろご説明を大変わかりやすく拝聴しました。つまり、先ほども区長会と議長会、これは協力して訴えてもらって、それぞれの２３区基礎的自治体の財政自主権を初め自治権の拡充をやっていこうということのお話はされているわけで、この区長会として、いろいろな意味で温度差があるという話も伺っているところですが、非常に大事なポイントを今お話しされたんじゃないかなと。","respondent":"高橋区長","answer":"したがって、最終的にはそういうふうな方向に取り組まざるを得ないんじゃないのかなと、私がそう思って言っているわけでございまして、それについて２３区の区長に対しましてのコンセンサスはまだ得ていないわけですけど、私は、そういう方法しかないんじゃないかと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"本田委員","kind":"意見","question":"２３区長会の中でも、今リーダー的な立場で役割を果たしていくわけで、ただ、問題、指摘されている内容というのは、私は、今までの議論の枠を超えた主要５課題といいますか、財調が、仮に一定のめどが立った後、その後これでいいのかという次の問題が当然出てくるわけですが、今区長のおっしゃられることは、その次のことも眼中に置いて、いっそこの機会に基本的な問題に、言ってみれば本丸ですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"藤田委員","kind":"質問","question":"もう１点は、今の清掃一部事務組合の肥大化したそういう形じゃなくて、もっとスリム化したものをするべきだというふうになっているわけですが、今お話を聞きますと、まだ職員の採用等の課題が残っている中で、まだきちっとしては固まっていない中で、この第４回定例会に条例を本当に出せるのかどうか、この辺のお考えを伺いたいと思います。","respondent":"高橋区長","answer":"清掃の問題もあります。したがって、交渉していきますけど、今回の交渉の中で、私は、平成１８年にまとまることはなかなか難しいと思います。そのときに暫定的にどうしようかと。問題はこれから２３区で検討していく問題だと、そういうふうに思っております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"高星委員","kind":"意見","question":"今のことに関連するんですけども、確かに、清掃の現行の中での処遇の問題とかいろいろあるわけですけど、要するに心配しているのは、今区長のお話だと、９月１６日に交渉して、これ、相当力を入れてやってきて、これが１０月になって条例はかけられることという話だけど、その辺の見通しも、今のニュアンスですと見通しとしては厳しいのかなという感覚を持ったんですけど、一方、聞きますと。","respondent":"高橋区長","answer":"昨日、この清掃の問題につきまして、助役会でも考え方がかなり違いまして、平成１６年の、本来ならば、平成１５年度いっぱいは東京都で採用して区のほうに配属して、平成１６年度からは区で採用してやっていくということになりましたけど。","voiceIndex":28,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"最終的には、いわゆる政治的な決着というか、判断というか、そういうものを求めていかないと、本当の意味での解決というか、いい成果は得られないような。そもそもこの主要５課題の確認をしたところというのも、当時の区長会の会長と石原都知事とのやりとりの中で、ある種石原都知事の政治的判断のもとでこの５つの課題を認識しているという発言に結びついたと思うんです。","respondent":"高橋区長","answer":"だからこそ、各都議会の先生方にご支援をいただいて、都議会が議決をするわけですから、まず都議会の先生方にご理解いただいて、この問題を並行して進めていくことが必要だと。当然、この区議会の皆さん方にもご協力いただき、また一緒になってそこの問題を進めていく。","voiceIndex":30,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"しかし、もう時期がずっとこう来て、１０月になろうとしている状況なのに、まだまだ停滞状況ですよね、率直に言って。ですから、本当に東京都がどう思っているのかというところを、あえてきちっとつかんでいく必要が、私はつかみたいなと思っているので、その辺はどうなんでしょうか。","respondent":"高橋区長","answer":"今回の都区制度改革推進議員連盟が東京都に説明を求めたときも、３税は、これは都税ですと、区税でございません、都が供給している都税ですと、こういうことを言っていますが、これが、やはり東京都の本当の考え方かなという気がいたしました。それは都税かもしれません。","voiceIndex":32,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"そうであるならば、やっぱり私は税の問題だけで東京都と交渉するんじゃなくて、基本的な理念のところでしっかりと押さえて、両方でやっていかないといけないんじゃないかなと、進んでいかないんじゃないかなと思うんですね。ですから、ぜひ具体的な事務方の交渉と、それからトップの区長会のところの交渉というのを使い分けながらぜひともやっていただきたいというふうに思います。","respondent":"高橋区長","answer":"この固定資産税を税源というような問題を言いますとね、法改正しなくちゃできないんじゃないかというふうなことを必ず言うと思うんですが、法改正をしないで運用面で私はできると思っています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"築舘委員","kind":"意見","question":"その辺のことはどうなっているのかということと、それから、国がどの程度補助というか負担をしているのか、全部自前で、今各２３区が必要なものを全部出して、各区が行政需要に従って財政の負担をしているのかどうか、その辺の事情をちょっと聞かせてください。","respondent":"市岡企画財政課長","answer":"これらのことも、詳しく、いろんなところで訴えていきたいなというふうに考えております。","voiceIndex":41,"id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"国による規制緩和、都による規制緩和みたいなのがあって、そこら辺との関係は、少しは我々も知識として入れておかないと、誤解されちゃっても困るんで、ちょっとその辺のところ、何か目新しいところというか、わかりやすいところがあったらちょっと教えてもらいたいんですけど。","respondent":"市岡企画財政課長","answer":"しかし、当然、この国庫負担金、あるいは都の負担金の廃止というのは、各地方公共団体が自由な裁量でこういう児童福祉施設についても運営をしていくということが一方の使命になっているはずですから、今後はこういうことについても、もし国が非常に腰が重いようであれば。","voiceIndex":43,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"さっき区長の説明で、調整３税の固定資産税を税源移譲でという話は、初めて私ども、耳に入ってきた話なんだけども、その辺の２３区の、先ほど本田委員もちょっと懸念したんだけども、それをやると、今の絵よりも確かに上になってくるよという話になろうかと思うんですけども、そのあたりは、今まで事務方で、当局の役割がどうだ、何がどうだということではなくて。","respondent":"市岡企画財政課長","answer":"固定資産税という税源でもっと安定的な財政調整を都区間でやったらどうかというのは、これが品川区長の持論だということは、２３区の区長も、それから私どものような財政担当者も、みんなよく知っていることでございまして、ただ、このお考えを正式なといいますか。","voiceIndex":45,"id":"exchange-018"}]},{"id":"topic-02","title":"自治会館（仮称）の運営に関すること","agenda":"自治会館（仮称）の運営に関すること","exchanges":[{"speaker":"南委員","kind":"質問","question":"委員会が設置されたというのかしら、５月、改選されたときに、もう既に特定事件ということで、項目がはっきりしますよね、それでずっと一年間議論して、２月、３月ごろに、まとめて議長に報告をいつも出しますよね。その関係と今のまとめるというのはどういうことですか。","respondent":"石田委員長","answer":"今考えておりますのは、一定の理解はございまして、せっかくここまで今皆さんに議論いただいて、もし問題点もあったらということで、正副で、理事者も含めてやっています。","voiceIndex":49,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"この時期でまとめておく必要性、何のためかわからないんです、私自身、今説明を伺ってもね、ちょっと私のほうの理解が、能力不足でできないのかもしれないですけども、よくわからないんですよね。","respondent":"石田委員長","answer":"だから、問題点だけを取り上げるということではなく、逆に、今移転が粛々と進んだり、ほかのテナント部分のこともあったり、そういうことを含めて、一度、今まで我々が、そのような視察から議論をいただいた部分をまとめて、皆様に、一度、その共通の部分として。","voiceIndex":51,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"正副のほうで一定程度のものをまとめて次回出すと、こういうことなんですね。私は、逆にもっと意見を求められるのかなと思ったので。","respondent":"石田委員長","answer":"それでよろしいですか。今後も自治会館の運営につきましては、新たな動き等がありましたら、もちろん十分な情報提供はしますし、理事者にもお願いをしておきます。我々正副で取りまとめします。","voiceIndex":53,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5554#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":34976,"voices":59}}]);
